def get_resource_by_key(self, resource_key):
        """Return resource by quick_key/folder_key.

        key -- quick_key or folder_key
        """
        try:
            return self.resources[resource_key]  # type: ignore[index]
        except Exception:
            pass

        for resource in getattr(self, "resources", []):
            if isinstance(resource, dict):
                if resource.get("quick_key") == resource_key or resource.get("folder_key") == resource_key:
                    return resource
            else:
                if getattr(resource, "quick_key", None) == resource_key or getattr(resource, "folder_key", None) == resource_key:
                    return resource

        raise KeyError(f"Resource with key {resource_key!r} not found")

