def get_command(self, ctx, cmd_name):
        """ Allow for partial commands. """
        rv = click.Group.get_command(self, ctx, cmd_name)
        if rv is not None:
            return rv
        matches = [x for x in self.list_commands(ctx)
                   if x.startswith(cmd_name)]
        if not matches:
            return None
        elif len(matches) == 1:
            return click.Group.get_command(self, ctx, matches[0])
        ctx.fail('Command ambiguous, could be: %s' %
                 ', '.join(sorted(matches)))

mgc_code:
def get_command(self, ctx, cmd_name):
        """ Allow for partial commands. """
        # Try exact match first
        cmd = self.all_commands.get(cmd_name)
        if cmd:
            return cmd

        # Collect commands that match partially (by name or alias)
        matches = []
        for command in self.all_commands.values():
            if command.name.startswith(cmd_name):
                matches.append(command)
                continue
            for alias in getattr(command, "aliases", []):
                if alias.startswith(cmd_name):
                    matches.append(command)
                    break

        # Return the command if there is a single unambiguous match
        return matches[0] if len(matches) == 1 else None

