def process_request(self, request):
        """
        Store memory data to log later.
        """
        if not hasattr(self, "_memory"):
            self._memory = []
        # Store a copy if possible to avoid later mutation side‑effects
        if isinstance(request, dict):
            self._memory.append(request.copy())
        else:
            self._memory.append(request)

