mgc_code:
def load_py(stream, filepath=None):
    """Load python-formatted data from a stream.

    Args:
        stream (file-like object).

    Returns:
        dict.
    """
    import ast

    data = stream.read()
    if not data:
        return {}
    try:
        result = ast.literal_eval(data)
        if isinstance(result, dict):
            return result
    except Exception:
        pass
    namespace = {}
    try:
        exec(data, {}, namespace)
    except Exception as e:
        raise ValueError(f"Failed to load python data: {e}") from e
    if isinstance(namespace, dict):
        return namespace
    raise ValueError("Loaded data is not a dict")

