def load_verifying_key(verifying_key, crypto_backend=default_backend()):
    """ Optional: crypto backend object from the "cryptography" python library
    """
    if not isinstance(crypto_backend, (Backend, MultiBackend)):
        raise ValueError('backend must be a valid Backend object')

    if isinstance(verifying_key, EllipticCurvePublicKey):
        return verifying_key
    elif isinstance(verifying_key, (str, unicode)):
        try:
            return load_der_public_key(
                verifying_key, backend=crypto_backend)
        except:
            try:
                return load_pem_public_key(
                    verifying_key, backend=crypto_backend)
            except Exception:
                raise ValueError('Invalid verifying key format')
    else:
        raise ValueError('Invalid verification key type')

mgc_code:
def load_verifying_key(verifying_key, crypto_backend=default_backend()):
    """ Optional: crypto backend object from the "cryptography" python library
    """
    if hasattr(verifying_key, "public_bytes"):
        return verifying_key
    if isinstance(verifying_key, (str, bytes, bytearray)):
        if isinstance(verifying_key, str):
            try:
                with open(verifying_key, "rb") as f:
                    data = f.read()
            except Exception as e:
                raise ValueError(f"Unable to read verifying key file: {e}") from e
        else:
            data = bytes(verifying_key)
        from cryptography.hazmat.primitives import serialization
        try:
            return serialization.load_pem_public_key(data, backend=crypto_backend)
        except ValueError:
            try:
                return serialization.load_der_public_key(data, backend=crypto_backend)
            except ValueError as e:
                raise ValueError("Verifying key is not valid PEM or DER format") from e
    raise TypeError("verifying_key must be a public key object, PEM/DER bytes, or a file path")

