else:
    target_dir = os.path.abspath(os.path.dirname(file_path))
# Ensure the directory exists
if not os.path.isdir(target_dir):
    return False
# Get size of the file to be uploaded
try:
    file_size = os.path.getsize(file_path)
except OSError:
    return False
# Get free space on the target filesystem
try:
    usage = shutil.disk_usage(target_dir)
    free_space = usage.free
except OSError:
    return False
# If overwriting an existing file, adjust required space
if overwrite:
    # Assume the uploaded file would have the same name as the source file
    dest_path = os.path.join(target_dir, os.path.basename(file_path))
    if os.path.isfile(dest_path):
        try:
            existing_size = os.path.getsize(dest_path)
            # Overwrite frees up the existing size before writing the new one
            free_space += existing_size
        except OSError:
            pass
return free_space >= file_size

