def _send_direct_message_new(self, messageobject: Dict[str, Dict]) -> Any:
        """
        :reference: https://developer.twitter.com/en/docs/direct-messages/sending-and-receiving/api-reference/new-event.html
        """
        # Prefer a client‑provided request helper if available
        if hasattr(self, "_request"):
            response = self._request("POST", endpoint, json=messageobject)
        else:
            import requests

            headers = {}
            # If the client stores authentication info, try to use it
            if hasattr(self, "auth") and self.auth:
                # Assume auth is a requests‑compatible auth object or a dict with bearer token
                if isinstance(self.auth, dict) and "bearer_token" in self.auth:
                    headers["Authorization"] = f"Bearer {self.auth['bearer_token']}"
                else:
                    # Let requests handle the auth object directly
                    response = requests.post(
                        endpoint,
                        json=messageobject,
                        auth=self.auth,
                        headers=headers,
                    )
                    response.raise_for_status()
                    return response.json()
            response = requests.post(endpoint, json=messageobject, headers=headers)

        # Ensure HTTP errors raise exceptions
        if hasattr(response, "raise_for_status"):
            response.raise_for_status()
        # Return parsed JSON if possible, otherwise raw text
        try:
            return response.json()
        except ValueError:
            return response.text

