def Kdiag(self,X,target):
        """Compute the diagonal of the covariance matrix associated to X."""
        import numpy as np
        try:
            K = self.K(X, X, target)
        except TypeError:
            K = self.K(X, X)
        return np.diag(K)

def step4(self, encrypted_data):
        """Last pairing step."""
        # Attempt to decrypt the data using a cipher attribute if available.
        # If no cipher is present, simply return the input as‑is.
        cipher = getattr(self, "cipher", None)
        decrypt = getattr(cipher, "decrypt", None) if cipher is not None else None
        if callable(decrypt):
            return decrypt(encrypted_data)
        return encrypted_data

