mgc_code:
def run(self, callback=None, limit=0):
        """
        Start pcap's loop over the interface, calling the given callback for each packet
        :param callback: a function receiving (win_pcap, param, header, pkt_data) for each packet intercepted
        :param limit: how many packets to capture (A value of -1 or 0 is equivalent to infinity)
        """
        if callback is None:
            raise ValueError("callback must be provided")
        if not hasattr(self, "handle") or self.handle is None:
            raise RuntimeError("pcap handle is not initialized")
        # pcap.loop expects -1 for infinite capture
        count = -1 if limit <= 0 else int(limit)

        def _wrapper(header, pkt_data):
            # header is a pcap_pkthdr object; expose as is
            callback(self, getattr(self, "param", None), header, pkt_data)

        try:
            self.handle.loop(count, _wrapper)
        except KeyboardInterrupt:
            # Graceful stop on user interrupt
            pass
        finally:
            # Ensure the capture is stopped if the handle provides a breakloop method
            if hasattr(self.handle, "breakloop"):
                try:
                    self.handle.breakloop()
                except Exception:
                    pass

