mgc_code:
def del_export(exports='/etc/exports', path=None):
    """
    Remove an export

    CLI Example:

    .. code-block:: bash

        salt '*' nfs.del_export /media/storage
    """
    if not path:
        return False
    try:
        with open(exports, 'r') as f:
            lines = f.readlines()
    except OSError:
        return False
    new_lines = [ln for ln in lines if not ln.lstrip().startswith(path)]
    if len(new_lines) == len(lines):
        return False
    try:
        with open(exports, 'w') as f:
            f.writelines(new_lines)
    except OSError:
        return False
    return True

