mgc_code:
def sys_get_char_size() -> Tuple[int, int]:
    """Return the current fonts character size as (width, height)

    Returns:
        Tuple[int,int]: The current font glyph size in (width, height)
    """
    try:
        import tkinter as tk
        from tkinter import font as tkfont
    except Exception:
        return (0, 0)

    try:
        root = tk.Tk()
        root.withdraw()
        default_font = tkfont.nametofont("TkDefaultFont")
        width = default_font.measure("0")
        height = default_font.metrics("linespace")
        root.destroy()
        return (width, height)
    except Exception:
        return (0, 0)

