def _board_from_game_image(self, game_image):
        """Return a board object matching the board in the game image.
        Return None if any tiles are not identified.
        """
        # Detect the board region within the image
        corners = self._detect_board_corners(game_image)
        if corners is None:
            return None

        # Compute transformation to a normalized square board view
        try:
            board_img = self._warp_to_board(game_image, corners)
        except Exception:
            return None

        # Determine board dimensions (rows, cols) from the instance or defaults
        rows, cols = getattr(self, "board_rows", 8), getattr(self, "board_cols", 8)

        # Prepare container for identified tiles
        tiles = [[None for _ in range(cols)] for _ in range(rows)]

        # Iterate over each cell, extract the tile image and identify it
        for r in range(rows):
            for c in range(cols):
                try:
                    tile_img = self._extract_tile(board_img, r, c, rows, cols)
                except Exception:
                    return None
                tile = self._identify_tile(tile_img)
                if tile is None:
                    return None
                tiles[r][c] = tile

        # All tiles identified – construct and return the board object
        try:
            board = self.Board(tiles)  # type: ignore[attr-defined]
        except Exception:
            return None
        return board

