def SaveDataToFD(self, raw_data, fd):
    """Merge the raw data with the config file and store it."""
    import json

    def _deep_merge(dest, src):
        for key, value in src.items():
            if (
                key in dest
                and isinstance(dest[key], dict)
                and isinstance(value, dict)
            ):
                _deep_merge(dest[key], value)
            else:
                dest[key] = value

    # Ensure we have a base configuration dictionary
    base_config = getattr(self, "config", {})
    if not isinstance(base_config, dict):
        raise TypeError("self.config must be a dict")

    if not isinstance(raw_data, dict):
        raise TypeError("raw_data must be a dict")

    # Perform a deep merge of raw_data into the base configuration
    merged = dict(base_config)  # shallow copy to avoid mutating original
    _deep_merge(merged, raw_data)

    # Write the merged configuration to the provided file descriptor
    # Assume fd is a file-like object opened in text mode for writing
    json.dump(merged, fd, indent=2, sort_keys=True)
    fd.flush()

