def synchronize(self, graph_data=None):
        """
        Synchronize ``facebook_username``, ``first_name``, ``middle_name``,
        ``last_name`` and ``birthday`` with Facebook.

        :param graph_data: Optional pre-fetched graph data
        """
        import requests
        if graph_data is None:
            token = getattr(self, "facebook_access_token", None)
            if not token:
                raise ValueError("Facebook access token is required to fetch data")
            username = getattr(self, "facebook_username", None)
            if not username:
                raise ValueError("Facebook username is required to fetch data")
            url = f"https://graph.facebook.com/v12.0/{username}"
            params = {
                "fields": "first_name,middle_name,last_name,birthday",
                "access_token": token,
            }
            resp = requests.get(url, params=params, timeout=10)
            resp.raise_for_status()
            graph_data = resp.json()
        # Update fields if present in the response
        if "first_name" in graph_data:
            self.first_name = graph_data["first_name"]
        if "middle_name" in graph_data:
            self.middle_name = graph_data["middle_name"]
        if "last_name" in graph_data:
            self.last_name = graph_data["last_name"]
        if "birthday" in graph_data:
            self.birthday = graph_data["birthday"]
        return graph_data

