def reset(cls):
        """
        Reset the datasets and interface to default values.
        """
        # Reset datasets
        if hasattr(cls, "_default_datasets"):
            # Use a shallow copy to avoid mutating the original defaults
            cls.datasets = cls._default_datasets.copy()
        else:
            cls.datasets = {}

        # Reset interface
        if hasattr(cls, "_default_interface"):
            default = cls._default_interface
            # Preserve mutability semantics: copy dicts, otherwise assign directly
            cls.interface = default.copy() if isinstance(default, dict) else default
        else:
            cls.interface = None

        # Clear any auxiliary caches that might exist
        for attr in ("_cache", "_memo", "_registry"):
            if hasattr(cls, attr):
                setattr(cls, attr, {})

