def execute_once(self, string):
        """Execute only one rule."""
        for rule in self.rules:
            if rule[0] in string:
                pos = string.find(rule[0])
                self.last_rule = rule
                return string[:pos] + rule[1] + string[pos+len(rule[0]):]
        self.last_rule = None
        return string

mgc_code:
def execute_once(self, string):
        """Execute only one rule."""
        if not hasattr(self, "_executed"):
            self._executed = set()
        if string in self._executed:
            return None
        # Try to locate the rule: attribute, then dict entry, then method named `run_<string>`
        rule = getattr(self, string, None)
        if rule is None and hasattr(self, "rules"):
            rule = self.rules.get(string)
        if rule is None:
            rule = getattr(self, f"run_{string}", None)
        if not callable(rule):
            raise AttributeError(f"No executable rule found for '{string}'")
        self._executed.add(string)
        return rule()

