    if not isinstance(activeMinicolumns, np.ndarray):
        raise TypeError("activeMinicolumns must be a numpy array")
    if activeMinicolumns.dtype.kind not in {"i", "u"}:
        raise ValueError("activeMinicolumns must contain integer indices")

    # Store the active minicolumns for possible later use
    self._last_active_minicolumns = activeMinicolumns.copy()

    # Learning step: if the class provides a learning hook, invoke it
    if learn:
        learn_method = getattr(self, "_learn_association", None)
        if callable(learn_method):
            learn_method(activeMinicolumns)

    # Prepare logging/tracing dictionaries
    log_info = {
        "active_minicolumns": activeMinicolumns.tolist(),
        "num_active": int(activeMinicolumns.size),
    }
    learn_info = {
        "learn": bool(learn),
    }

    return (log_info, learn_info)

