def normalizeXpath(xpath):
    """ Normalize XPATH split around slashes

    :param xpath: List of xpath elements
    :type xpath: [str]
    :return: List of refined xpath
    :rtype: [str]
    """
    parts = []
    for elem in xpath:
        if not isinstance(elem, str):
            continue
        for sub in elem.split('/'):
            if sub:
                parts.append(sub)
    return parts

