mgc_code:
def refuse_transfer(transfer, comment=None):
    """Refuse an incoming a transfer request"""
    if not hasattr(transfer, "status"):
        raise AttributeError("Transfer object must have a 'status' attribute")
    if getattr(transfer, "status") not in {"pending", "requested"}:
        raise ValueError(f"Cannot refuse a transfer with status {getattr(transfer, 'status')}")
    transfer.status = "refused"
    if comment is not None:
        if hasattr(transfer, "comments"):
            try:
                transfer.comments.append(comment)
            except Exception:
                if isinstance(transfer.comments, str):
                    transfer.comments = transfer.comments + "\n" + comment
                else:
                    transfer.comments = [comment]
        else:
            transfer

