def filter(self, **kwargs):
        """
        Returns a list of statements in the database
        that match the parameters specified.
        """
        result = []
        # If no filters provided, return all statements
        if not kwargs:
            return list(getattr(self, "_statements", []))
        for stmt in getattr(self, "_statements", []):
            match = True
            for key, value in kwargs.items():
                # Support dict-like statements
                if isinstance(stmt, dict):
                    if stmt.get(key) != value:
                        match = False
                        break
                else:
                    if getattr(stmt, key, None) != value:
                        match = False
                        break
            if match:
                result.append(stmt)
        return result

