def ensure_str(s, encoding="utf-8", errors="strict"):
    """Coerce *s* to `str`.

    To keep six with lower version, see Issue 4169, we copy this function
    from six == 1.12.0.

    TODO(yuhguo): remove this function when six >= 1.12.0.

    For Python 2:
      - `unicode` -> encoded to `str`
      - `str` -> `str`

    For Python 3:
      - `str` -> `str`
      - `bytes` -> decoded to `str`
    """
    import sys
    # Python 2 compatibility: get unicode type if exists
    try:
        unicode_type = unicode  # type: ignore
    except NameError:
        unicode_type = None

    # Fast path for common cases
    if isinstance(s, str):
        return s
    # In Python 2, unicode should be encoded to str
    if unicode_type is not None and isinstance(s, unicode_type):
        return s.encode(encoding, errors)
    # Bytes (or bytearray) should be decoded to str
    if isinstance(s, (bytes, bytearray)):
        return s.decode(encoding, errors)
    # Fallback: use built‑in str conversion
    return str(s)

