def find_child_element(elm, child_local_name):
    """
    Find an XML child element by local tag name.
    """
    for child in elm:
        tag = child.tag
        if isinstance(tag, str):
            local = tag.split('}', 1)[1] if tag.startswith('{') else tag
            if local == child_local_name:
