mgc_code:
def list_object_versions(Bucket, Delimiter=None, EncodingType=None, Prefix=None,
                 region=None, key=None, keyid=None, profile=None):
    """
    List objects in a given S3 bucket.

    Returns a list of objects.

    CLI Example:

    .. code-block:: bash

        salt myminion boto_s3_bucket.list_object_versions mybucket

    """
    import boto3
    session_kwargs = {}
    if profile:
        session_kwargs["profile_name"] = profile
    if region:
        session_kwargs["region_name"] = region
    if keyid and key:
        session_kwargs["aws_access_key_id"] = keyid
        session_kwargs["aws_secret_access_key"] = key
    session = boto3.session.Session(**session_kwargs)
    client = session.client("s3")
    paginator = client.get_paginator("list_object_versions")
    paginate_kwargs = {"Bucket": Bucket}
    if Delimiter is not None:
        paginate_kwargs["Delimiter"] = Delimiter
    if EncodingType is not None:
        paginate_kwargs["EncodingType"] = EncodingType
    if Prefix is not None:
        paginate_kwargs["Prefix"] = Prefix
    versions = []
    for page in paginator.paginate(**paginate_kwargs):
        versions.extend(page.get("Versions", []))
        versions.extend(page.get("DeleteMarkers", []))
    return versions

