def is_provider_configured(opts, provider, required_keys=(), log_message=True, aliases=()):
    """
    Check and return the first matching and fully configured cloud provider
    configuration.
    """
    for name in (provider,) + tuple(aliases):
        cfg = opts.get(name)
        if not isinstance(cfg, dict):
            continue
        if all(key in cfg and cfg[key] for key in required_keys):
            return cfg
    if log_message:
        print(f"Provider '{provider}' is not configured or missing required keys: {required_keys}")
    return None

