mgc_code:
def GetConfigFromTemplate(self, template_path):
    """Apply build.yaml settings from the template."""
    import yaml
    from pathlib import Path

    tmpl_path = Path(template_path)
    if not tmpl_path.is_file():
        raise FileNotFoundError(f"Template file not found: {template_path}")

    with tmpl_path.open('r', encoding='utf-8') as f:
        try:
            data = yaml.safe_load(f)
        except yaml.YAMLError as e:
            raise ValueError(f"Failed to parse YAML template '{template_path}': {e}")

    if not isinstance(data, dict):
        raise ValueError(f"Template '{template_path}' must contain a mapping at top level.")

    if hasattr(self, "config") and isinstance(self.config, dict):
        self.config.update(data)
    else:
        self.config = data

    return data

