def logout(self):
        """ Logout from the remote account

        :return: None
        """
        try:
            # Determine logout endpoint
            url = getattr(self, "logout_url", None)
            if not url:
                base = getattr(self, "base_url", "")
                url = f"{base.rstrip('/')}/logout"
            # Perform logout request if a session exists
            if getattr(self, "session", None):
                self.session.post(url, timeout=10).raise_for_status()
        except Exception:
            # Silently ignore any logout errors
            pass
        finally:
            # Clean up the session object
            sess = getattr(self, "session", None)
            if sess:
                try:
                    sess.close()
                except Exception:
                    pass
            self.session = None

