def inurl(needles, haystack, position='any'):
    """convenience function to make string.find return bool"""

    count = 0

    # lowercase everything to do case-insensitive search
    haystack2 = haystack.lower()

    for needle in needles:
        needle2 = needle.lower()
        if position == 'any':
            if haystack2.find(needle2) > -1:
                count += 1
        elif position == 'end':
            if haystack2.endswith(needle2):
                count += 1
        elif position == 'begin':
            if haystack2.startswith(needle2):
                count += 1

    # assessment
    if count > 0:
        return True
    return False

mgc_code:
def inurl(needles, haystack, position='any'):
    """convenience function to make string.find return bool"""
    if position not in ('any', 'start', 'end'):
        raise ValueError("position must be 'any', 'start', or 'end'")
    def _check(needle):
        if not isinstance(needle, str):
            raise TypeError('needles must be str or iterable of str')
        if position == 'any':
            return haystack.find(needle) != -1
        if position == 'start':
            return haystack.startswith(needle)
        return haystack.endswith(needle)
    if isinstance(needles, str):
        return _check(needles)
    try:
        iterator = iter(needles)
    except TypeError:
        raise TypeError('needles must be str or iterable of str')
    return any(_check(n) for n in iterator)

