import inspect
calls = []
for name, func in getattr(self, "_methods", {}).items():
    try:
        sig = inspect.signature(func)
        parts = []
        for param in sig.parameters.values():
            if param.default is param.empty:
                parts.append(param.name)
            else:
                parts.append(f"{param.name}={repr(param.default)}")
        args_str = ", ".join(parts)
    except (ValueError, TypeError):
        # Fallback if signature cannot be obtained
        args_str = ""
    calls.append(f"{tab}{name}({args_str})")
return calls

