def _item_type(item):
    """Indicate to the ODF reader the type of the block or text."""
    tag = item['tag']
    style = item.get('style', None)
    if tag == 'p':
        if style is None or 'paragraph' in style:
            return 'paragraph'
        else:
            return style
    elif tag == 'span':
        if style in (None, 'normal-text'):
            return 'text'
        elif style == 'url':
            return 'link'
        else:
            return style
    elif tag == 'h':
        assert style is not None
        return style
    elif tag in ('list', 'list-item', 'line-break'):
        if style == '_numbered_list':
            return 'numbered-list'
        else:
            return tag
    elif tag == 's':
        return 'spaces'
    raise Exception("The tag '{0}' with style '{1}' hasn't "
                    "been implemented.".format(tag, style))

mgc_code:
def _item_type(item):
    """Indicate to the ODF reader the type of the block or text."""
    # Determine type based on common ODF element patterns
    # 1. lxml/Element objects have a .tag attribute (possibly with namespace)
    # 2. Simple Python containers have obvious types
    # 3. Fallback to the class name in lower case
    if item is None:
        return None
    # Strings represent plain text
    if isinstance(item, str):
        return "text"
    # Containers
    if isinstance(item, (list, tuple, set)):
        return "list"
    if isinstance(item, dict):
        return "dict"
    # lxml-like element with .tag
    tag = getattr(item, "tag", None)
    if tag is not None:
        # tag may be '{namespace}localname'
        if isinstance(tag, str):
            if "}" in tag:
                tag = tag.split("}", 1)[1]
            return tag.lower()
    # Objects that expose a .type attribute
    typ = getattr(item, "type", None)
    if typ:
        return str(typ).lower

