mgc_code:
def cmd_extract_email(infile, verbose, jsonout):
    """Extract email addresses from a file or stdin.

    Example:

    \b
    $ cat /var/log/auth.log | habu.extract.email
    john@securetia.com
    raven@acmecorp.net
    nmarks@fimax.com
    """
    import sys, re, json
    # Determine input source
    if infile and infile != "-":
        try:
            f = open(infile, "r", encoding="utf-8", errors="ignore")
        except Exception as e:
            sys.stderr.write(f"Error opening file {infile}: {e}\n")
            return
    else:
        f = sys.stdin

    # Regex for email addresses
    email_regex = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")

    seen = set()
    emails = []
    for line in f:
        for match in email_regex.findall(line):
            if match not in seen:
                seen.add(match)
                emails.append(match)

    if f is not sys.stdin:
        f.close()

    if jsonout:
        sys.stdout.write(json.dumps(emails, ensure_ascii=False))
        sys.stdout.write("\n")
    else:
        for e in emails:
            sys.stdout.write(e + "\n")

    if verbose:
        sys.stderr.write(f"Found {len(emails)} unique email address{'es' if len(emails)!=1 else ''}.\n")

