def search_datasets(self):
        """
        Returns an iterator over the Datasets on the server.

        :return: An iterator over the :class:`ga4gh.protocol.Dataset`
            objects on the server.
        """
        request = {}
        while True:
            response = self.client.search_datasets(**request)
            for dataset in getattr(response, "datasets", []):
                yield dataset
            next_token = getattr(response, "next_page_token", None)
            if not next_token:
                break
            request["page_token"] = next_token

