mgc_code:
def lines(text):
    """
    Generator function to yield lines (delimited with ``'\n'``) stored in
    ``text``. This is useful when a regular expression should only match on a
    per line basis in a memory efficient way.
    """
    start = 0
    for i, ch in enumerate(text):
        if ch == '\n':
            yield text[start:i]
            start = i + 1
    if start <= len(text):
        yield text[start:]

