mgc_code:
def kick_idle():
    """
    Looks for idle clients and disconnects them by setting active to False.
    """
    import time
    # Retrieve the collection of clients; support common naming conventions.
    clients = globals().get("clients") or globals().get("CLIENTS")
    if not clients:
        return
    # Idle timeout in seconds; allow override via a global constant.
    idle_timeout = globals().get("IDLE_TIMEOUT", 300)
    now = time.time()
    for client in clients:
        try:
            # Expect each client to be a mutable mapping with 'active' and 'last_active'.
            if client.get("active", True) and now - client.get("last_active", now) > idle_timeout:
                client["active"] = False
        except Exception:
            # Silently ignore malformed client entries.
            continue

