mgc_code:
def timestamp_normalized(self):
        """
        we're expecting self.timestamp to be either a long, int, a datetime, or a timedelta
        :return:
        """
        from datetime import datetime, timedelta
        ts = self.timestamp
        if isinstance(ts, datetime):
            return ts
        if isinstance(ts, timedelta):
            return datetime.utcnow() + ts
        if isinstance(ts, (int, float)):
            try:
                return datetime.utcfromtimestamp(ts)
            except (OSError, OverflowError, ValueError):
                # Fallback for timestamps that may be in milliseconds
                return datetime.utcfromtimestamp(ts / 1000.0)
        raise TypeError(f"Unsupported timestamp type: {type(ts)!r}")

