def round(self, multiple=1):
        """
        Rounds the kerning values to increments of **multiple**,
        which will be an ``int``.

        The default behavior is to round to increments of 1.
        """
        if not isinstance(multiple, int):
            raise TypeError("multiple must be an int")
        if multiple == 0:
            raise ValueError("multiple must not be zero")
        # Assume kerning data is stored in a dict-like attribute `kerning`
        # where values are numeric (int or float).
        kerning = getattr(self, "kerning", None)
        if kerning is None:
            raise AttributeError("object has no attribute 'kerning'")
        for key, value in kerning.items():
            if isinstance(value, (int, float)):
                kerning[key] = round(value / multiple) * multiple
        return self

