def sort(self, **kwargs):
        """
        Adds a sort stage to aggregation query
        :param kwargs: Specifies the field(s) to sort by and the respective sort order.
        :return: The current object
        """
        sort_stage = {}
        for field, order in kwargs.items():
            if isinstance(order, str):
                order_lower = order.lower()
                if order_lower in ("asc", "ascending", "1"):
                    sort_stage[field] = 1
                elif order_lower in ("desc", "descending", "-1"):
                    sort_stage[field] = -1
                else:
                    raise ValueError(f"Invalid sort order string: {order}")
            elif isinstance(order, (int, float)):
                if order > 0:
                    sort_stage[field] = 1
                elif order < 0:
                    sort_stage[field] = -1
                else:
                    raise ValueError(f"Sort order numeric value cannot be zero for field '{field}'")
            else:
                raise TypeError(f"Sort order for field '{field}' must be str or numeric, got {type(order)}")
        if sort_stage:
            if not hasattr(self, "_pipeline"):
                self._pipeline = []
            self._pipeline.append({"$sort": sort_stage})
        return self

