def _found_barcode(self, record, sample, barcode=None):
        """Hook called when barcode is found"""
        # Determine barcode if not explicitly provided
        if barcode is None:
            # Try attribute access on record
            barcode = getattr(record, "barcode", None)
            # Fallback to mapping access
            if barcode is None:
                try:
                    barcode = record["barcode"]
                except Exception:
                    barcode = None

        # Store the barcode in the sample object/dict if we have one
        if barcode is not None:
            if isinstance(sample, dict):
                sample["barcode"] = barcode
            else:
                try:
                    setattr(sample, "barcode", barcode)
                except Exception:
                    pass

        return barcode

