def _call(self, f, out):
        """Implement ``self(f, out)``."""
        if f is None:
            return out
        if isinstance(f, (list, tuple)):
            for func in f:
                out = self._call(func, out)
            return out
        if callable(f):
            return f(out)
        raise TypeError("f must be callable or an iterable of callables")

