mgc_code:
def dt_comp(self, sampled_topics):

        """
        Compute document-topic matrix from sampled_topics.
        """
        # Determine number of topics
        if hasattr(self, 'num_topics'):
            K = self.num_topics
        else:
            K = max((t for doc in sampled_topics for t in doc), default=-1) + 1
        D = len(sampled_topics)
        import numpy as np
        dt = np.zeros((D, K), dtype=int)
        for d, topics in enumerate(sampled_topics):
            for t in topics:
                dt[d, t] += 1
        return dt

