def file_or_token(value):
    """
    If value is a file path and the file exists its contents are stripped and returned,
    otherwise value is returned.
    """
    import os
    from pathlib import Path

    # Determine if value can be interpreted as a path
    is_path = isinstance(value, (str, bytes, os.PathLike))
    if is_path:
        try:
            path = Path(value)
            if path.is_file():
                # Read file contents as text, strip whitespace, and return
                return path.read_text(encoding="utf-8").strip()
        except Exception:
            # If any error occurs (e.g., decoding), fall back to returning original value
            pass
    return value

