mgc_code:
def iob2json(input_data, n_sents=10, *args, **kwargs):
    """
    Convert IOB files into JSON format for use with train cli.
    """
    import os, json
    # Determine source of IOB data
    if hasattr(input_data, "read"):
        content = input_data.read()
    elif isinstance(input_data, (str, bytes)) and os.path.exists(str(input_data)):
        with open(input_data, "r", encoding="utf-8") as f:
            content = f.read()
    else:
        content = str(input_data)

    sentences = []
    tokens, tags = [], []
    for line in content.splitlines():
        line = line.strip()
        if not line:
            if tokens:
                sentences.append({"tokens": tokens, "labels": tags})
                tokens, tags = [], []
            continue
        parts = line.split()
        if len(parts) < 2:
            # ignore malformed lines
            continue
        token, tag = parts[0], parts[-1]
        tokens.append(token)
        tags.append(tag)
    # capture trailing sentence
    if tokens:
        sentences.append({"tokens": tokens, "labels": tags})

    # limit number of sentences
    if n_sents is not None:
        sentences = sentences[:n_sents]

    return json.dumps(sentences, ensure_ascii=False)

