def set_acl(self, role, users):
        """Set permissions for this method.

        Args:
            role (str): Access level
                one of {one of "OWNER", "READER", "WRITER", "NO ACCESS"}
            users (list(str)): List of users to give role to
        """
        allowed_roles = {"OWNER", "READER", "WRITER", "NO ACCESS"}
        if role not in allowed_roles:
            raise ValueError(f"Invalid role '{role}'. Must be one of {sorted(allowed_roles)}.")
        if not isinstance(users, (list, tuple, set)):
            raise TypeError("users must be a list, tuple, or set of strings.")
        for u in users:
            if not isinstance(u, str):
                raise TypeError(f"User identifiers must be strings, got {type(u).__name__}.")
        if not hasattr(self, "_acl") or not isinstance(self._acl, dict):
            self._acl = {}
        # Store a copy to avoid external mutation
        self._acl[role] = set(users)

