def add(self, name, value):
        """
        Adds a new entry to the table

        We reduce the table size if the entry will make the
        table size greater than maxsize.
        """
        # Ensure the table attribute exists
        if not hasattr(self, "table"):
            raise AttributeError("Object has no attribute 'table'")
        # Ensure maxsize attribute exists and is a positive integer
        if not hasattr(self, "maxsize") or not isinstance(self.maxsize, int) or self.maxsize <= 0:
            raise ValueError("Invalid or missing 'maxsize' attribute")
        # Update existing entry and move it to the end if possible (preserve order)
        if name in self.table:
            self.table[name] = value
            try:
                self.table.move_to_end(name)  # type: ignore[attr-defined]
            except Exception:
                pass

