mgc_code:
def lookup_extrapolation(x, xs, ys):
    """
    Intermediate values are calculated with linear interpolation between the intermediate points.
    Out-of-range values are calculated with linear extrapolation from the last two values at either end.
    """
    import bisect

    if len(xs) < 2:
        raise ValueError("xs must contain at least two points")
    # Ensure xs is sorted; if not, raise error
    if any(xs[i] > xs[i + 1] for i in range(len(xs) - 1)):
        raise ValueError("xs must be sorted in ascending order")
    # Exact match
    try:
        idx = xs.index(x)
        return ys[idx]
    except ValueError:
        pass

    if x < xs[0]:
        i0, i1 = 0, 1
    elif x > xs[-1]:
        i0, i1 = -2, -1
    else:
        # bisect_right returns insertion point to the right of existing entries
        i1 = bisect.bisect_right(xs, x)
        i0 = i1 - 1

    x0, x1 = xs[i0], xs[i1]
    y0, y1 = ys[i0], ys[i1]

    if x1 == x0:
        raise ZeroDivisionError("Two xs values are equal, cannot compute slope")
    slope = (y1 - y0) / (x1 - x0)
    return y0 + slope * (x - x0)

