def _set_unique_id(self, json_response):
        """
        Sets the unique_id provided a json response.

        Args:
            json_response:
        """
        if not isinstance(json_response, dict):
            raise TypeError("json_response must be a dict")
        # Prefer 'unique_id' key; fallback to common alternatives
        for key in ("unique_id", "uniqueId", "id"):
            if key in json_response:
                self.unique_id = json_response[key]
                break
        else:
            self.unique_id = None
        return self.unique_id

