def clear_cached_values(self):
        """Removes all of the cached values and interpolators
        """
        # Clear common cache containers if they exist
        for name in ("_cached_values", "_interpolators"):
            if hasattr(self, name):
                container = getattr(self, name)
                # If it's a mutable collection, empty it in‑place
                if isinstance(container, (dict, list, set)):
                    container.clear()
                # Otherwise replace with a fresh empty container of the same type
                else:
                    try:
                        empty = type(container)()
                    except Exception:
                        empty = None
                    setattr(self, name, empty)

