def removeIndexOnAttribute(self, attributeName):
        """
            removeIndexOnAttribute - Remove an attribute from indexing (for getElementsByAttr function) and remove indexed data.

        @param attributeName <lowercase str> - An attribute name. Will be lowercased. "name" and "id" will have no effect.
        """
        attributeName = attributeName.lower()
        if attributeName in ("name", "id"):
            return
        # Remove from attribute index tracking if present
        if hasattr(self, "_indexedAttributes"):
            idx = getattr(self, "_indexedAttributes")
            try:
                if isinstance(idx, set):
                    idx.discard(attributeName)
                else:
                    idx.pop(attributeName, None)
            except Exception:
                pass
        # Remove any stored indexed data for the attribute
        if hasattr(self, "_indexData"):
            try:
                self._indexData.pop(attributeName, None)
            except Exception:
