def mix(color1, color2, pos=0.5):
    """
    Return the mix of two colors at a state of :pos:

    Retruns color1 * pos + color2 * (1 - pos)
    """
    if isinstance(color1, (list, tuple)) and isinstance(color2, (list, tuple)):
        if len(color1) != len(color2):
            raise ValueError("color1 and color2 must have the same length")
        return tuple(c1 * pos + c2 * (1 - pos) for c1, c2 in zip(color1, color2))
    return color1 * pos + color2 * (1 - pos)

