def fulltext_add(self, index, docs):
        """
        Adds documents to the search index.
        """
        # Normalize docs to an iterable
        if not isinstance(docs, (list, tuple, set)):
            docs = [docs]
        added = 0
        for doc in docs:
            # If the index provides a Whoosh‑like API
            if hasattr(index, "add_document"):
                index.add_document(**doc)
            # Simple dict‑based index
            elif isinstance(index, dict):
                doc_id = doc.get("id")
                if doc_id is None:
                    raise ValueError("Document missing required 'id' field")
                index[doc_id] = doc

