def get_download_progress(self):
        """Returns tuple with download progress (for optional DLCs):

            (bytes_downloaded, bytes_total)

        :rtype: tuple
        """
        # Attempt to retrieve progress attributes; fall back to defaults
        downloaded = getattr(self, "bytes_downloaded", None)
        total = getattr(self, "bytes_total", None)

        if downloaded is None or total is None:
            # Support legacy attribute storing a dict with keys 'downloaded' and 'total'
            progress = getattr(self, "_dlc_progress", {})
            if isinstance(progress, dict):
                downloaded = progress.get("downloaded", 0)
                total = progress.get("total", 0)
            else:
                downloaded, total = 0, 0

        # Ensure integer return values
        try:
            downloaded = int(downloaded)
        except Exception:
            downloaded = 0
        try:
            total = int(total)
        except Exception:
            total = 0

        return (downloaded, total)

