def getWinner(self, type = 'activation'):
        """
        Returns the winner of the type specified {'activation' or
        'target'}.
        """
        if type not in ('activation', 'target'):
            raise ValueError("type must be 'activation' or 'target'")
        # Prefer a pre‑computed winner attribute
        winner_attr = f"{type}_winner"
        if hasattr(self, winner_attr):
            return getattr(self, winner_attr)
        # Fallback to a score container attribute
        scores = getattr(self, type, None)
        if scores is None:
            raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{type}'")
        # Support dict, list of (key, value), or any iterable of pairs
        if isinstance(scores, dict):
            if not scores:
                return None
            return max(scores, key=scores.get)
        try:
            # Assume iterable of (key, value)
            iterator = iter(scores)
            max_key = None
            max_val = None
            for item in iterator:
                if not isinstance(item, (list, tuple)) or len(item) != 2:
                    continue
                key, val = item
                if max_val is None or val > max_val:
                    max_key, max_val = key, val
            return max_key
        except TypeError:
            raise TypeError(f"Unsupported score container type for '{type}'")

