def unassign(pid_type, pid_value):
    """Unassign persistent identifier."""
    global _PID_REGISTRY
    if '_PID_REGISTRY' not in globals():
        _PID_REGISTRY = {}
    if not isinstance(pid_type, str):
        raise TypeError("pid_type must be a string")
