import base64

if not auth:
    return {}

# If auth is already a dict of headers, return it directly
if isinstance(auth, dict):
    return auth

# Tuple or list of (username, password) for Basic auth
if isinstance(auth, (list, tuple)) and len(auth) == 2:
    user, pwd = auth
    token = base64.b64encode(f"{user}:{pwd}".encode()).decode()
    return {"Authorization": f"Basic {token}"}

# String token – assume Bearer if not already prefixed
if isinstance(auth, str):
    if auth.lower().startswith("bearer "):
        return {"Authorization": auth}
    if auth.lower().startswith("basic "):
        return {"Authorization": auth}
    # Fallback to Bearer token
    return {"Authorization": f"Bearer {auth}"}

# Fallback: try to extract known keys from generic objects
