        # String token – assume Bearer if not already prefixed
        if isinstance(auth, str):
            if auth.lower().startswith("bearer "):
                return {"Authorization": auth}
            if auth.lower().startswith("basic "):
                return {"Authorization": auth}
            # Fallback to Bearer token
            return {"Authorization": f"Bearer {auth}"}

        # Fallback: try to extract known keys from generic objects
        try:
            auth_dict = dict(auth)
            return auth_dict
        except Exception:
            raise TypeError("Unsupported auth type: must be dict, tuple/list of (user, pass), or string token")

