import json

# Allow JSON string input
if isinstance(keyset, str):
    try:
        keyset = json.loads(keyset)
    except Exception as exc:
        raise ValueError("Invalid JSON string for keyset") from exc

if not isinstance(keyset, dict):
    raise TypeError("keyset must be a dict or JSON string")

# RFC 7517 requires a top‑level "keys" member containing an array
keys = keyset.get("keys")
if not isinstance(keys, list):
    raise ValueError('RFC 7517 keyset must contain a "keys" array')

# Prepare storage for imported keys
imported = {}
for idx, jwk in enumerate(keys):
    if not isinstance(jwk, dict):
        raise ValueError(f"Key at index {idx} is not a JSON object")
    kid = jwk.get("kid")
    # Use kid if present, otherwise fallback to index‑based identifier
    identifier = kid if isinstance(kid, str) else f"key-{idx}"
    if identifier in imported:
        raise ValueError(f"Duplicate key identifier '{identifier}' in keyset")
    imported[identifier] = jwk

# Store the processed keyset on the instance
self._jwk_set = {"keys": list(imported.values())}
self._keys_by_kid = imported
return self

