mgc_code:
def code2color(color_string):
    """Returns wx.Colour from a string of a 3-tuple of floats in [0.0, 1.0]"""
    import wx
    s = color_string.strip()
    if s.startswith('(') and s.endswith(')'):
        s = s[1:-1]
    parts = [p.strip() for p in s.split(',')]
    if len(parts) != 3:
        raise ValueError(f"Invalid color string: {color_string}")
    try:
        floats = [float(p) for p in parts]
    except Exception as e:
        raise ValueError(f"Invalid numeric values in color string: {color_string}") from e
    for f in floats:
        if not (0.0 <= f <= 1.0):
            raise ValueError(f"Color component {f} out of range [0.0, 1.0]")
    rgb = [int(round(f * 255)) for f in floats]
    return wx.Colour(*rgb)

