mgc_code:
def lines_from_stream(chunks):
    """
    Given data in chunks, yield lines of text
    """
    buffer = ""
    for chunk in chunks:
        buffer += chunk
        while True:
            newline_index = buffer.find("\n")
            if newline_index == -1:
                break
            line = buffer[:newline_index]
            buffer = buffer[newline_index + 1 :]
            yield line
    if buffer:
        yield buffer

