def _equivalent(self, other):
    """Compare two entities of the same class, excluding keys."""
    if not isinstance(other, self.__class__):
        return False
    keys = getattr(self, "_keys", [])
    self_attrs = {k: v for k, v in vars(self).items() if k not in keys}
    other_attrs = {k: v for k, v in vars(other).items() if k not in keys}
    return self_attrs == other_attrs

