def __eval_validator_check(self, check_item, resp_obj):
        """ evaluate check item in validator.

        Args:
            check_item: check_item should only be the following 5 formats:
                1, variable reference, e.g. $token
                2, function reference, e.g. ${is_status_code_200($status_code)}
                3, dict or list, maybe containing variable/function reference, e.g. {"var": "$abc"}
                4, string joined by delimiter. e.g. "status_code", "headers.content-type"
                5, regex string, e.g. "LB[\d]*(.*)RB[\d]*"

            resp_obj: response object

        """
        # Helper to resolve a dotted path on resp_obj (attributes or dict keys)
        def _resolve_path(path):
            parts = path.split('.')
            cur = resp_obj
            for p in parts:
                if isinstance(cur, dict):
                    cur = cur.get(p)
                else:
                    cur = getattr(cur, p, None)
                if cur is None:
                    break
            return cur

        # Evaluate a single item (could be variable, function, or plain value)
        def _eval(item):
            # Variable reference: $var or $var.sub
            if isinstance(item, str) and item.startswith('$') and not item.startswith('${'):
                return _resolve_path(item[1:])

def visit_assign(self, node, parent):
        """visit a Assign node by returning a fresh instance of it"""
        new_targets = [self.visit(t, node) for t in node.targets]
        new_value = self.visit(node.value, node)
        new_node = ast.Assign(
            targets=new_targets,
            value=new_value,
            type_comment=getattr(node, "type_comment", None),
        )
        for attr in ("lineno", "col_offset", "end_lineno", "end_col_offset"):
            if hasattr(node, attr):
                setattr(new_node, attr, getattr(node, attr))
        return new_node

