mgc_code:
def index(self, collection, docs, params=None, min_rf=None, **kwargs):
        """
        :param str collection: The name of the collection for the request.
        :param docs list docs: List of dicts. ex: [{"title": "testing solr indexing", "id": "test1"}]
        :param min_rf int min_rf: Required number of replicas to write to'

        Sends supplied list of dicts to solr for indexing.  ::

            >>> docs = [{'id':'changeme','field1':'value1'}, {'id':'changeme1','field2':'value2'}]
            >>> solr.index('SolrClient_unittest', docs)

        """
        # Build the update URL for the given collection
        url = f"{self.base_url.rstrip('/')}/{collection}/update"
        # Merge any explicit params with min_rf if provided
        query = {}
        if params:
            query.update(params)
        if min_rf is not None:
            query["min_rf"] = min_rf
        # Prepare request headers
        headers = {"Content-Type": "application/json"}
        # Send the documents to Solr
        response = self.session.post(url, params=query, json=docs, headers=headers, **kwargs)
        # Raise an error for non‑successful status codes
        if not response.ok:
            raise RuntimeError(
                f"Solr indexing failed (status {response.status_code}): {response.text}"
            )
        # Return the parsed JSON response (or raw text if not JSON)
        try:
            return response.json()
        except ValueError:
            return response.text

