mgc_code:
def FindNotNaNBackwards(x, i):
    """Returns last position (starting at i backwards) which is not NaN, or -1."""
    import math
    try:
        import numpy as _np
    except Exception:
        _np = None

    def _is_nan(val):
        if isinstance(val, float):
            return math.isnan(val)
        if _np is not None and isinstance(val, _np.generic):
            return _np.isnan(val)
        return False

    n = len(x)
    if i >= n:
        i = n - 1
    if i < 0:
        return -1
    for j in range(i, -1, -1):
        if not _is_nan(x[j]):
            return j
    return -1

