def delete_fw(self, tenant_id, data):
        """Top level routine called when a FW is deleted. """
        fw_id = data.get('id') or data.get('fw_id')
        if not fw_id:
            raise ValueError("Firewall identifier missing in data")
        try:
            result = self.client.delete_firewall(tenant_id, fw_id)
        except Exception as exc:
            self.logger.error(
                "Failed to delete firewall %s for tenant %s: %s",
                fw_id,
                tenant_id,
                exc,
            )
            raise
        self.logger.info("Deleted firewall %s for tenant %s", fw_id, tenant_id)
        return {"status": "deleted", "firewall_id": fw_id, "result": result}

