mgc_code:
def selected_shells(command):
    """Iterator over the shells with names matching the patterns.
    An empty patterns matches all the shells"""
    import fnmatch

    patterns = getattr(command, "patterns", [])
    shells = getattr(command, "shells", [])
    if not patterns:
        for sh in shells:
            yield sh
        return
    for sh in shells:
        name = getattr(sh, "name", None)
        if name is None:
            continue
        if any(fnmatch.fnmatch(name, pat) for pat in patterns):
            yield sh

