mgc_code:
def agg_dims(arr, stat):
    """Returns a 1D array with higher dimensions aggregated using stat fn.

    Arguments:
    arr -- ndarray
    stat -- numpy or numpy.ma function as str to call
    """
    import numpy as np

    # Determine the aggregation function, preferring numpy.ma if available
    try:
        func = getattr(np.ma, stat)
    except AttributeError:
        func = getattr(np, stat)

    # If arr has more than one dimension, aggregate over all but the first
    if arr.ndim > 1:
        axis = tuple(range(1, arr.ndim))
        result = func(arr, axis=axis)
    else:
        result = arr

    # Ensure the output is a 1‑D ndarray
    result = np.atleast_1d(result).ravel()
    return result

