def AddToBalance(self, assetId, fixed8_val):
        """
        Add amount to the specified balance.

        Args:
            assetId (UInt256):
            fixed8_val (Fixed8): amount to add.
        """
        if not isinstance(assetId, UInt256):
            raise TypeError(f"assetId must be UInt256, got {type(assetId).__name__}")
        if not isinstance(fixed8_val, Fixed8):
            raise TypeError(f"fixed8_val must be Fixed8, got {type(fixed8_val).__name__}")

        # Ensure the instance has a balances container
        if not hasattr(self, "_balances"):
            self._balances = {}

        current = self._balances.get(assetId, Fixed8(0))
        try:
            new_balance = current + fixed8_val
        except Exception as e:
            raise ValueError(f"Failed to add balances: {e}")

        self._balances[assetId] = new_balance

