def is_password_valid(plaintextpw: str, storedhash: str) -> bool:
    """
    Checks if a plaintext password matches a stored hash.

    Uses ``bcrypt``. The stored hash includes its own incorporated salt.
    """
    import bcrypt
    if not isinstance(plaintextpw, str) or not isinstance(storedhash, str):
        return False
    try:
        return bcrypt.checkpw(plaintextpw.encode('utf-8'), storedhash.encode('utf-8'))
    except Exception:
        return False

