mgc_code:
def find_module_egg_path(module_path):
    """
    Find the path of the deployed egg package that may contain the
    specified module path.


    @param module_path: the path of a Python module.


    @return: the absolute path of the deployed egg package that contains
        the specified module path, or ``None`` if no deployed egg
        package contains this module path.
    """
    import os

    path = os.path.abspath(module_path)
    while True:
        head, tail = os.path.split(path)
        if tail.lower().endswith('.egg'):
            if os.path.isdir(path) or os.path.isfile(path):
                return path
        if head == path:  # reached filesystem root
            break
        path = head
    return None

