def _generate_data_for_format(fmt):
    """Generate a fake data dictionary to fill in the provided format string."""
    import string

    def _set_nested(d, keys, value):
        if len(keys) == 1:
            d[keys[0]] = value
        else:
            d = d.setdefault(keys[0], {})
            _set_nested(d, keys[1:], value)

    result = {}
    formatter = string.Formatter()
    for _, field_name, _, _ in formatter.parse(fmt):
        if not field_name:
            continue
        # ignore conversion or format spec parts after '!' or ':'
        field_name = field_name.split('!')[0].split(':')[0]
        # handle attribute and item lookups (e.g., user.name or user[0])
        # we only support dot notation for simplicity
        keys = field_name.split('.')
        placeholder = f"example_{keys[-1]}"
        _set_nested(result, keys, placeholder)
    return result

