def omnihash(obj):
    """ recursively hash unhashable objects """
    if isinstance(obj, set):
        return hash(frozenset(omnihash(e) for e in obj))
    elif isinstance(obj, (tuple, list)):
        return hash(tuple(omnihash(e) for e in obj))
    elif isinstance(obj, dict):
        return hash(frozenset((k, omnihash(v)) for k, v in obj.items()))
    else:
        return hash(obj)

mgc_code:
def omnihash(obj):
    """ recursively hash unhashable objects """
    try:
        return hash(obj)
    except TypeError:
        if isinstance(obj, (list, tuple)):
            return hash(tuple(omnihash(item) for item in obj))
        if isinstance(obj, dict):
            items = tuple(sorted((omnihash(k), omnihash(v)) for k, v in obj.items()))
            return hash(items)
        if isinstance(obj, set):
            return hash(tuple(sorted(omnihash(item) for item in obj)))
        if hasattr(obj, '__dict__'):
            return omnihash(vars(obj))
        if hasattr(obj, '__slots__'):
            slot_dict = {slot: getattr(obj, slot) for slot in obj.__slots__ if hasattr(obj, slot)}
            return omnihash(slot_dict)
        return hash(repr(obj))

