mgc_code:
def add_object(self, obj):
        """Add object to local and app environment storage

        :param obj: Instance of a .NET object
        """
        import uuid

        if obj is None:
            raise ValueError("obj must not be None")

        # generate a unique identifier for the object
        obj_id = str(uuid.uuid4())

        # store locally
        if not hasattr(self, "_local_objects"):
            self._local_objects = {}
        self._local_objects[obj_id] = obj

        # store in the application environment if possible
        app_env = getattr(self, "_app", None)
        if app_env is not None:
            storage = getattr(app_env, "environment", None)
            if storage is not None:
                storage = getattr(storage, "storage", None)
                if storage is not None and hasattr(storage, "add"):
                    try:
                        storage.add(obj_id, obj)
                    except Exception:
                        # ignore storage errors; local storage is still valid
                        pass

        return obj_id

