def _get_atomic_dtype(data_type):
    """Retrieve the NumPy's `dtype` for a given atomic data type."""
    import numpy as np
    try:
        dt = np.dtype(data_type)
    except Exception as exc:
        raise TypeError(f"Unable to interpret {data_type!r} as a NumPy dtype") from exc
    if dt.fields is not None:
        raise TypeError(f"{data_type!r} is not an atomic dtype")
