def insertPrimaryDataset(self, businput):
        """
        Input dictionary has to have the following keys:
        primary_ds_name, primary_ds_type, creation_date, create_by.
        it builds the correct dictionary for dao input and executes the dao
        """
        required_keys = ("primary_ds_name", "primary_ds_type", "creation_date", "create_by")
        if not isinstance(businput, dict):
            raise TypeError("businput must be a dict")
        missing = [k for k in required_keys if k not in businput]
        if missing:
            raise ValueError(f"Missing required keys: {', '.join(missing)}")
        dao_input = {k: businput[k] for k in required_keys}
        if not hasattr(self, "dao") or not hasattr(self.dao, "insertPrimaryDataset"):
            raise AttributeError("DAO with method insertPrimaryDataset not found")
        return self.dao.insertPrimaryDataset(dao_input)

