def reload(self):
        """ reloads this object so if it was updated in the database it now
        contains the new values"""
        try:
            from sqlalchemy.orm import object_session
            sess = object_session(self)
            if sess is None:
                raise RuntimeError("Object is not attached to a SQLAlchemy session")
            sess.refresh(self)
        except Exception:
            cls = self.__class__
            pk_name = getattr(cls, '__primary_key__', 'id')
            pk = getattr(self, pk_name, None)
            if pk is None:
                raise RuntimeError("Primary key not found; cannot reload")
            if hasattr(cls, 'get'):
                fresh = cls.get(pk)
            else:
                raise RuntimeError("No method to retrieve fresh instance")
            if fresh is None:
                raise RuntimeError("Failed to reload object from database")
            self.__dict__.clear()
            self.__dict__.update(fresh.__dict__)

