mgc_code:
def str_encode(value, encoder='base64'):
    """
    .. versionadded:: 2014.7.0

    value
        The value to be encoded.

    encoder : base64
        The encoder to use on the subsequent string.

    CLI Example:

    .. code-block:: bash

        salt '*' random.str_encode 'I am a new string' base64
    """
    import base64

    # Ensure we are working with bytes
    if isinstance(value, bytes):
        raw = value
    else:
        raw = str(value).encode("utf-8")

    enc = encoder.lower()
    if enc == "base64":
        return base64.b64encode(raw).decode("utf-8")
    if enc in ("hex", "hexlify"):
        return raw.hex()
    if enc in ("url", "urlsafe", "base64url"):
        return base64.urlsafe_b64encode(raw).decode("utf-8")

