def dicts_from_table(table, keys=None):
    """Returns a list of dict() objects, one for each row in a list of lists (table)"""
    lod = []
    for row in table:
        if not keys:
            keys = row
            if not all((k not in (None, '') or bool(k.strip())) for k in keys):
                keys = None
            continue
        lod += [OrderedDict((k, v) for k, v in zip(keys, row))]
    return lod

mgc_code:
def dicts_from_table(table, keys=None):
    """Returns a list of dict() objects, one for each row in a list of lists (table)"""
    result = []
    if keys is None:
        for row in table:
            result.append({i: v for i, v in enumerate(row)})
    else:
        keys = list(keys)
        klen = len(keys)
        for row in table:
            d = {}
            for i, key in enumerate(keys):
                d[key] = row[i] if i < len(row) else None
            result.append(d)
    return result

