mgc_code:
def recv(self, size):
        """
        Read from the standard output of the forked program.

        :param int size: how many chars should be read

        :return: the length of the read content, as an `int`
        """
        if size <= 0:
            return 0
        try:
            if hasattr(self, "stdout") and hasattr(self.stdout, "read"):
                data = self.stdout.read(size)
            elif hasattr(self, "_stdout_fd"):
                import os
                data = os.read(self._stdout_fd, size)
            else:
                raise AttributeError("No stdout source available")
        except Exception:
            return 0
        return len(data)

