def get_volume_remove_kwargs(self, action, volume_name, kwargs=None):
        """
        Generates keyword arguments for the Docker client to remove a volume.

        :param action: Action configuration.
        :type action: ActionConfig
        :param volume_name: Volume name.
        :type volume_name: unicode | str
        :param kwargs: Additional keyword arguments to complement or override the configuration-based values.
        :type kwargs: dict
        :return: Resulting keyword arguments.
        :rtype: dict
        """
        if kwargs is None:
            kwargs = {}
        if not isinstance(kwargs, dict):
            raise TypeError("kwargs must be a dict")
        result = {}
        # Extract configuration‑based kwargs from the action object/dict
        if hasattr(action, "remove_volume_kwargs"):
            cfg = getattr(action, "remove_volume_kwargs")
            if cfg:
                if not isinstance(cfg, dict):
                    raise TypeError("action.remove_volume_kwargs must be a dict")
