def flatten(self):
        """
        Get a flattened list of the items in the collection.

        :rtype: Collection
        """
        def _flatten(item):
            # Strings/bytes are treated as atomic values
            if isinstance(item, (str, bytes)):
                return [item]
            # If the item has its own flatten method, use it
            if hasattr(item, "flatten") and callable(item.flatten):
                return list(item.flatten())
            # Try to iterate over the item
            try:
                iterator = iter(item)
            except TypeError:
                return [item]
            else:
                result = []
                for sub in iterator:
                    result.extend(_flatten(sub))
                return result

        return _flatten(self)

