def help(self):
        """Prints discovered resources and their associated methods. Nice when
        noodling in the terminal to wrap your head around Magento's insanity.
        """
        resources = getattr(self, "resources", None) or getattr(self, "_resources", None)
        if not resources:
            print("No resources discovered.")
            return
        for resource, methods in sorted(resources.items()):
            print(f"{resource}:")
            try:
                iterable = sorted(methods)
            except TypeError:
                try:
                    iterable = sorted(methods.keys())
                except Exception:
                    iterable = list(methods)
            for method in iterable:
                print(f"  {method}")

