def get_flat_size(self):
        """Returns the total length of all of the flattened variables.

        Returns:
            The length of all flattened variables concatenated.
        """
        total = 0
        for var in getattr(self, "flat_vars", []):
            # Prefer NumPy/Torch size attribute if present
            if hasattr(var, "size"):
                try:
                    total += int(var.size)
                    continue
                except Exception:
                    pass
            # Fallback to Python length
            try:
                total += len(var)
            except Exception:
                # If var is a scalar or has no length, count as 1
                total += 1
        return total

