def add(self, byte_sig: str, text_sig: str) -> None:
        """
        Adds a new byte - text signature pair to the database.
        :param byte_sig: 4-byte signature string
        :param text_sig: resolved text signature
        :return:
        """
        if not isinstance(byte_sig, str):
            raise TypeError("byte_sig must be a string")
        if len(byte_sig) != 4:
            raise ValueError("byte_sig must be exactly 4 characters long")
        if not isinstance(text_sig, str):
            raise TypeError("text_sig must be a string")
        # Ensure the internal storage exists
        if not hasattr(self, "_signatures"):
            self._signatures = {}
        # Prevent overwriting existing entries
        if byte_sig in self._signatures:
            raise KeyError(f"Signature '{byte_sig}' already exists")
        self._signatures[byte_sig] = text_sig

