def api_user_uuid(request, userUuid, key=None, hproPk=None):
    """Return information about an user based on uuid"""
    import uuid

    # Validate the UUID format
    try:
        user_uuid_obj = uuid.UUID(str(userUuid))
    except (ValueError, AttributeError, TypeError) as exc:
        raise ValueError(f"Invalid UUID supplied: {userUuid}") from exc

    # Basic result structure
    result = {
        "uuid": str(user_uuid_obj),
        "key": key,
        "hproPk": hproPk,
    }

    # If a request object is provided, attempt to enrich the response
    if request is not None:
        # Common patterns: Django/Flask request objects
        user_id = None
        # Django-like request
        if hasattr(request, "user"):
            try:
                user_id = getattr(request.user, "id", None)
            except Exception:
                user_id = None
        # Flask-like request (may have a 'headers' dict)
        elif hasattr(request, "headers"):
            user_id = request.headers.get("X-User-Id")
        result["request_user_id"] = user_id

    return result

