hwc_code:
def QA_util_code_tostr(code):
    """
    将所有沪深股票从数字转化到6位的代码

    因为有时候在csv等转换的时候,诸如 000001的股票会变成office强制转化成数字1

    """
    if isinstance(code, int):
        return "{:>06d}".format(code)
    if isinstance(code, str):
        # 聚宽股票代码格式 '600000.XSHG'
        # 掘金股票代码格式 'SHSE.600000'
        # Wind股票代码格式 '600000.SH'
        # 天软股票代码格式 'SH600000'
        if len(code) == 6:
            return code
        if len(code) == 8:
            # 天软数据
            return code[-6:]
        if len(code) == 9:
            return code[:6]
        if len(code) == 11:
            if code[0] in ["S"]:
                return code.split(".")[1]
            return code.split(".")[0]
        raise ValueError("错误的股票代码格式")
    if isinstance(code, list):
        return QA_util_code_to_str(code[0])

mgc_code:
def QA_util_code_tostr(code):
    """
    将所有沪深股票从数字转化到6位的代码

    因为有时候在csv等转换的时候,诸如 000001的股票会变成office强制转化成数字1

    """
    import pandas as pd
    import numpy as np

    def _to_str(x):
        try:
            # Strip possible whitespace
            s = str(x).strip()
            # If already a 6‑digit string (possibly with leading zeros), return as is
            if s.isdigit() and len(s) == 6:
                return s
            # Convert numeric strings or numbers to int then format
            return f"{int(float(s)):06d}"
        except Exception:
            return x

    if isinstance(code, pd.Series):
        return code.apply(_to_str)
    if isinstance(code, pd.DataFrame):
        return code.applymap(_to_str)
    if isinstance(code, (list, tuple)):
        return [_to_str(item) for item in code]
    if isinstance(code, np.ndarray):
        vec = np.vectorize(_to_str, otypes=[object])
        return vec(code)
    return _to_str(code)

