def _calibrate(self, data):
        """Calibrate *data*."""
        import numpy as np
        if data is None:
            return None
        arr = np.asarray(data, dtype=float)
        if arr.size == 0:
            return arr
        mean = np.mean(arr)
        std = np.std(arr)
        if std == 0:
            return np.zeros_like(arr)
        return (arr - mean) / std

