def _add_complex_section(self, item):
        """Add a section that has a filter and set of constraints

        :raise: ValueError if filter or constraints is missing
        """
        if not isinstance(item, dict):
            raise ValueError("Item must be a dict containing 'filter' and 'constraints'")
        if 'filter' not in item or item['filter'] is None:
            raise ValueError("Missing required 'filter' in item")
        if 'constraints' not in item or item['constraints'] is None:
            raise ValueError("Missing required 'constraints' in item")
        # Ensure the container for sections exists
        if not hasattr(self, 'sections'):
            self.sections = []
        # Create a copy to avoid external mutation
        section = {'filter': item['filter'], 'constraints': item['constraints']}
        self.sections.append(section)
        return section

