def multi_packages(self, logins=None, platform=None, package_type=None,
                       type_=None, access=None):
        """Return the private packages for a given set of usernames/logins."""
        params = {}
        if logins is not None:
            if isinstance(logins, (list, tuple, set)):
                params['logins'] = ','.join(map(str, logins))
            else:
                params['logins'] = str(logins)
        if platform is not None:
            params['platform'] = platform
        if package_type is not None:
            params['package_type'] = package_type
        if type_ is not None:
            params['type'] = type_
        if access is not None:
            params['access'] = access

        # Assume the instance provides a generic request method.
        response = self._request('GET', '/private-packages', params=params)
        # Expecting JSON response containing a list of packages.
        return response.json() if hasattr(response, 'json') else response

