def update_configs(self, release):
        """ Update the fedora-atomic.git repositories for a given release """
        import os
        import shutil
        import subprocess
        from pathlib import Path

        repo_path = Path(getattr(self, "repo_path", "fedora-atomic.git"))
        config_src = Path(getattr(self, "config_src", "configs"))
        if not repo_path.is_dir():
            raise RuntimeError(f"Repository path '{repo_path}' does not exist")
        if not config_src.is_dir():
            raise RuntimeError(f"Config source '{config_src}' does not exist")

