def handle(self, dict):
        """
        Processes a vaild stats request

        @param dict: a valid dictionary object
        """
        if not isinstance(dict, dict):
            raise TypeError("Expected a dictionary")
        # Extract numeric values from the dictionary (including nested iterables)
        def _extract_numbers(obj):
            if isinstance(obj, (int, float)):
                return [obj]
            if isinstance(obj, (list, tuple, set)):
                nums = []
                for item in obj:
                    nums.extend(_extract_numbers(item))
                return nums
            if isinstance(obj, dict):
                nums = []
                for v in obj.values():
                    nums.extend(_extract_numbers(v))
                return nums
            return []
        numbers = _extract_numbers(dict)
        if not numbers:
            return {"count": 0, "sum": 0, "average": None, "min": None, "max": None}
        total = sum(numbers)
        count = len(numbers)
        return {
            "count": count,
            "sum": total,
            "average": total / count,
            "min": min(numbers),
            "max": max(numbers),
        }

