async def load_blob(reader, elem_type, params=None, elem=None):
    """
    Loads blob from reader to the element. Returns the loaded blob.

    :param reader:
    :param elem_type:
    :param params:
    :param elem:
    :return:
    """
    # Determine how many bytes to read
    size = None
    if params is not None:
        # common keys that may specify length
        for key in ("size", "length", "count", "bytes"):
            if key in params:
                size = params[key]
                break

    # Read from the async reader
    if hasattr(reader, "readexactly") and size is not None:
        # readexactly may raise if not enough data; let it propagate
        data = await reader.readexactly(size)
    elif hasattr(reader, "read"):
        if size is None:
            data = await reader.read()
        else:
            data = await reader.read(size)
    else:
        raise TypeError("reader must provide an async read or readexactly method")

    # If an element is supplied, try to store the blob in it
    if elem is not None:
        # Prefer a setter method
        for setter_name in ("set_blob", "set_data", "set_content"):
            setter = getattr(elem, setter_name, None)
            if callable(setter):
                setter(data)
                break
        else:
            # Fallback to direct attribute assignment
            for attr_name in ("blob", "data", "content"):
                if hasattr(elem, attr_name):
                    setattr(elem, attr_name, data)
                    break

    return data

