def check_structure(data):
    """
    Check whether the structure is flat dictionary. If not, try to convert it
    to dictionary.

    Args:
        data: Whatever data you have (dict/tuple/list).

    Returns:
        dict: When the conversion was successful or `data` was already `good`.

    Raises:
        MetaParsingException: When the data couldn't be converted or had `bad`
                              structure.
    """
    if not isinstance(data, dict):
        try:
            data = _convert_to_dict(data)
        except MetaParsingException:
            raise
        except:
            raise MetaParsingException(
                "Metadata format has invalid strucure (dict is expected)."
            )

    for key, val in data.iteritems():
        if type(key) not in _ALLOWED_TYPES:
            raise MetaParsingException(
                "Can't decode the meta file - invalid type of keyword '" +
                str(key) +
                "'!"
            )
        if type(val) not in _ALLOWED_TYPES:
            raise MetaParsingException(
                "Can't decode the meta file - invalid type of keyword '" +
                str(key) +
                "'!"
            )

    return data

mgc_code:
def check_structure(data):
    """
    Check whether the structure is flat dictionary. If not, try to convert it
    to dictionary.

    Args:
        data: Whatever data you have (dict/tuple/list).

    Returns:
        dict: When the conversion was successful or `data` was already `good`.

    Raises:
        MetaParsingException: When the data couldn't be converted or had `bad`
                              structure.
    """
    try:
        MetaParsingException
    except NameError:
        class MetaParsingException(Exception):
            """Exception raised when data cannot be parsed into a flat dict."""
            pass

    def _is_flat(d):
        for k, v in d.items():
            if isinstance(v, (dict, list, tuple)):
                return False
        return True

    if isinstance(data, dict):
        if _is_flat(data):
            return data
        raise MetaParsingException("Dictionary is not flat.")
    if isinstance(data, (list, tuple)):
        try:
            converted = dict(data)
        except Exception as e:
            raise MetaParsingException(f"Cannot convert to dict: {e}")
        if _is_flat(converted):
            return converted
        raise MetaParsingException("Converted dictionary is not flat.")
    raise MetaParsingException("Unsupported data type for conversion.")

