def _transform_i(self, x, i):
        """return transform of x in component i"""
        try:
            tr = self._transforms[i]
        except Exception as e:
            raise IndexError(f"Transform index {i} out of range") from e
        if tr is None:
            return x
        if callable(tr):
            return tr(x)
        if hasattr(tr, "transform"):
            return tr.transform(x)
        raise TypeError(f"Transform at index {i} is not callable")

