def flush_read_tuple(self):
        """Flush the internal buffer of reads.
		"""
        buf = getattr(self, "_read_buffer", None)
        if buf is not None:
            # If the buffer supports clear (list, deque, etc.), use it.
            if hasattr(buf, "clear"):
                buf.clear()
            else:
                # Fallback: replace with a new empty container.
                setattr(self, "_read_buffer", [])
        else:
            # Ensure the attribute exists for future operations.
            setattr(self, "_read_buffer", [])

