def _get_bottom_line_color(self):
        """Returns color rgb tuple of bottom line"""
        # Attempt to retrieve a predefined bottom line color attribute
        color = getattr(self, 'bottom_line_color', None)
        if color is None:
            color = getattr(self, '_bottom_line_color', None)
        # Fallback to a theme-provided color if available
        if color is None:
            theme = getattr(self, 'theme', None)
            if theme is not None and hasattr(theme, 'bottom_line_color'):
                color = theme.bottom_line_color
        # Default to black if no color is found
        if color is None:
            color = (0, 0, 0)
        # Ensure the result is a 3‑tuple of ints (RGB)
        if isinstance(color, (list, tuple)) and len(color) == 3:
            return tuple(int(c) for c in color)
        return (0, 0, 0)

