mgc_code:
def parse(self, data, mimetype):
        """
        Parses a byte array containing a JSON document and returns a Python object.
        :param data: The byte array containing a JSON document.
        :param MimeType mimetype: The mimetype chose to parse the data.
        :return: A Python object.
        """
        import json

        # Validate mimetype
        if not mimetype or not str(mimetype).lower().startswith('application/json'):
            raise ValueError(f"Unsupported mimetype for JSON parsing: {mimetype}")

        # Ensure data is bytes; if it's a str, encode it
        if isinstance(data, str):
            data_bytes = data.encode('utf-8')
        else:
            data_bytes = data

        # Decode bytes to text
        try:
            text = data_bytes.decode('utf-8')
        except Exception as exc:
            raise ValueError("Failed to decode JSON bytes as UTF-8") from exc

        # Empty input yields None
        if not text.strip():
            return None

        # Parse JSON
        try:
            return json.loads(text)
        except json.JSONDecodeError as exc:
            raise ValueError("Invalid JSON data") from exc

