mgc_code:
def _reader(path, password, prompt):
        """Read PDF and decrypt if encrypted."""
        from PyPDF2 import PdfReader

        # Open the PDF file
        reader = PdfReader(path)

        # If the PDF is encrypted, attempt to decrypt it
        if reader.is_encrypted:
            # Determine which password to use
            pwd = password
            if pwd is None and callable(prompt):
                pwd = prompt()
            if pwd is None:
                raise ValueError("PDF is encrypted and no password was provided.")
            # PyPDF2 expects a string (or bytes) password
            if isinstance(pwd, bytes):
                pwd = pwd.decode(errors="ignore")
            # Attempt decryption; decrypt returns True on success
            if not reader.decrypt(pwd):
                raise ValueError("Failed to decrypt PDF with the provided password.")
        return reader

