mgc_code:
def get_path_matching(name):
    """Get path matching a name.

    Parameters
    ----------
    name : string
        Name to search for.

    Returns
    -------
    string
        Full filepath.
    """
    from pathlib import Path
    cwd = Path.cwd()
    # Direct match (including possible extensions)
    for p in cwd.rglob(name):
        if p.is_file():
            return str(p.resolve())
    # Match by stem (ignore extension)
    target_stem = Path(name).stem
    for p in cwd.rglob("*"):
        if p.is_file() and p.stem == target_stem:
            return str(p.resolve())
    raise FileNotFoundError(f"No file matching {name!r} found.")

