def _add_process(self, aProcess):
        """
        Private method to add a process object to the snapshot.

        @type  aProcess: L{Process}
        @param aProcess: Process object.
        """
        # Initialize internal storage if not present
        if not hasattr(self, "_processes"):
            self._processes = {}
        if not hasattr(self, "_processes_by_name"):
            self._processes_by_name = {}

        # Validate the incoming process object
        pid = getattr(aProcess, "pid", None)
        if pid is None:
            raise AttributeError("Process object must have a 'pid' attribute")

        # Store the process by its PID
        self._processes[pid] = aProcess

        # Optionally index by name if the process provides one
        name = getattr(aProcess, "name", None)
        if name is not None:
            self._processes_by_name.setdefault(name, []).append(aProcess)

