mgc_code:
def _set_property(xml_root, name, value, properties=None):
    """Sets property to specified value."""
    # Find existing property element
    for prop in xml_root.findall('property'):
        if prop.get('name') == name:
            prop.set('value', str(value))
            if properties is not None:
                properties[name] = value
            return
    # Property not found; create a new one
    import xml.etree.ElementTree as ET
    new_prop = ET.SubElement(xml_root, 'property')
    new_prop.set('name', name)
    new_prop.set('value', str(value))
    if properties is not None:
        properties[name] = value

