def _section_from_spec(elf_file, spec):
    """
        Retrieve a section given a "spec" (either number or name).
        Return None if no such section exists in the file.
    """
    if isinstance(spec, int):
        try:
            return elf_file.get_section(spec)
        except Exception:
            return None
    if isinstance(spec, (bytes, str)):
        name = spec.decode() if isinstance(spec, bytes) else spec
        try:
            return elf_file.get_section_by_name(name)
        except Exception:
            return None
    return None

