def _construct_from_json(self, rec):
        """ Construct this Dagobah instance from a JSON document. """
        if not isinstance(rec, dict):
            raise TypeError(f"Expected dict for JSON record, got {type(rec).__name__}")
        for key, value in rec.items():
            # If the attribute already exists and is a Dagobah-like object, try to construct it recursively
            current = getattr(self, key, None)
            if isinstance(value, dict) and hasattr(current, "_construct_from_json"):
                current._construct_from_json(value)
            else:
                setattr(self, key, value)
        return self

