def icanhazascii(client, channel, nick, message, found):
    """
    A plugin for generating showing ascii artz
    """
    import shlex
    try:
        from pyfiglet import Figlet
    except Exception:
        return "Error: pyfiglet library is required for ascii generation."
    # Extract the text after the command keyword
    parts = message.strip().split(None, 1)
    if len(parts) < 2 or not parts[1].strip():
        return f"{nick}: usage: icanhazascii <text>"
    text = parts[1].strip()
    fig = Figlet()
    try:
        ascii_art = fig.renderText(text)
    except Exception:
        ascii_art = text
    return

