def get_next_id(self):
        """Gets the next Id in this list.

        return: (osid.id.Id) - the next Id in this list. The has_next()
                method should be used to test that a next Id is
                available before calling this method.
        raise:  IllegalState - no more elements available in this list
        raise:  OperationFailed - unable to complete request
        compliance: mandatory - This method must be implemented.

        """
        try:
            # Ensure an iterator exists
            if not hasattr(self, "_id_iter"):
                try:
                    self._id_iter = iter(self._ids)
                except Exception as e:
                    raise OperationFailed(str(e))
            return next(self._id_iter)
        except StopIteration:
            raise IllegalState("no more elements available in this list")
        except Exception as e:
            raise OperationFailed(str(e))

