def delete_device(self, device_id):
        """Delete device from catalog.

        :param str device_id: ID of device in catalog to delete (Required)
        :return: void
        """
        if not device_id:
            raise ValueError("device_id must be provided")
        base = getattr(self, "base_url", "")
        if not base:
            raise AttributeError("Instance missing 'base_url' attribute")
        url = f"{base.rstrip('/')}/devices/{device_id}"
        session = getattr(self, "session", None)
        if session is None:
            import requests
            session = requests
        response = session.delete(url)
        if not response.ok:
            try:
                detail = response.json()
            except Exception:
                detail = response.text
            raise RuntimeError(
                f"Failed to delete device {device_id}: {response.status_code} {detail}"
            )
        return None

