def gc(self):
        """ Garbage collect overflow and/or aged entries. """
        manifest = []
        overlimit = len(self.data) - self.maxsize \
            if self.maxsize is not None else 0
        now = self.ttl is not None and self.timer()
        for key, entry in self.data.items():
            if overlimit > 0 or (now and self.is_expired(entry, time=now)):
                overlimit -= 1
                manifest.append(key)
            else:
                break
        for x in manifest:
            del self.data[x]

mgc_code:
def gc(self):
        """ Garbage collect overflow and/or aged entries. """
        import time
        # Remove aged entries
        max_age = getattr(self, "_maxage", None)
        if max_age is not None:
            now = time.time()
            for key, (_, ts) in list(self._cache.items()):
                if now - ts > max_age:
                    del self._cache[key]
        # Remove overflow entries (oldest first)
        max_size = getattr(self, "_maxsize", None)
        if max_size is not None:
            while len(self._cache) > max_size:
                # pop the oldest entry; assumes OrderedDict semantics
                self._cache.popitem(last=False)

