            if hasattr(self, "set_status") and hasattr(self, "finish"):
                self.set_status(500)
                self.finish("Internal Server Error")
            elif hasattr(self, "send_response"):
                self.send_response(500, b"Internal Server Error")
            else:
                raise RuntimeError("No method to send error response")
        except Exception as exc:
            logger = getattr(self, "logger", None)
            if logger is not None:
                try:
                    logger.exception("Failed to send 500 error response")
                except Exception:
                    pass
            try:
                if hasattr(self, "write"):
                    self.write("Internal Server Error")
            except Exception:
                pass

