def _convert_token(self, token):
        """Convert token fields from camel case.

        :param dict token: An authentication token.
        :rtype: dict
        """
        import re

        def _to_snake(name):
            return re.sub(r'(?<!^)(?=[A-Z])', '_', name).lower()

        def _process(value):
            if isinstance(value, dict):
                return {_to_snake(k): _process(v) for k, v in value.items()}
            if isinstance(value, list):
                return [_process(item) for item in value]
            return value

        return _process(token)

