def _send_command_list(self, commands):
        """Wrapper for Netmiko's send_command method (for list of commands."""
        outputs = []
        # Ensure we have an iterable of commands
        cmd_iter = commands if isinstance(commands, (list, tuple)) else [commands]
        for cmd in cmd_iter:
            try:
                result = self.send_command(cmd)
            except Exception as exc:
                # Capture any exception as a string to avoid breaking the loop
                result = str(exc)
            outputs.append(result)
        return outputs

