mgc_code:
def _jog(self, axis, direction, step):
        """
        Move the pipette on `axis` in `direction` by `step` and update the
        position tracker
        """
        delta = direction * step
        # Send movement command to hardware if possible
        hw = getattr(self, "_hardware", None)
        if hw is not None and hasattr(hw, "move_relative"):
            try:
                hw.move_relative({axis: delta})
            except Exception:
                pass
        # Update internal position tracker
        pos = getattr(self, "_position", None)
        if pos is None:
            self._position = {}
            pos = self._position
        pos[axis] = pos.get(axis, 0) + delta

