def generate_unit_triangles(image_width, image_height):
    """Generate coordinates for a tiling of unit triangles."""
    triangles = []
    for y in range(image_height):
        for x in range(image_width):
            # lower‑left triangle of the unit square
            triangles.append(((x, y), (x + 1, y), (x, y + 1)))
            # upper‑right triangle of the unit square
            triangles.append(((x + 1, y + 1), (x, y + 1), (x + 1, y)))
    return triangles

