def check_for_interest(self, client, recipient, message):
        """Determine whether this line is addressing us."""
        for prefix in self.prefixes:
            if message.startswith(prefix):
                return True, message[len(prefix):]

        # Don't require a prefix if addressed in PM.
        # This comes after the prefix checks because
        # if the user does include a prefix, we want
        # to strip it, even in PM.
        if not isinstance(recipient, Channel):
            return True, message

        return False, None

mgc_code:
def check_for_interest(self, client, recipient, message):
        """Determine whether this line is addressing us."""
        bot_nick = getattr(self, 'nick', getattr(self, 'name', None))
        if not bot_nick:
            return False

        # Normalize inputs
        recipient_norm = str(recipient).strip().lower()
        message_norm = str(message).strip().lower()
        bot_nick_norm = str(bot_nick).strip().lower()

        # Direct addressing via recipient field
        if recipient_norm == bot_nick_norm:
            return True

        # Mention in the message (e.g., "@botnick" or "botnick:")
        if f"@{bot_nick_norm}" in message_norm:
            return True
        if message_norm.startswith(f"{bot_nick_norm}:"):
            return True
        if f"{bot_nick_norm} " in message_norm:
            # Ensure it's a separate word
            words = message_norm.split()
            if bot_nick_norm in words:
                return True

        return False

