def scanmeta(f):
    """Scan file headers for @meta ... @endmeta information and store that into
       a dictionary.
    """
    # Determine if f is a path or a file-like object
    close_after = False
    if isinstance(f, (str, bytes, os.PathLike)):
        f = open(f, "r", encoding="utf-8")
        close_after = True

    meta = {}
    in_block = False

    try:
        for line in f:
            stripped = line.strip()
            if not in_block:
                if stripped == "@meta":
                    in_block = True
                # stop scanning after first non-meta header line (e.g., code)
                elif stripped and not stripped.startswith("#"):
                    # reached content before any meta block
                    break
                continue

            # inside meta block
            if stripped == "@endmeta":
                break
            if not stripped or stripped.startswith("#"):
                continue
            # parse key: value
            if ":" in stripped:
                key, value = stripped.split(":", 1)
                meta[key.strip()] = value.strip()
    finally:
        if close_after:
            f.close()

