def load(self, fname):
        """
        Load signatures from a file.

        @fname - Path to signature file.

        Returns None.
        """
        if not hasattr(self, 'signatures'):
            self.signatures = []
        with open(fname, 'r', encoding='utf-8') as f:
            for line in f:
                sig = line.rstrip('\n\r')
                if sig:
                    self.signatures.append(sig)
        return None

