from __future__ import annotations
import os
import json

try:
    import yaml
except Exception:  # pragma: no cover
    yaml = None

try:
    from revision.config import Config
except Exception as e:  # pragma: no cover
    raise ImportError("Unable to import Config class") from e

if config_path_or_dict is None:
    return None

# If a dict is supplied, instantiate Config directly.
if isinstance(config_path_or_dict, dict):
    try:
        return Config(config_path_or_dict)
    except TypeError:
        # Fallback to a classmethod if the constructor does not accept a dict.
        if hasattr(Config, "from_dict"):
            return Config.from_dict(config_path_or_dict)
        raise

# If a string path is supplied, load the file.
if isinstance(config_path_or_dict, str):
    path = os.path.expanduser(config_path_or_dict)
    if not os.path.isfile(path):
        return None

    with open(path, "r", encoding="utf-8") as f:
        content = f.read()

    # Try JSON first.
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        # Fallback to YAML if available.
        if yaml is not None:
            try:
                data = yaml.safe_load(content)
            except yaml.YAMLError:
                return None
        else:
            return None

    # Instantiate Config from the parsed data.

