def reference_creator_surnames(self, index):
        """Return as a list the surnames of the reference creators (locally defined)."""
        try:
            ref = self.references[index]
        except (IndexError, TypeError, AttributeError):
            return []
        # Support dict‑like or object‑like reference entries
        creators = []
        if isinstance(ref, dict):
            creators = ref.get("creators", [])
        else:
            creators = getattr(ref, "creators", [])
        surnames = []
        for creator in creators:
            if isinstance(creator, dict):
                surname = creator.get("surname")
            else:
                surname = getattr(creator, "surname", None)
            if surname:
                surnames.append(surname)
        return surnames

