def _missing_value_message(self, parent):
        # type: (ET.Element) -> Text
        """Return the message to report that the value needed for serialization is missing."""
        if parent is None:
            return "Missing value for serialization"
        tag = parent.tag
        # If the tag includes a namespace, strip it for readability
        if isinstance(tag, str) and '}' in tag:
            tag = tag.split('}', 1)[1]
        return f"Missing value for element '{tag}'"

