def merge_sims(oldsims, newsims, clip=None):
    """Merge two precomputed similarity lists, truncating the result to `clip` most similar items."""
    result = {}
    for item, sim in oldsims:
        if item not in result or sim > result[item]:
            result[item] = sim
    for item, sim in newsims:
        if item not in result or sim > result[item]:
            result[item] = sim
    merged = sorted(result.items(), key=lambda x: x[1], reverse=True)
    if clip is not None:
        merged = merged[:clip]
    return merged

