mgc_code:
def runserver(app=None, reloader=None, debug=None, host=None, port=None):
    """Run the Flask development server i.e. app.run()"""
    from flask import current_app
    # Resolve the Flask app
    if app is None:
        try:
            app = current_app._get_current_object()
        except Exception as exc:
            raise RuntimeError("No Flask app provided and no active application context") from exc

    # Determine defaults
    if debug is None:
        debug = getattr(app, "debug", False)
    if reloader is None:
        reloader = debug
    if host is None:
        host = "127.0.0.1"
    if port is None:
        port = 5000

    # Run the development server
    return app.run(host=host, port=port, debug=debug, use_reloader=reloader)

