mgc_code:
def field_timedelta_from_json(self, json_val):
        """Convert json_val to a timedelta object.

        json_val contains total number of seconds in the timedelta.
        If json_val is a string it will be converted to a float.
        """
        import datetime

        if json_val is None:
            return None
        # Convert string representation to float
        if isinstance(json_val, str):
            try:
                seconds = float(json_val)
            except Exception as exc:
                raise ValueError(f"Cannot convert string to timedelta seconds: {json_val}") from exc
        else:
            seconds = json_val

        if not isinstance(seconds, (int, float)):
            raise ValueError(f"Invalid type for timedelta seconds: {type(seconds).__name__}")

        return datetime.timedelta(seconds=seconds)

