def check_sensors():
    """
    collect and check all available sensors
    """
    import psutil

    result = {}

    # Temperatures
    temps = {}
    try:
        raw_temps = psutil.sensors_temperatures()
        for name, entries in raw_temps.items():
            temps[name] = [
                {
                    "label": e.label,
                    "current": e.current,
                    "high": e.high,
                    "critical": e.critical,
                }
                for e in entries
            ]
    except (AttributeError, NotImplementedError):
        raw_temps = {}
    result["temperatures"] = temps

    # Fans
    fans = {}
    try:
        raw_fans = psutil.sensors_fans()
        for name, entries in raw_fans.items():
            fans[name] = [e.current for e in entries]
    except (AttributeError, NotImplementedError):
        raw_fans = {}
    result["fans"] = fans

    # Battery
    battery_info = None
    try:
        bat = psutil.sensors_battery()
        if bat is not None:
            battery_info = {
                "percent": bat.percent,
                "secsleft": bat.secsleft,
                "power_plugged": bat.power_plugged,
            }
    except (AttributeError, NotImplementedError):
        pass
    result["battery"] = battery_info

    return result

