def send_request(req=None, method=None, requires_response=True):
    """Call function req and then send its results via ZMQ."""
    if req is None:
        return functools.partial(send_request, method=method,
                                 requires_response=requires_response)

    @functools.wraps(req)
    def wrapper(self, *args, **kwargs):
        params = req(self, *args, **kwargs)
        _id = self.send(method, params, requires_response)
        return _id
    wrapper._sends = method
    return wrapper

mgc_code:
def send_request(req=None, method=None, requires_response=True):
    """Call function req and then send its results via ZMQ."""
    import json
    import zmq

    if req is None:
        raise ValueError("req must be provided")
    if not callable(req):
        raise TypeError("req must be callable")

    # Execute the request function
    try:
        result = req() if method is None else req(method)
    except Exception as e:
        # Propagate exception after sending error info
        result = {"error": str(e), "type": type(e).__name__}

    # Prepare ZMQ context and socket
    ctx = zmq.Context.instance()
    if requires_response:
        socket = ctx.socket(zmq.REQ)
    else:
        socket = ctx.socket(zmq.PUSH)
    # Default endpoint; can be overridden via environment variable
    endpoint = "tcp://127.0.0.1:5555"
    socket.connect(endpoint)

