            raise TypeError(f"record must be a dict or an instance of {cls.__name__}, got {type(record).__name__}")

        # Find the discriminator key (allow 'type' or 'class')
        discriminator = None
        for key in ('type', 'class', 'cls'):
            if key in record:
                discriminator = record[key]
                break
        if discriminator is None:
            raise ValueError(f"record does not contain a discriminator key ('type', 'class', or 'cls') to select a subclass of {cls.__name__}")

