mgc_code:
def get_chains(self):
        """Return an ordered list of the `Chain_#` directories in the db
        directory."""
        import os
        base = getattr(self, 'db_path', getattr(self, 'db_dir', None))
        if not base:
            raise AttributeError("Object has no 'db_path' or 'db_dir' attribute")
        try:
            entries = os.listdir(base)
        except OSError:
            return []
        chains = []
        for name in entries:
            full_path = os.path.join(base, name)
            if os.path.isdir(full_path) and name.startswith('Chain_'):
                suffix = name[6:]
                if suffix.isdigit():
                    chains.append(full_path)
        chains.sort(key=lambda p: int(os.path.basename(p)[6:]))
        return chains

