mgc_code:
def import_blacklist(self, parser):
        """Import blacklist.

        New entries parsed by 'parser' will be added to the blacklist.

        :param parser: sorting hat parser
        """
        # Ensure a blacklist container exists; use a set for fast membership checks
        if not hasattr(self, "blacklist"):
            self.blacklist = set()
        # Determine iterable of new entries from the parser
        try:
            # Common pattern: parser is a callable returning an iterable
            new_entries = parser()
        except TypeError:
            # If parser is already an iterable or has a .parse() method
            if hasattr(parser, "parse") and callable(parser.parse):
                new_entries = parser.parse()
            else:
                new_entries = parser
        # Add each entry to the blacklist, ignoring duplicates automatically
        for entry in new_entries:
            self.blacklist.add(entry)

