def get_learned_skills(self, lang):
        """
        Return the learned skill objects sorted by the order they were learned
        in.
        """
        # Retrieve all skill objects; support common container types
        skills = getattr(self, "skills", [])
        if isinstance(skills, dict):
            skills = skills.values()
        # Filter by language and learned status
        filtered = [
            s
            for s in skills
            if getattr(s, "lang", None) == lang and getattr(s, "learned", True)
        ]
        # Determine a stable sort key based on typical attributes
        def _key(s):
            if hasattr(s, "learned_order"):
                return s.learned_order
            if hasattr(s, "learned_at"):
                return s.learned_at
            # Fallback to insertion order if possible
            return getattr(s, "__order__", 0)

        return sorted(filtered, key=_key)

