def get_matching_blocks(self):
        """Similar to :py:meth:`get_opcodes`, but returns only the opcodes that are
        equal and returns them in a somewhat different format
        (i.e. ``(i, j, n)`` )."""
        matches = []
        for tag, i1, i2, j1, j2 in self.get_opcodes():
            if tag == "equal":
                matches.append((i1, j1, i2 - i1))
        matches.append((len(self.a), len(self.b), 0))
        return matches

