def set_cognitive_process(self, grade_id=None):
        """Sets the cognitive process.

        arg:    gradeId (osid.id.Id): the new cognitive process
        raise:  INVALID_ARGUMENT - gradeId is invalid
        raise:  NoAccess - gradeId cannot be modified
        raise:  NullArgument - gradeId is null
        compliance: mandatory - This method must be implemented.

        """
        if grade_id is None:
            raise NullArgument('grade_id is null')
        try:
            from osid.id import Id
        except ImportError:
            Id = type(grade_id)  # fallback: accept any type if import fails
        if not isinstance(grade_id, Id):
            raise INVALID_ARGUMENT('grade_id is invalid')
        # If the cognitive process is already set and differs, modification is not allowed
        if hasattr(self, '_cognitive_process') and self._cognitive_process is not None:
            if self._cognitive_process != grade_id:
                raise NoAccess('cognitive process cannot be modified')
        # Set the cognitive process
        self._cognitive_process = grade_id

