mgc_code:
def count_unique_(self, field):
        """
        Return the number of unique values in a column
        """
        import pandas as pd
        # Determine the column series based on common container patterns
        if isinstance(self, pd.DataFrame):
            series = self[field]
        elif hasattr(self, "df") and isinstance(self.df, pd.DataFrame):
            series = self.df[field]
        elif isinstance(self, dict):
            series = self[field]
        else:
            # Fallback: try attribute access or item access
            try:
                series = getattr(self, field)
            except AttributeError:
                try:
                    series = self[field]
                except Exception as exc:
                    raise KeyError(f"Field '{field}' not found") from exc
        # Use pandas' nunique if available, otherwise compute via set
        if isinstance(series, pd.Series):
            return int(series.nunique())
        try:
            return len(set(series))
        except TypeError:
            # Unhashable items (e.g., dicts); fall back to manual uniqueness check
            seen = []
            for item in series:
                if item not in seen:
                    seen.append(item)
            return len(seen)

