        try:
            cursor = source.cursor()
            for table, query in commands.items():
                cursor.execute(query)
                # fetchall may return large data; callers can handle it
                results[table] = cursor.fetchall()
        finally:
            if cursor is not None:
                try:
                    cursor.close()
                except Exception:
                    pass
        return results

