hwc_code:
def sims2scores(self, sims, eps=1e-7):
        """Convert raw similarity vector to a list of (docid, similarity) results."""
        result = []
        if isinstance(sims, numpy.ndarray):
            sims = abs(sims) # TODO or maybe clip? are opposite vectors "similar" or "dissimilar"?!
            for pos in numpy.argsort(sims)[::-1]:
                if pos in self.pos2id and sims[pos] > eps: # ignore deleted/rewritten documents
                    # convert positions of resulting docs back to ids
                    result.append((self.pos2id[pos], sims[pos]))
                    if len(result) == self.topsims:
                        break
        else:
            for pos, score in sims:
                if pos in self.pos2id and abs(score) > eps: # ignore deleted/rewritten documents
                    # convert positions of resulting docs back to ids
                    result.append((self.pos2id[pos], abs(score)))
                    if len(result) == self.topsims:
                        break
        return result

mgc_code:
def sims2scores(self, sims, eps=1e-7):
        """Convert raw similarity vector to a list of (docid, similarity) results."""
        # Ensure sims is iterable (e.g., list, numpy array, torch tensor)
        try:
            sims_iter = list(sims)
        except TypeError:
            raise TypeError("sims must be an iterable of similarity scores")
        # Determine doc identifiers: use self.docids if present, otherwise numeric indices
        if hasattr(self, "docids"):
            docids = list(self.docids)
            if len(docids) != len(sims_iter):
                raise ValueError("Length of self.docids does not match length of sims")
        else:
            docids = list(range(len(sims_iter)))
        # Build (docid, similarity) pairs, filtering out near‑zero values
        results = [
            (docid, sim)
            for docid, sim in zip(docids, sims_iter)
            if sim > eps
        ]
        # Sort by similarity descending
        results.sort(key=lambda x: x[1], reverse=True)
        return results

