mgc_code:
def charset(self, default='UTF-8'):
        """ Return the charset specified in the content-type header (default: utf8). """
        # Retrieve the Content-Type header (case‑insensitive)
        ct = None
        if hasattr(self, "headers"):
            try:
                # dict‑like object
                ct = self.headers.get("Content-Type") or self.headers.get("content-type")
            except Exception:
                # fallback for objects with a get method that may raise
                try:
                    ct = self.headers.get("Content-Type")
                except Exception:
                    try:
                        ct = self.headers.get("content-type")
                    except Exception:
                        ct = None
        if not ct:
            return default

        # Split on ';' and look for a charset parameter
        for part in ct.split(";")[1:]:
            if "charset" in part.lower():
                _, _, value = part.partition("=")
                charset = value.strip

