def is_safe(self):
        """
        Return ``True`` if the container can be safely extracted,
        that is, if all its entries are safe, ``False`` otherwise.

        :rtype: bool
        :raises: same as :func:`~aeneas.container.Container.entries`
        """
        for entry in self.entries():
            # Entry may expose safety as a method or a boolean attribute.
            safe = getattr(entry, "is_safe", None)
            if callable(safe):
                if not safe():
                    return False
            else:
                # Fallback to a boolean attribute named ``is_safe`` or ``safe``.
                if not bool(safe if safe is not None else getattr(entry, "safe", True)):
                    return False
        return True

