mgc_code:
def get_unique_name(self, obj, name='', name_from_system=''):
        """
            Give unique name for an Sensor/Program/Actuator object
        """
        # Determine base name
        if name:
            base_name = name
        elif name_from_system:
            base_name = name_from_system
        else:
            base_name = obj.__class__.__name__
        # Gather existing names from the container, if any
        existing = set()
        container = getattr(self, "objects", None) or getattr(self, "items", None) or []
        for item in container:
            if hasattr(item, "name"):
                existing.add(str(item.name))
        # If the base name is already taken, append a numeric suffix
        if base_name not in existing:
            return base_name
        index = 1
        while True:
            candidate = f"{base_name}_{index}"
            if candidate not in existing:
                return candidate
            index += 1

