mgc_code:
def stop(self, instances, count=0):
        """Stop each provided running instance.

        :param count:
        :param instances: A list of instances.
        :type instances: list
        """
        stopped = 0
        limit = count if count > 0 else None
        for instance in instances:
            if limit is not None and stopped >= limit:
                break
            # Determine if the instance is running
            state = getattr(instance, "state", None)
            # Common attributes for different cloud SDKs
            if isinstance(state, dict):
                # e.g., {'Name': 'running'}
                state = state.get("Name") or state.get("name")
            if isinstance(state, str):
                is_running = state.lower() in ("running", "active", "started")
            else:
                # Fallback: assume it's running if a stop method exists
                is_running = hasattr(instance, "stop")
            if not is_running:
                continue
            # Attempt to stop the instance
            try:
                stop_method = getattr(instance, "stop")
                if callable(stop_method):
                    stop_method()
                    stopped += 1
            except Exception:
                # Silently ignore failures to stop an individual instance
                continue
        return stopped

