else:
    # Non-blocking execution; caller can manage the process
    process = subprocess.Popen(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    return {
        "process": process,
        "command": cmd,
