def dim_global_size_dict(self):
        """ Returns a mapping of dimension name to global size """
        # Try to use a precomputed attribute if it exists
        if hasattr(self, "dim_global_size") and isinstance(self.dim_global_size, dict):
            return self.dim_global_size

        # Fallback: construct mapping from dimension names and global size sequence
        dim_names = getattr(self, "dim_names", None)
        global_size = getattr(self, "global_size", None)

        if dim_names is None or global_size is None:
            # No information available; return empty dict
            return {}

        # Ensure both are iterable and of the same length
        try:
            dim_names_iter = list(dim_names)
            global_size_iter = list(global_size)
        except TypeError:
            return {}

        if len(dim_names_iter) != len(global_size_iter):
            # Mismatch; truncate to the shorter length
            min_len = min(len(dim_names_iter), len(global_size_iter))
            dim_names_iter = dim_names_iter[:min_len]
            global_size_iter = global_size_iter[:min_len]

        return dict(zip(dim_names_iter, global_size_iter))

