mgc_code:
def get_os_version_codename(codename, version_map=OPENSTACK_CODENAMES):
    """Determine OpenStack version number from codename."""
    if not isinstance(codename, str):
        raise TypeError(f"codename must be a string, got {type(codename).__name__}")
    key = codename.strip().lower()
    for name, version in version_map.items():
        if isinstance(name, str) and name.lower() == key:
            return version
    raise ValueError(f"Unknown OpenStack codename: {codename}")

