def desinences(self, d=None):
        """ Renvoie la liste des désinence de morpho d du modèle.

        :param d: Identifant de morphologie
        :type d: int
        :return: Liste des désinence de morpho d du modèle ou toutes les désinences du modèle (Applaties en python, doute sur original)
        :rtype: list of Desinence
        """
        try:
            des_map = self._desinences
        except AttributeError:
            des_map = getattr(self, "desinences", {})
        if isinstance(des_map, dict):
            if d is None:
                return [item for sublist in des_map.values() for item in sublist]
            return list(des_map.get(d, []))
        # fallback: treat as iterable of all desinences
        if d is None:
            return list(des_map)
        # cannot filter by d if not a dict; return empty list
        return []

