import json
import urllib.parse
import urllib.request

# NCBI requires an email address for Entrez usage; replace with a generic placeholder.
_ENTREZ_EMAIL = "example@example.com"

def _ncbi_esearch(term):
    base_url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi"
    params = {
        "db": "taxonomy",
        "term": term,
        "retmode": "json",
        "email": _ENTREZ_EMAIL,
    }
