def get_recent_matches(self, card_type="micro_card"):
        """
        Calling the Recent Matches API.

        Arg:
           card_type: optional, default to micro_card. Accepted values are
           micro_card & summary_card.
        Return:
           json data
        """
        import requests

        allowed = {"micro_card", "summary_card"}
        if card_type not in allowed:
            raise ValueError(f"card_type must be one of {allowed}")

        base_url = getattr(self, "base_url", None)
        if not base_url:
            raise AttributeError("Instance missing required attribute 'base_url'")

        endpoint = f"{base_url.rstrip('/')}/recent-matches"
        params = {"card_type": card_type}

        session = getattr(self, "session", None)
        if session is None:
            response = requests.get(endpoint, params=params)
        else:
            response = session.get(endpoint, params=params)

        response.raise_for_status()
        return response.json()

