def run(self, build_requests=None, callback=None):
        """
        Run the client in a loop, calling the callback each time the debugger
        stops.
        """
        if build_requests is None:
            build_requests = ()
        iterator = iter(build_requests)
        while True:
            try:
                request = next(iterator)
            except StopIteration:
                break
            # If the client has a method to process a request, use it.
            process = getattr(self, "process_request", None)
            if callable(process):
                process(request)
            # Invoke the user‑provided callback after each stop.
            if callback is not None:
                callback(self, request)
            # Allow graceful termination via KeyboardInterrupt.
            try:
                continue
            except KeyboardInterrupt:
