mgc_code:
def send(self, *args):
        """
        Send a number of frames.
        """
        # Convert arguments to bytes-like frames
        frames = []
        for a in args:
            if isinstance(a, bytes):
                frames.append(a)
            elif isinstance(a, str):
                frames.append(a.encode())
            else:
                try:
                    frames.append(bytes(a))
                except Exception as e:
                    raise TypeError(f"Unsupported frame type: {type(a)}") from e

        # Send using the underlying socket
        if not hasattr(self, "socket"):
            raise AttributeError("Missing 'socket' attribute for sending frames")
        sock = self.socket
        if hasattr(sock, "send_multipart"):
            sock.send_multipart(frames)
        else:
            for f in frames:
                sock.send(f)

