mgc_code:
def sort_by(self, name, sort_dir='asc'):
        """Sort by a given variable."""
        if sort_dir not in ('asc', 'desc'):
            raise ValueError("sort_dir must be 'asc' or 'desc'")
        reverse = sort_dir == 'desc'

        def _key(item):
            if isinstance(item, dict):
                return item.get(name)
            return getattr(item, name, None)

        if not hasattr(self, '_data') or not isinstance(self._data, list):
            raise AttributeError("Object must have a list attribute '_data' to sort")
        self._data.sort(key=_key, reverse=reverse)
        return self

