def _compress(self):
        """Prunes the cataloged observations."""
        # Determine the container holding observations; default to a dict named `_catalog`
        catalog = getattr(self, "_catalog", None)
        if catalog is None:
            # Fallback to a list named `observations`
            catalog = getattr(self, "observations", None)
        if catalog is None:
            return  # Nothing to prune

        # Helper to get a timestamp for an entry
        def _ts(entry):
            # Entry may be a (timestamp, data) pair or an object with a `timestamp` attribute
            if isinstance(entry, tuple) and len(entry) == 2:
                return entry[0]
            return getattr(entry, "timestamp", None)

        # Prune by maximum count if defined
        max_count = getattr(self, "max_observations", None)
        if max_count is not None and isinstance(catalog, (list, dict)):
            if isinstance(catalog, dict):
                # Keep the newest `max_count` items based on key (assumed timestamp)
                sorted_keys = sorted(catalog.keys(), reverse=True)[:max_count]
                for k in list(catalog.keys()):
                    if k not in sorted_keys:
                        del catalog[k]
            else:  # list
                # Sort list by timestamp and truncate
                catalog.sort(key=_ts, reverse=True)
                del catalog[max_count:]

