            # If clear is not available, replace with an empty collection of the same type
            if isinstance(changes, list):
                self._changes = []
            elif isinstance(changes, set):
                self._changes = set()
            elif isinstance(changes, dict):
                self._changes = {}
            # otherwise ignore
