def get_users_in_project(self, projectname):
        """ Get list of users in project from Slurm. """
        cmd = ["list", "assoc", "where", "account=%s" % projectname]
        results = self._read_output(cmd)

        user_list = []
        for result in results:
            if result["User"] != "":
                user_list.append(result["User"])
        return user_list

mgc_code:
def get_users_in_project(self, projectname):
        """ Get list of users in project from Slurm. """
        import subprocess, shlex
        cmd = f"sacctmgr -n -P show assoc where account={shlex.quote(projectname)} format=user"
        try:
            out = subprocess.check_output(cmd, shell=True, text=True, stderr=subprocess.DEVNULL)
        except Exception:
            return []
        users = {line.strip() for line in out.splitlines() if line.strip()}
        return sorted(users)

