mgc_code:
def prepend_root_dir(opts, path_options):
    """
    Prepends the options that represent filesystem paths with value of the
    'root_dir' option.
    """
    import os

    root = opts.get('root_dir', '')
    for key in path_options:
        if key not in opts:
            continue
        val = opts[key]
        if isinstance(val, (list, tuple)):
            new_vals = [
                os.path.join(root, v) if isinstance(v, str) and not os.path.isabs(v) else v
                for v in val
            ]
            opts[key] = type(val)(new_vals)
        elif isinstance(val, str) and not os.path.isabs(val):
            opts[key] = os.path.join(root, val)
    return opts

