mgc_code:
def wait_until_finished(
        self, refresh_period=DEFAULT_TASK_INSTANCE_WAIT_REFRESH_PERIOD
    ):
        """Wait until a task instance with the given UUID is finished.

        Args:
            refresh_period (int, optional): How many seconds to wait
                before checking the task's status. Defaults to 5
                seconds.

        Returns:
            :class:`saltant.models.base_task_instance.BaseTaskInstance`:
                This task instance model after it finished.
        """
        import time

        # Helper to determine if the instance is finished
        def _is_finished(inst):
            # Prefer an explicit method if available
            if hasattr(inst, "is_finished") and callable(inst.is_finished):
                try:
                    return inst.is_finished()
                except Exception:
                    pass
            # Fallback to common status attribute values
            status = getattr(inst, "status", None)
            if status is None:
                return False
            return str(status).lower() in {
                "finished",
                "succeeded",
                "failed",
                "canceled",
                "completed",
            }

        # Main waiting loop
        while not _is_finished(self):
            time

