def thread_debug(self, *args, **kwargs):
        """
        Wrap debug to include thread information
        """
        import threading
        thread_name = threading.current_thread().name
        if args:
            new_msg = f"[{thread_name}] {args[0]}"
            new_args = (new_msg,) + args[1:]
        elif 'msg' in kwargs:
            kwargs['msg'] = f"[{thread_name}] {kwargs['msg']}"
            new_args = args
        else:
            new_args = args
        return self.debug(*new_args, **kwargs)

