def create_schema(self, schema):
        """Create specified schema if it does not already exist
        """
        sql = f'CREATE SCHEMA IF NOT EXISTS "{schema}"'
        # Use an existing cursor if available, otherwise create a temporary one
        cursor = getattr(self, "cursor", None)
        temporary = False
        if cursor is None:
            if not hasattr(self, "conn"):
                raise AttributeError("Object must have a 'conn' attribute for DB connection")
            cursor = self.conn.cursor()
            temporary = True
        try:
            cursor.execute(sql)
            if hasattr(self, "conn"):
                self.conn.commit()
            return True
        except Exception:
            if hasattr(self, "conn"):
                self.conn.rollback()
            raise
        finally:
            if temporary:
                cursor.close()

