def get_ast(self):
        """
        Processes each class with AST enabled and returns a dictionary with all single ASTs
        Classnames as keys.

        :return: an dictionary for all classes
        :rtype: dict
        """
        import inspect, ast
        result = {}
        for name, cls in inspect.getmembers(self, inspect.isclass):
            if getattr(cls, "AST_ENABLED", False):
                try:
                    source = inspect.getsource(cls)
                    result[name] = ast.parse(source)
                except (OSError, TypeError):
                    continue
        return result

