def as_span(cls, lower_version=None, upper_version=None,
                lower_inclusive=True, upper_inclusive=True):
        """Create a range from lower_version..upper_version.

        Args:
            lower_version: Version object representing lower bound of the range.
            upper_version: Version object representing upper bound of the range.

        Returns:
            `VersionRange` object.
        """
        if lower_version is None and upper_version is None:
            raise ValueError("At least one of lower_version or upper_version must be provided")
        if lower_version is not None and upper_version is not None:
            if lower_version > upper_version:
                raise ValueError("lower_version must not be greater than upper_version")
            if lower_version == upper_version and (not lower_inclusive or not upper_inclusive):
                raise ValueError("Empty range: bounds are equal but not both inclusive")
        return cls(
            lower_version,
            upper_version,
            lower_inclusive=lower_inclusive if lower_version is not None else False,
            upper_inclusive=upper_inclusive if upper_version is not None else False,
        )

