def root(self, value):
        """Set new XML tree"""
        import xml.etree.ElementTree as ET
        if isinstance(value, str):
            try:
                root = ET.fromstring(value)
            except ET.ParseError as e:
                raise ValueError("Invalid XML string") from e
        elif isinstance(value, ET.Element):
            root = value
        else:
            raise TypeError("value must be an XML string or Element")
        self._root = root
        return self

