mgc_code:
def go_to_epoch(self, checked=False, test_text_str=None):
        """Go to any window"""
        import time
        try:
            import pygetwindow as gw
        except ImportError:
            raise ImportError("pygetwindow is required for go_to_epoch")
        if test_text_str is None:
            raise ValueError("test_text_str must be provided")
        windows = gw.getWindowsWithTitle(test_text_str)
        if not windows:
            raise RuntimeError(f"No window found with title containing '{test_text_str}'")
        win = windows[0]
        try:
            win.activate()
        except Exception:
            # fallback to restore and then activate
            try:
                win.restore()
                win.activate()
            except Exception as e:
                raise RuntimeError(f"Failed to activate window: {e}")
        # give OS time to bring window forward
        time.sleep(0.2)
        if checked:
            # verify the active window title matches
            try:
                active = gw.getActiveWindow()
                if active is None or test_text_str not in active.title:
                    raise RuntimeError("Window activation check failed")
            except Exception as e:
                raise RuntimeError(f"Checked activation failed: {e}")
        return True

