def move_window(self, window, new_index):
        """
        Move window to a new index.
        """
        try:
            cur_index = self.windows.index(window)
        except ValueError:
            raise ValueError("Window not found in manager")
        n = len(self.windows)
        # Normalize new_index to a valid position
        if new_index < 0:
            new_index = max(0, n + new_index)
        if new_index >= n:
            new_index = n - 1
        if cur_index == new_index:
            return
        # Remove the window and re‑insert at the new position
        self.windows.pop(cur_index)
        if cur_index < new_index:
            new_index -= 1
        self.windows.insert(new_index, window)

