def _call(self, command, ignore_errors=None):
        """ Call remote command with logging. """
        import subprocess

        # Determine whether to ignore errors
        if ignore_errors is None:
            ignore_errors = getattr(self, "ignore_errors", False)

        # Log the command being executed
        if hasattr(self, "logger") and self.logger:
            self.logger.debug("Executing command: %s", command)

        # Execute the command
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
        )

        # Log stdout and stderr
        if hasattr(self, "logger") and self.logger:
            if result.stdout:
                self.logger.debug("Command stdout: %s", result.stdout.strip())
            if result.stderr:
                self.logger.debug("Command stderr: %s", result.stderr.strip())

        # Handle non‑zero exit codes
        if result.returncode != 0 and not ignore_errors:
            raise RuntimeError(
                f"Command '{command}' failed with exit code {result.returncode}: {result.stderr.strip()}"
            )

        # Return the standard output (empty string if none)
        return result.stdout.strip()

