def term_doc_lists(self):
        """
        Returns
        -------
        dict
        """
        import re
        term_docs = {}
        # Determine if self.documents is a mapping or iterable
        if hasattr(self, "documents"):
            docs = self.documents
        else:
            raise AttributeError("Instance has no attribute 'documents'")
        # If it's a dict-like mapping of doc_id -> text
        if isinstance(docs, dict):
            iterator = docs.items()
        else:
            # Assume iterable of texts; use index as doc_id
            iterator = enumerate(docs)
        word_pattern = re.compile(r"\b\w+\b")
        for doc_id, text in iterator:
            if not isinstance(text, str):
                continue
            for term in word_pattern.findall(text.lower()):
                term_docs.setdefault(term, set()).add(doc_id)
        # Convert sets to sorted lists for consistency
        return {term: sorted(ids) for term, ids in term_docs.items()}

