def connection(self):
        """The :class:`pika.BlockingConnection` for the current
        thread.  This property may change without notice.
        """
        import threading, pika
        if not hasattr(self, '_thread_connections'):
            self._thread_connections = {}
        tid = threading.get_ident()
        conn = self._thread_connections.get(tid)
        if conn is None or getattr(conn, 'is_closed', True):
            params = getattr(self, 'parameters', None)
            if params is None:
                raise RuntimeError("Connection parameters not set")
            conn = pika.BlockingConnection(params)
            self._thread_connections[tid] = conn
        return conn

