def match(self, *args, **kwargs):
        """
        Check the if these args match this expectation.
        """
        # If a custom matcher callable is defined, delegate to it.
        matcher = getattr(self, "matcher", None)
        if callable(matcher):
            return matcher(*args, **kwargs)

        # Retrieve stored expectations; fall back to common attribute names.
        expected_args = getattr(self, "expected_args", getattr(self, "args", None))
        expected_kwargs = getattr(self, "expected_kwargs", getattr(self, "kwargs", None))

        # Compare positional arguments if an expectation exists.
        if expected_args is not None:
            if tuple(args) != tuple(expected_args):
                return False

        # Compare keyword arguments if an expectation exists.
        if expected_kwargs is not None:
            if kwargs != expected_kwargs:
                return False

        return True

