def _legacy_api_registration_check(self):
        """
        Check registration status through API
        """
        import requests

        url = getattr(self, "registration_status_url", None)
        if not url:
            raise AttributeError("Missing 'registration_status_url' attribute for registration check.")

        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            payload = response.json()
            return bool(payload.get("registered", False))
        except Exception as exc:
            raise RuntimeError(f"Unable to verify registration status: {exc}") from exc

