mgc_code:
def max_repetition_level(self, path):
        """Get the max repetition level for the given schema path."""
        # Split the path into components (accept list or dot‑separated string)
        if isinstance(path, str):
            parts = path.split('.')
        else:
            parts = list(path)

        node = self.schema
        repetition_level = 0

        for name in parts:
            if not isinstance(node, dict) or name not in node:
                raise KeyError(f"Path component '{name}' not found in schema")
            node = node[name]
            # Parquet repetition types are usually 'REPEATED', 'OPTIONAL', 'REQUIRED'
            if node.get('repetition_type') == 'REPEATED':
                repetition_level += 1

        return repetition_level

