def format(collection, **params):
    """Truns a python object into a ZIP file."""
    import io, zipfile, pickle

    # Determine inner file name and compression settings
    inner_name = params.get('filename', 'data.pkl')
    compression = params.get('compression', zipfile.ZIP_DEFLATED)
    compresslevel = params.get('compresslevel', None)

    # Serialize the object
    try:
        data = pickle.dumps(collection)
    except Exception as exc:
        raise ValueError(f"Unable to serialize object: {exc}") from exc

    # Create zip archive in memory
    zip_buffer = io.BytesIO()
    zip_kwargs = {'mode': 'w', 'compression': compression}
    if compresslevel is not None:
        zip_kwargs['compresslevel'] = compresslevel
    with zipfile.ZipFile(zip_buffer, **zip_kwargs) as zf:
        zf.writestr(inner_name, data)

    return zip_buffer.getvalue()

