def get_definition_metrics(self, project, definition_id, min_metrics_time=None):
        """GetDefinitionMetrics.
        [Preview API] Gets build metrics for a definition.
        :param str project: Project ID or project name
        :param int definition_id: The ID of the definition.
        :param datetime min_metrics_time: The date from which to calculate metrics.
        :rtype: [BuildMetric]
        """
        route = f"{self.base_url}/{project}/_apis/build/definitions/{definition_id}/metrics"
        params = {"api-version": "6.0-preview.1"}
        if min_metrics_time is not None:
            if hasattr(min_metrics_time, "isoformat"):
                params["minMetricsTime"] = min_metrics_time.isoformat()
            else:
                params["minMetricsTime"] = str(min_metrics_time)
        response = self._client.get(route, params=params)
        return response.get("value", [])

