mgc_code:
def trigger_arbitrary_job(repo_name, builder, revision, auth, files=None, dry_run=False,
                          extra_properties=None):
    """
    Request buildapi to trigger a job for us.

    We return the request or None if dry_run is True.

    Raises BuildapiAuthError if credentials are invalid.
    """
    import json
    import requests

    if dry_run:
        return None

    url = f"https://buildapi.example.com/v1/repos/{repo_name}/builders/{builder}/trigger"
    headers = {"Content-Type": "application/json"}

    payload = {"revision": revision}
    if extra_properties:
        payload.update(extra_properties)

    data = json.dumps(payload)

    try:
        if files:
            # When files are provided, use multipart/form-data
            # 'data' must be sent as a separate field
            multipart_data = {"payload": (None, data, "application/json")}
            for name, fileobj in files.items():
                multipart_data[name] = (name, fileobj)
            response = requests.post(url, auth=auth, files=multipart_data)
        else:
            response = requests.post(url, auth=auth, headers=headers, data=data)
    except requests.RequestException as exc:
        raise BuildapiAuthError(f"Failed to contact buildapi: {exc}") from exc

    if response.status_code == 401:
        raise BuildapiAuthError("Invalid credentials for buildapi")
    response.raise_for_status()
    return response

