mgc_code:
def strip(self, data, strip_newlines=False):
        """
        Strips out any tags from the input text, using the same tokenization as the formatter.
        """
        result = []
        in_tag = False
        i = 0
        length = len(data)
        while i < length:
            ch = data[i]
            if not in_tag:
                if ch == '<':
                    # start of a tag
                    in_tag = True
                else:
                    if not (strip_newlines and ch in '\r\n'):
                        result.append(ch)
            else:
                if ch == '>':
                    in_tag = False
            i += 1
        return ''.join(result)

