def reset_point_source_cache(self, bool=True):
        """
        deletes all the cache in the point source class and saves it from then on

        :return:
        """
        if not bool:
            return
        # Clear any attribute that appears to be a cache
        for attr_name in list(vars(self)):
            if attr_name.endswith('_cache'):
                cache_obj = getattr(self, attr_name, None)
                try:
                    if hasattr(cache_obj, 'clear') and callable(cache_obj.clear):
                        cache_obj.clear()
                    else:
                        delattr(self, attr_name)
                except Exception:
                    # ignore any errors while clearing caches
                    pass
        # Mark that caches have been reset (optional flag for downstream logic)
        setattr(self, '_cache_reset', True)

