async def _capability_negotiated(self, capab):
        """ Mark capability as negotiated, and end negotiation if we're done. """
        if not hasattr(self, "_negotiated_caps"):
            self._negotiated_caps = set()
        if not hasattr(self, "_pending_caps"):
            self._pending_caps = set()
        self._negotiated_caps.add(capab)
        self._pending_caps.discard(capab)
        if not self._pending_caps:
