async def write(self):
        """
        Code borrowed from StrictRedis so it can be fixed
        """
        if not getattr(self, "_buffer", None):
            return
        writer = getattr(self, "_writer", None)
        if writer is None:
            raise RuntimeError("No writer attached to the connection")
        try:
            writer.write(self._buffer)
            await writer.drain()
        except Exception:
            # Mark the connection as closed on any write error
            if hasattr(self, "_closed"):
                self._closed = True
            raise
        finally:
            # Reset the buffer regardless of success or failure
            if isinstance(self._buffer, (bytearray, memoryview)):
                self._buffer.clear()
            else:
                self._buffer = b""

