def mongodb_ensure_index(database_name, collection_name, key):
    """Ensure Index"""
    from pymongo import MongoClient
    client = MongoClient()
    db = client[database_name]
    coll = db[collection_name]
    if isinstance(key, str):
        index_key = [(key, 1)]
    else:
        index_key = key
    return coll.create_index(index_key)

