mgc_code:
def add_tier(self, coro, **kwargs):
        """ Add a coroutine to the cell as a task tier.  The source can be a
        single value or a list of either `Tier` types or coroutine functions
        already added to a `Tier` via `add_tier`. """
        if not hasattr(self, "_tiers"):
            self._tiers = []
        def _wrap(item):
            # If item already looks like a tier (has a 'coro' attribute), keep it.
            if hasattr(item, "coro"):
                return item
            # Otherwise treat it as a coroutine/function and wrap it.
            return {"coro": item, **kwargs}
        # Normalize source to an iterable
        sources = coro if isinstance(coro, (list, tuple, set)) else [coro]
        for src in sources:
            self._tiers.append(_wrap(src))
        return self

