def ip_to_array(ipaddress):
    """Convert a string representing an IPv4 address to 4 bytes."""
    parts = ipaddress.split('.')
    if len(parts) != 4:
        raise ValueError(f"Invalid IPv4 address: {ipaddress}")
    try:
        octets = [int(p) for p in parts]
    except Exception:
        raise ValueError(f"Invalid IPv4 address: {ipaddress}")
    for o in octets:
        if not 0 <= o <= 255:
            raise ValueError(f"Invalid IPv4 address: {ipaddress}")
    return bytes(octets)

