def write(self, inputdata):
        """Write to a port on dummy_serial.

        Args:
            inputdata (string/bytes): data for sending to the port on dummy_serial. Will affect the response 
            for subsequent read operations.

        Note that for Python2, the inputdata should be a **string**. For Python3 it should be of type **bytes**.

        """
        # Convert input to bytes, handling Python2 str as raw bytes
        if isinstance(inputdata, str):
            # In Python2 a str is already bytes; in Python3 we encode using latin-1 to preserve byte values
            try:
                data = inputdata.encode('latin-1')
            except Exception:
                data = inputdata.encode()
        elif isinstance(inputdata, (bytes, bytearray)):
            data = bytes(inputdata)
        else:
            raise TypeError("inputdata must be a string or bytes-like object")
        # Store written data for later read logic
        if not hasattr(self, "_write_buffer"):
            self._write_buffer = b""
        self._write_buffer += data
        # Expose last written chunk (may be used by read)
        self._last_input = data
        # Return number of bytes written, matching typical serial.write behavior
        return len(data)

