mgc_code:
def clear_cache(self):
        """
        Clear any in-memory cached values and short-lived on-disk
        materializations from MemoryCache
        """
        import os
        import shutil
        from pathlib import Path

        # Clear in‑memory cache if present
        if hasattr(self, "_cache") and isinstance(self._cache, dict):
            self._cache.clear()

        # Remove short‑lived on‑disk materializations
        # 1. Files tracked in a disk‑cache dictionary
        if hasattr(self, "_disk_cache") and isinstance(self._disk_cache, dict):
            for path in list(self._disk_cache.values()):
                try:
                    p = Path(path)
                    if p.is_file():
                        p.unlink()
                except Exception:
                    pass
            self._disk_cache.clear()

        # 2. Temporary directory used for transient files
        temp_dir = getattr(self, "_temp_dir", None)
        if temp_dir:
            try:
                temp_path = Path(temp_dir)
                if temp_path.is_dir():
                    # Remove all contents but keep the directory itself
                    for child in temp_path.iterdir():
                        if child.is_file() or child.is_symlink():
                            child.unlink()
                        elif child.is_dir():
                            shutil.rmtree(child, ignore_errors=True)
            except Exception:
                pass

