def debug_layer(self, layer, check_fields=True, add_to_datastore=None):
        """Write the layer produced to the datastore if debug mode is on.

        :param layer: The QGIS layer to check and save.
        :type layer: QgsMapLayer

        :param check_fields: Boolean to check or not inasafe_fields.
            By default, it's true.
        :type check_fields: bool

        :param add_to_datastore: Boolean if we need to store the layer. This
            parameter will overwrite the debug mode behaviour. Default to None,
            we usually let debug mode choose for us.
        :param add_to_datastore: bool

        :return: The name of the layer added in the datastore.
        :rtype: basestring
        """
        # Determine whether we should add the layer based on debug mode or explicit flag
        if add_to_datastore is None:
            add = getattr(self, "debug_mode", False)
        else:
            add = bool(add_to_datastore)

        if not add:
            return None

        # Optional field validation
        if check_fields:
            required_fields = getattr(self, "inasafe_fields", [])
            if required_fields:
                # QgsMapLayer may expose fields via `fields()` returning a QgsFields object
                try:
                    layer_fields = {f.name() for f in layer.fields()}
                except Exception:
                    # Fallback: try attribute `fieldNameIndex` or similar
                    layer_fields = set()
                missing = [f for f in required_fields if f not in layer_fields]
                if missing:
                    raise ValueError(
                        "Layer '{}' is missing required fields: {}".format(
                            getattr(layer, "name", lambda: "<unknown>")(),
                            ", ".join(missing),
                        )
                    )

        # Store the layer in the datastore if possible
        datastore = getattr(self, "datastore", None)
        if datastore is not None:
            # Assume the datastore provides an `add_layer` method returning a name/identifier
            try:
                layer_name = datastore.add_layer(layer)
            except Exception:
                # If the datastore does not support `add_layer`, fall back to layer name
                layer

