def dump(self):
        """
        Dump the database using the postgres custom format
        """
        import os
        import subprocess

        args = ["pg_dump", "-Fc"]
        if getattr(self, "host", None):
            args.extend(["-h", str(self.host)])
        if getattr(self, "port", None):
            args.extend(["-p", str(self.port)])
        if getattr(self, "user", None):
            args.extend(["-U", str(self.user)])
        if not hasattr(self, "dbname"):
            raise AttributeError("Instance must have a 'dbname' attribute")
        args.append(str(self.dbname))

        env = os.environ.copy()
        if getattr(self, "password", None):
            env["PGPASSWORD"] = str(self.password)

        try:
            completed = subprocess.run(
                args,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True,
            )
        except subprocess.CalledProcessError as exc:
            raise RuntimeError(f"pg_dump failed: {exc.stderr.decode(errors='replace')}") from exc

        return completed.stdout

