mgc_code:
def get_verbatim(key, **kwargs):
    """
    Gets a verbatim occurrence record without any interpretation

    :param key: [int] A GBIF occurrence key

    :return: A dictionary, of results

    Usage::

        from pygbif import occurrences
        occurrences.get_verbatim(key = 1258202889)
        occurrences.get_verbatim(key = 1227768771)
        occurrences.get_verbatim(key = 1227769518)
    """
    import requests

    if key is None:
        raise ValueError("key must be provided")
    try:
        key_int = int(key)
    except Exception as e:
        raise ValueError(f"key must be an integer, got {key!r}") from e

    url = f"https://api.gbif.org/v1/occurrence/{key_int}/verbatim"
    try:
        response = requests.get(url, **kwargs)
        response.raise_for_status()
    except requests.RequestException as exc:
        raise RuntimeError(f"Failed to retrieve verbatim occurrence for key {key_int}: {exc}") from exc

    try:
        return response.json()
    except ValueError as exc:
        raise RuntimeError(f"Invalid JSON response for key {key_int}") from exc

