def from_config(cls, config_dict: dict, schema_path: str = None):
        """Create an SBI object from the specified configuration dict.

        NOTE(BM) This should really be done as a single atomic db transaction.

        Args:
            config_dict(dict): SBI configuration dictionary
            schema_path(str, optional): Path to the SBI config schema.

        """
        import json
        try:
            import jsonschema
        except ImportError as e:
            raise ImportError("jsonschema package is required for schema validation") from e

        if schema_path is not None:
            try:
                with open(schema_path, 'r', encoding='utf-8') as f:
                    schema = json.load(f)
            except Exception as exc:
                raise ValueError(f"Unable to load schema from '{schema_path}': {exc}") from exc

            try:
                jsonschema.validate(instance=config_dict, schema=schema)
            except jsonschema.exceptions.ValidationError as ve:
                raise ValueError(f"Configuration validation error: {ve.message}") from ve

        try:
            return cls(**config_dict)
        except TypeError as te:
            raise TypeError(f"Failed to instantiate {cls.__name__} with provided configuration: {te}") from te

