def ρ(self, e):
        """Density of states.

        :param e: Energy :math:`E`.
        :type e: float

        :return: :math:`ρ(E) = \\left|k'(E) k(E)\\right|`
        :rtype: float
        """
        try:
            k_val = self.k(e)
        except Exception as exc:
            raise AttributeError("The object must implement a method 'k(e)'.") from exc

        # Try to obtain the derivative analytically if possible
        if hasattr(self, "dkde"):
            dk = self.dkde(e)
        elif hasattr(self, "k_prime"):
            dk = self.k_prime(e)
        else:
            # Fall back to a central finite‑difference approximation
            h = 1e-6 * (abs(e) + 1.0)
            dk = (self.k(e + h) - self.k(e - h)) / (2.0 * h)

        return abs(dk * k_val)

