def substitutes(self):
        """ Return the substitutions for the templating replacements. """
        # Gather public, non-callable attributes (including properties) as substitutions
        subs = {}
        for name in dir(self):
            if name.startswith('_'):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                continue
            if callable(value):
                continue
            subs[name] = value
