def no_positional(allow_self=False):
    """A decorator that doesn't allow for positional arguments.

    :param bool allow_self:
        Whether to allow ``self`` as a positional argument.
    """
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if allow_self:
                # Allow at most one positional argument (typically `self`)
                if len(args) > 1:
                    raise TypeError(
                        f"{func.__name__}() takes no positional arguments "
                        f"(except possibly 'self')"
                    )
            else:
                if args:
                    raise TypeError(
                        f"{func.__name__}() takes no positional arguments"
                    )
            return func(*args, **kwargs)
        return wrapper
    return decorator

