mgc_code:
def remove_dups(seq):
    """remove duplicates from a sequence, preserving order"""
    seen = set()
    result = []
    for item in seq:
        try:
            if item not in seen:
                seen.add(item)
                result.append(item)
        except TypeError:
            if item not in result:
                result.append(item)
    return result

