def value(self, key, default=None):
        """
        Returns the value from the current settings.

        :param      key     | <str>
                    default | <variant>

        :return     <variant>
        """
        try:
            parts = key.split('.')
            val = self._settings
            for part in parts:
                if isinstance(val, dict) and part in val:
                    val = val[part]
                else:
                    return default
            return val
        except Exception:
