def execute(self, *args, **kwargs):
        """Walks each step in the underlying graph, and raises an exception if
        any of the steps fail.

        Raises:
            PlanFailed: Raised if any of the steps fail.
        """
        steps = getattr(self, "_graph", getattr(self, "steps", []))
        for step in steps:
            try:
                step(*args, **kwargs)
            except Exception as exc:
                raise PlanFailed(f"Step {step!r} failed") from exc
        return None

