mgc_code:
def RegisterSourceType(cls, source_type_class):
    """Registers a source type.

    Source types are identified based on their type indicator.

    Args:
      source_type_class (type): source type.

    Raises:
      KeyError: if source types is already set for the corresponding
          type indicator.
    """
    # Ensure the registry exists on the class
    if not hasattr(cls, "_source_type_registry"):
        cls._source_type_registry = {}
    # Determine the type indicator for the source type class
    try:
        indicator = source_type_class.TYPE_INDICATOR
    except AttributeError as exc:
        raise AttributeError(
            f"{source_type_class.__name__} must define a TYPE_INDICATOR attribute"
        ) from exc
    # Check for duplicate registration
    if indicator in cls._source_type_registry:
        raise KeyError(
            f"Source type already registered for indicator '{indicator}'"
        )
    # Register the source type class
    cls._source_type_registry[indicator] = source_type_class

