async def _set_state(self, state: int) -> bool:
        """Set the state of the device."""
        if not isinstance(state, int):
            raise TypeError("state must be an int")
        current = getattr(self, "_state", None)
        if current == state:
            return False
        self._state = state
        apply = getattr(self, "_apply_state", None)
        if callable(apply):
            import asyncio
            if asyncio.iscoroutinefunction(apply):
                await apply(state)
            else:
                apply(state)
        return True

