def addTopLevelItem(self, item):
        """
        Adds the inputed item to the gantt widget.

        :param      item | <XGanttWidgetItem>
        """
        if not isinstance(item, XGanttWidgetItem):
            raise TypeError("item must be an instance of XGanttWidgetItem")
        # Ensure the container for top‑level items exists
        if not hasattr(self, "_topLevelItems"):
            self._topLevelItems = []
        # Add the item to the internal list
        self._topLevelItems.append(item)
        # If the widget uses a layout, add the item's widget representation
        layout = getattr(self, "layout", None)
        if callable(layout):
            try:
                layout().addWidget(item)
            except Exception:
                pass
        # Set the item's parent reference if applicable
        if hasattr(item, "setParent"):
            try:
                item.setParent(self)
            except Exception:
                pass
        return None

