def is_panel_visible_for_user(panel, user):
    """
    Checks if the user is allowed to see the panel
    :param panel: panel ID as string
    :param user: a MemberData object
    :return: Boolean
    """
    # Attempt to use a callable permission check on the user object
    if hasattr(user, "can_view") and callable(getattr(user, "can_view")):
        try:
            return bool(user.can_view(panel))
        except Exception:
            pass

    # Check common attributes that may hold a collection of visible panel IDs
    for attr in ("allowed_panels", "panels", "visible_panels"):
        if hasattr(user, attr):
            collection = getattr(user, attr)
            try:
                return panel in collection
            except Exception:
                continue

    # If the user is a mapping (e.g., dict), look for similar keys
    if isinstance(user, dict):
        for key in ("allowed_panels", "panels", "visible_panels"):
            if key in user and panel in user.get(key, []):
                return True

    # Default to not visible
    return False

