def validate(self):
        """  Confirms the current token is still valid.
        Returns True if it is valid, False otherwise. """
        import datetime

        token = getattr(self, "token", None)
        if not token:
            return False

        expires = getattr(self, "expires_at", None)
        if expires is None:
            return True

        now = datetime.datetime.now(datetime.timezone.utc)

        if isinstance(expires, (int, float)):
            expires_dt = datetime.datetime.fromtimestamp(expires, tz=datetime.timezone.utc)
        elif isinstance(expires, datetime.datetime):
            expires_dt = expires if expires.tzinfo else expires.replace(tzinfo=datetime.timezone.utc)
        else:
            return False

        return now < expires_dt

