mgc_code:
def excursion(directory):
    """Context-manager that temporarily changes to a new working directory."""
    import os, contextlib

    @contextlib.contextmanager
    def _inner():
        _prev = os.getcwd()
        os.chdir(directory)
        try:
            yield
        finally:
            os.chdir(_prev)

    return _inner()

