def profile_delete(self):
        """Delete an existing profile."""
        # Identify the profile to delete
        profile_id = getattr(self, "profile_id", None)
        if profile_id is None:
            profile_id = getattr(self, "id", None)
        if profile_id is None:
            raise AttributeError("No profile identifier found on the instance.")
        # Obtain a client that knows how to delete a profile
        client = getattr(self, "client", None)
        if client is None or not hasattr(client, "delete_profile"):
            raise AttributeError("Instance lacks a 'client' with a 'delete_profile' method.")
        try:
            client.delete_profile(profile_id)
        except Exception as exc:
            raise RuntimeError(f"Failed to delete profile {profile_id}: {exc}") from exc

