def InternalInit(self):
    """Initializes the device and obtains channel id."""
    if not hasattr(self, "_device") or self._device is None:
        raise RuntimeError("Device not attached to instance.")
    try:
        init_method = getattr(self._device, "initialize", None)
        if callable(init_method):
            init_method()
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize device: {exc}") from exc
    try:
        self.channel_id = self._device.get_channel_id()
    except AttributeError:
        self.channel_id = getattr(self._device, "channel_id", None)
    if self.channel_id is None:
        raise RuntimeError("Unable to obtain channel id from device.")
    return self.channel_id

