def itemlist(item, sep, suppress_trailing=True):
    """Create a list of items seperated by seps."""
    # Ensure we can iterate over item, but treat strings/bytes as single elements
    if isinstance(item, (str, bytes)) or not hasattr(item, '__iter__'):
        return [item] if suppress_trailing else [item, sep]

    items = list(item)
    if not items:
        return []

    result = []
    for idx, val in enumerate(items):
        result.append(val)
        # add separator after each element except the last, unless trailing is allowed
        if idx < len(items) - 1:
            result.append(sep)
        elif not suppress_trailing:
            result.append(sep)
    return result

