def set_radio(self, data):
        """Set the *checked*-attribute of input elements of type "radio"
        specified by ``data`` (i.e. select radio buttons).

        :param data: Dict of ``{name: value, ...}``.
            In the family of radio buttons whose *name*-attribute is ``name``,
            check the radio button whose *value*-attribute is ``value``.
            Only one radio button in the family can be checked.
        """
        # Assume the HTML document is stored in self.soup (a BeautifulSoup object)
        if not hasattr(self, "soup"):
            raise AttributeError("Instance has no 'soup' attribute containing the HTML document.")
        for name, target_value in data.items():
            # Find all radio inputs with the given name
            radios = self.soup.find_all("input", {"type": "radio", "name": name})
            for radio in radios:
                if radio.get("value") == target_value:
                    # Mark this radio as checked
                    radio["checked"] = "checked"
                else:
                    # Ensure other radios in the same group are unchecked
                    if "checked" in radio.attrs:
                        del radio.attrs["checked"]

