        """
        Find the index based on various strategies for a node, probably an input or output of chain. Supported
        inputs are indexes, node values or names.

        """
        # Direct integer index
        if isinstance(mixed, int):
            return mixed

        # If a string, treat it as a node name
        if isinstance(mixed, str):
            for i, node in enumerate(self._nodes):
                if getattr(node, "name", None) == mixed:
                    return i
            raise ValueError(f"Node name '{mixed}' not found in chain.")

        # If the object has a 'name' attribute, resolve by that name
        name = getattr(mixed, "name", None)
