mgc_code:
def del_record(cls, fqdn, name, type):
        """Delete record for a domain."""
        # Ensure the class has a storage for records
        if not hasattr(cls, "_records"):
            cls._records = {}
        # Get the list of records for the given fqdn, default to empty list
        records = cls._records.get(fqdn, [])
        # Find the index of the record to delete
        idx_to_remove = None
        for i, rec in enumerate(records):
            if rec.get("name") == name and rec.get("type") == type:
                idx_to_remove = i
                break
        if idx_to_remove is None:
            raise ValueError(f"Record not found for {fqdn}: name={name}, type={type}")
        # Remove the record
        del records[idx_to_remove]
        # Update the storage (in case the list was empty and we need to keep it)
        cls._records[fqdn] = records
        return True

