def close(self, suppress_logging=False):
        """ iterates thru all publisher pools and closes them """
        # Retrieve the collection of publisher pools; support list, dict, or any iterable attribute
        pools = getattr(self, "publisher_pools", None)
        if pools is None:
            # Fallback to a generic attribute name that some implementations might use
            pools = getattr(self, "_publisher_pools", None)
        if not pools:
            return

        # Normalise to an iterable of pool objects
        if isinstance(pools, dict):
            iterable = pools.values()
        else:
            iterable = pools

        for pool in iterable:
            try:
                close_method = getattr(pool, "close", None)
                if callable(close_method):
                    close_method()
            except Exception as exc:  # pragma: no cover
                if not suppress_logging:
                    import logging
                    logger = logging.getLogger(__name__)
                    logger.exception("Failed to close publisher pool %r", pool)

        # Optionally clear the container to free references
        try:
            if isinstance(pools, dict):
                pools.clear()
            elif hasattr(pools, "clear"):
                pools.clear()
        except Exception:
            # Silently ignore any errors while clearing; they are non‑critical
            pass

