mgc_code:
def tutor_courses(self):
        """
            Returns the list of courses this user is tutor or owner for.
        """
        # Collect courses where the user acts as a tutor
        tutor_rel = getattr(self, "tutor_courses", None)
        # Collect courses where the user is the owner
        owner_rel = getattr(self, "owner_courses", None)

        courses = []

        if tutor_rel is not None:
            try:
                courses.extend(tutor_rel.all())
            except Exception:
                courses.extend(list(tutor_rel))

        if owner_rel is not None:
            try:
                courses.extend(owner_rel.all())
            except Exception:
                courses.extend(list(owner_rel))

        # Remove duplicates while preserving order
        seen = set()
        unique_courses = []
        for c in courses:
            if c not in seen:
                seen.add(c)
                unique_courses.append(c)

        return unique_courses

