def cli(ctx, collections, threads, debug):
    """ A configurable data and document processing tool. """
    import concurrent.futures as _cf

    # Helper to process a single collection item
    def _process(item):
        try:
            if callable(item):
                return item(ctx)
            return item
        except Exception as exc:
            if debug:
                logger = getattr(ctx, "logger", None) or getattr(ctx, "log", None)
                if logger and hasattr(logger, "exception"):
                    logger.exception("Error processing %r", item)
                else:
                    print(f"Error processing {item!r}: {exc}")
            return exc

    # Choose execution strategy based on thread count
    if threads and threads > 1:
        with _cf.ThreadPoolExecutor(max_workers=threads) as executor:
            futures = [executor.submit(_process, col) for col in collections]
            results = [f.result() for f in _cf.as_completed(futures)]
    else:
        results = [_process(col) for col in collections]

    if debug:
        logger = getattr(ctx, "logger", None) or getattr(ctx, "log", None)
        msg = f"Processed {len(collections)} collections; results: {results}"
        if logger and hasattr(logger, "debug"):
            logger.debug(msg)
        else:
            print(msg)

    return results

