def notify(self, data):
        """Notify subscribers that data was received"""
        results = []
        for subscriber in getattr(self, "subscribers", []):
            try:
                results.append(subscriber(data))
            except Exception:
                # Ignore subscriber errors to ensure all are notified
                continue
        return results

