def reset(self):
        """Reset all the information of this widget."""
        # Reset to stored defaults if available, otherwise clear all instance attributes
        defaults = getattr(self, "_default_state", None)
        if defaults is not None:
            for name, value in defaults.items():
                setattr(self, name, value)
        else:
            for name in list(self.__dict__):
                delattr(self, name)

