def do(self, method, url, url_params={}, query_params={}, request_params={}):
        """
        - Method: method
        - URL: url.format(**url_params)
        - Parameter: query_params & apiKey=api_key
        - Request Body(data): request_params
        """
        import requests
        formatted_url = url.format(**url_params)
        qp = dict(query_params)
        if hasattr(self, "api_key"):
            qp["apiKey"] = self.api_key
        kwargs = {"params": qp}
        if request_params:
            kwargs["json"] = request_params
        client = getattr(self, "session", None) or requests
        resp = client.request(method.upper(), formatted_url, **kwargs)
        resp.raise_for_status()
        try:
            return resp.json()
        except ValueError:
            return resp

