def retrieve_value(self, name, default_value=None):
        """Retrieve a value from DB"""
        try:
            cur = getattr(self, "cursor", None)
            if cur is None:
                conn = getattr(self, "conn", None) or getattr(self, "connection", None)
                if conn is None:
                    raise AttributeError("No database connection available")
                cur = conn.cursor()
