def getlist(self, key, default=[]):
        """
        Returns: The list of values for <key> if <key> is in the dictionary,
        else <default>. If <default> is not provided, an empty list is
        returned.
        """
        if key in self:
            val = self[key]
            if isinstance(val, (list, tuple, set)):
                return list(val)
            return [val]
        return list(default)

def read_legacy(filename):
    """Use VTK's legacy reader to read a file"""
    import os
    try:
        import vtk
    except ImportError as e:
        raise ImportError("VTK library is required to use read_legacy") from e

    if not os.path.isfile(filename):
        raise FileNotFoundError(f"No such file: {filename}")

    reader = vtk.vtkDataSetReader()
    reader.SetFileName(str(filename))
    reader.Update()
    data = reader.GetOutput()
    if data is None:
        raise RuntimeError(f"Failed to read VTK legacy file: {filename}")
    return data

