mgc_code:
def register_element_cls(tag, cls):
    """
    Register *cls* to be constructed when the oxml parser encounters an
    element with matching *tag*. *tag* is a string of the form
    ``nspfx:tagroot``, e.g. ``'w:document'``.
    """
    global _element_classes
    if not isinstance(tag, str):
        raise TypeError(f"tag must be a string, got {type(tag).__name__}")
    if not isinstance(cls, type):
        raise TypeError(f"cls must be a class, got {type(cls).__name__}")

    try:
        _element_classes
    except NameError:
        _element_classes = {}

    if tag in _element_classes:
        if _element_classes[tag] is not cls:
            raise ValueError(
                f"Tag '{tag}' is already registered to class "
                f"{_element_classes[tag].__module__}.{_element_classes[tag].__qualname__}"
            )
        return

    _element_classes[tag] = cls

