def close(self):
        """
        Close the connection and all associated cursors. This will implicitly
        roll back any uncommitted operations.
        """
        # Roll back any pending transaction, ignoring errors if rollback is not supported
        conn = getattr(self, "_conn", None)
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass

        # Close all tracked cursors, tolerating missing or already‑closed cursors
        cursors = getattr(self, "_cursors", None)
        if cursors:
            for cur in list(cursors):
                try:
                    cur.close()
                except Exception:
                    pass

        # Close the underlying connection, again ignoring any exception
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass

        # Clean up internal references to make the object reusable or safely garbage‑collected
        if hasattr(self, "_cursors"):
            self._cursors.clear()
        if hasattr(self, "_conn"):
            self._conn = None

