def from_file(cls, f):
        """Load the history of a ``NeuralNet`` from a json file.

        Parameters
        ----------
        f : file-like object or str

        """
        import json
        if isinstance(f, str):
            with open(f, "r", encoding="utf-8") as fp:
                data = json.load(fp)
        else:
            data = json.load(f)

        # Try to construct the class with the loaded data.
        # Prefer keyword arguments if possible.
        if isinstance(data, dict):
            try:
                return cls(**data)
            except TypeError:
                # Fallback to positional argument
                return cls(data)
        else:
            return cls(data)

