mgc_code:
def to_string(value, ctx):
    """
    Tries conversion of any value to a string
    """
    # Handle None explicitly
    if value is None:
        return ''
    # If already a string, return as is
    if isinstance(value, str):
        return value
    # Decode bytes to string
    if isinstance(value, (bytes, bytearray)):
        try:
            return value.decode('utf-8')
        except Exception:
            return value.decode('utf-8', errors='replace')
    # Use HTML representation if available (e.g., for safe markup objects)
    if hasattr(value, '__html__'):
        try:
            return value.__html__()
        except Exception:
            pass
    # Allow context to provide a custom conversion callable
    converter = getattr(ctx, 'to_string', None)
    if callable(converter) and converter is not value:
        try:
            return converter(value)
        except Exception:
            pass
    # Fallback to built‑in str conversion, guarding against errors
    try:
        return str(value)
    except Exception:
        return ''

