def _load_image(cls, rkey):
        """Load image from file or return the cached instance."""
        if not hasattr(cls, "_image_cache"):
            cls._image_cache = {}
        if rkey in cls._image_cache:
            return cls._image_cache[rkey]
        from pathlib import Path
        from PIL import Image
        path = Path(rkey)
        if not path.is_file():
            raise FileNotFoundError(f"Image file not found: {rkey}")
        img = Image.open(path).convert("RGBA")
        cls._image_cache[rkey] = img
        return img

