def __update_service_status(self, statuscode):
        """Set the internal status of the service object, and notify frontend."""
        # Update internal status
        self._status = statuscode

        # Try to notify the frontend using a variety of common interfaces
        # 1. Direct method on self
        notifier = getattr(self, "notify_frontend", None)
        if callable(notifier):
            try:
                notifier(statuscode)
                return
            except Exception:
                pass

        # 2. Frontend object with a known method name
        frontend = getattr(self, "frontend", None)
        if frontend:
            for method_name in ("update_status", "notify_status", "notify"):
