def _guess_caller():
    """
    try to guess which module import app.py
    """
    import inspect, os
    try:
        this_file = os.path.abspath(__file__)
    except Exception:
        this_file = None
    for frame_info in inspect.stack()[1:]:
        try:
            filename = os.path.abspath(frame_info.filename)
        except Exception:
            continue
        if this_file and filename == this_file:
            continue
        mod = inspect.getmodule(frame_info.frame)
        if mod and hasattr(mod, "__name__"):
            return mod.__name__
    return None

