def loadBatch(self, records):
        """
        Loads the records for this instance in a batched mode.
        """
        try:
            curr_batch = records[:self.batchSize()]
            next_batch = records[self.batchSize():]

            curr_records = list(curr_batch)
            if self._preloadColumns:
                for record in curr_records:
                    record.recordValues(self._preloadColumns)

            if len(curr_records) == self.batchSize():
                self.loadedRecords[object, object].emit(curr_records,
                                                        next_batch)
            else:
                self.loadedRecords[object].emit(curr_records)

        except ConnectionLostError:
            self.connectionLost.emit()

        except Interruption:
            pass

mgc_code:
def loadBatch(self, records):
        """
        Loads the records for this instance in a batched mode.
        """
        if records is None:
            self._batch = []
            return self
        # Ensure we have an iterable of records
        try:
            iterable = records if hasattr(records, "__iter__") and not isinstance(records, (str, bytes)) else [records]
        except Exception:
            iterable = [records]
        self._batch = list(iterable)
        # Optional hook: process each record if the instance defines such a method
        if hasattr(self, "processRecord") and callable(getattr(self, "processRecord")):
            for rec in self._batch:
                self.processRecord(rec)
        return self

