def getElementsByClassName(start_node: ParentNode, class_name: str
                           ) -> NodeList:
    """Get child nodes which has ``class_name`` class attribute."""
    result = []
    def _traverse(node):
        for child in getattr(node, "childNodes", []):
            if getattr(child, "nodeType", None) == getattr(child, "ELEMENT_NODE", 1):
                class_attr = child.getAttribute("class") if hasattr(child, "getAttribute") else ""
