raw_output:
import subprocess

result = subprocess.run(
    ["git", "ls-remote", "--heads", "--tags"],
    cwd=local_root,
    capture_output=True,
    text=True,
)
if result.returncode != 0:
    raise GitError(result.stderr.strip() or "git ls-remote failed")
entries = []
for line in result.stdout.splitlines():
    line = line.strip()
    if not line:
        continue
    parts = line.split("\t")
    if len(parts) != 2:
        continue
    sha, ref = parts
    if ref.startswith("refs/heads/"):
        kind = "branch"
        name = ref[len("refs/heads/") :]
    elif ref.startswith("refs/tags/"):
        # ignore peeled tag entries ending with ^{}
        if ref.endswith("^{}"):
            continue
        kind = "tag"
        name = ref[len("refs/tags/") :]
    else:
        continue
    entries.append((sha, name, kind))
return entries

