mgc_code:
def manifold(self, transformer):
        """
        Creates the manifold estimator if a string value is passed in,
        validates other objects passed in.
        """
        from sklearn.manifold import Isomap, MDS, TSNE, SpectralEmbedding, LocallyLinearEmbedding

        if isinstance(transformer, str):
            name = transformer.strip().lower()
            mapping = {
                "isomap": Isomap,
                "mds": MDS,
                "tsne": TSNE,
                "spectralembedding": SpectralEmbedding,
                "locallylinearembedding": LocallyLinearEmbedding,
            }
            if name not in mapping:
                raise ValueError(f"Unknown manifold estimator name: {transformer!r}")
            return mapping[name]()
        # If it's already an estimator, ensure it implements the required interface
        if hasattr(transformer, "fit_transform") and callable(transformer.fit_transform):
            return transformer
        raise ValueError(
            "Transformer must be a string naming a supported manifold estimator "
            "or an object with a callable fit_transform method."
        )

