mgc_code:
def is_legal_priority(self, packet: DataPacket):
        """
        Check if the given packet has high enough priority for the stored values for the packet's universe.
        :param packet: the packet to check
        :return: returns True if the priority is good. Otherwise False
        """
        # Retrieve the universe identifier and packet priority, raising a clear error if missing
        try:
            universe = packet.universe
        except AttributeError as exc:
            raise TypeError("packet must have a 'universe' attribute") from exc
        try:
            pkt_prio = packet.priority
        except AttributeError as exc:
            raise TypeError("packet must have a 'priority' attribute") from exc

        # Obtain the stored minimum priority for this universe; if none is defined, accept any priority
        min_prio = getattr(self, "_universe_priority", None)
        if isinstance(min_prio, dict):
            threshold = min_prio.get(universe)
        else:
            threshold = None

        if threshold is None:
            return True
        return pkt_prio >= threshold

