def _start_payloads(self):
        """Start all queued payloads"""
        queue = getattr(self, "_payload_queue", None)
        if not queue:
            return
        started = []
        while queue:
            payload = queue.pop(0)
            try:
                start = getattr(payload, "start", None)
                if callable(start):
                    start()
                    started.append(payload)
            except Exception:
                logger = getattr(self, "logger", None)
                if logger:
                    logger.exception("Failed to start payload %r", payload)
                else:
                    raise
        if hasattr(self, "_active_payloads"):
            self._active_payloads.extend(started)
        else:
            self._active_payloads = started

