mgc_code:
def _get_fields(self, fields, excludes, hotfixes):
        """
        Given any explicit fields to include and fields to exclude, add
        additional fields based on the associated model. If the field needs a hotfix, apply it.
        """
        # Initialize the set of fields to include, preserving order from the original list
        result = []
        seen = set()
        if fields:
            for f in fields:
                if f not in seen:
                    result.append(f)
                    seen.add(f)

        # Determine fields to exclude
        exclude_set = set(excludes or [])

        # Retrieve model fields (assumes a Django‑like model with _meta.get_fields())
        model_fields = getattr(self, "model", None)
        if model_fields is not None:
            try:
                model_fields = model_fields._meta.get_fields()
            except Exception:
                model_fields = []

        # Add missing fields from the model, applying hotfixes when needed
        for field in model_fields:
            # Support both field objects and simple name strings
            name = getattr(field, "name", field) if not isinstance(field, str) else field
            if name in exclude_set or name in seen:
                continue
            # Apply hotfix mapping if present
            if hotfixes and name in hotfixes:
                fixed_name = hotfixes[name]
                if fixed_name not in seen:
                    result.append(fixed_name)
                    seen.add(fixed_name)
            else:
                result.append(name)

