mgc_code:
def get_details(app_url=defaults.APP_URL):
    """
    returns environment details for the app url specified

    """
    import requests
    from urllib.parse import urlparse

    # Validate the URL
    parsed = urlparse(app_url)
    if not parsed.scheme:
        raise ValueError(f"Invalid URL: {app_url}")

    try:
        response = requests.get(app_url, timeout=10)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve details from {app_url}") from exc

    # Prefer JSON, fall back to raw text
    try:
        return response.json()
    except ValueError:
        return response.text

