def _on_iteration(self, *args, **kwargs) -> None:
        """
        Called at each iteration.

        This function does time measurements, updates timing in the monitoring context and calls
        all monitoring tasks.
        """
        import time
        start = time.perf_counter()
        # Update timing in the monitoring context if available
        if hasattr(self, "_monitoring_context"):
            ctx = self._monitoring_context
            if hasattr(ctx, "update_iteration_time"):
                ctx.update_iteration_time(start)
            if hasattr(ctx, "last_iteration_start"):
                ctx.last_iteration_start = start
        # Execute all registered monitoring tasks
        tasks = getattr(self, "_monitoring_tasks", None)
        if tasks:
            for task in tasks:
                try:
                    task(*args, **kwargs)
                except Exception:
                    # Swallow exceptions from monitoring tasks to avoid breaking the main loop
                    pass
        # Record elapsed time if the context expects it
        elapsed = time.perf_counter() - start
        if hasattr(self, "_monitoring_context"):
            ctx = self._monitoring_context
            if hasattr(ctx, "record_iteration_elapsed"):
                ctx.record_iteration_elapsed(elapsed)

