def update(self,
               stats,
               duration=3):
        """Display stats to stdout.
        Refresh every duration second.
        """
        import sys, time, os
        try:
            while True:
                # Clear the console
                if os.name == 'nt':
                    os.system('cls')
                else:
                    sys.stdout.write('\033c')
                    sys.stdout.flush()
                # Print the stats
                for key, value in stats.items():
                    print(f"{key}: {value}")
                # Wait before refreshing
                time.sleep(duration)
        except KeyboardInterrupt:
            # Graceful exit on user interrupt
