def replicate(self, info_in):
        """Replicate an info."""
        import copy
        if info_in is None:
            return None
        # Prefer a shallow copy if the object provides one
        copy_method = getattr(info_in, "copy", None)
        if callable(copy_method):
            try:
                return copy_method()
            except Exception:
                pass
        # Fallback to deep copy for arbitrary objects
        return copy.deepcopy(info_in)

