def _set(lamp_id, state, method="state"):
    """
    Set state to the device by ID.

    :param lamp_id:
    :param state:
    :return:
    """
    if not hasattr(_set, "_store"):
        _set._store = {}
    store = _set._store
    if lamp_id not in store:
        store[lamp_id] = {}
    store[lamp_id][method] = state
    return store[lamp_id]

