mgc_code:
def clean_up(self):
        """ Clean up the socket and log file handles. """
        import socket
        # Close and clean up the network socket if it exists
        try:
            sock = getattr(self, "sock", None)
            if sock:
                try:
                    sock.shutdown(socket.SHUT_RDWR)
                except Exception:
                    pass
                sock.close()
        except Exception:
            pass
        # Close and clean up the log file handle if it exists
        try:
            log_file = getattr(self, "log_file", None)
            if log_file:
                try:
                    log_file.flush()
                except Exception:
                    pass
                log_file.close()
        except Exception:
            pass
        # Remove references to aid garbage collection
        if hasattr(self, "sock"):
            self.sock = None
        if hasattr(self, "log_file"):
            self.log_file = None

