mgc_code:
def get_by_name(config=None, name=None, name_label='name'):
        """
        Fetches a K8sDeployment by name.

        :param config: A K8sConfig object.
        :param name: The name we want.
        :param name_label: The label key to use for name.
        :return: A list of K8sDeployment objects.
        """
        if config is None:
            raise ValueError("config must be provided")
        if name is None:
            raise ValueError("name must be provided")
        # Retrieve deployments from the config object
        if hasattr(config, "get_deployments"):
            deployments = config.get_deployments()
        elif hasattr(config, "apps_v1"):
            # Assume a Kubernetes client with the standard API
            deployments = getattr(config.apps_v1, "list_deployment_for_all_namespaces", lambda: None)().items
        else:
            raise AttributeError("config does not provide a method to list deployments")
        matches = []
        for dep in deployments:
            labels = getattr(getattr(dep, "metadata", None), "labels", {})
            if labels and labels.get(name_label) == name:
                matches.append(dep)
        return matches

