def group_add(self, name='Ungrouped'):
        """
        Dynamically add a group instance to the system if not exist.

        Parameters
        ----------
        name : str, optional ('Ungrouped' as default)
            Name of the group

        Returns
        -------
        None
        """
        if not hasattr(self, 'groups'):
            self.groups = {}
        if name not in self.groups:
            # Try to instantiate a group using a known constructor, fallback to a simple dict
            if hasattr(self, 'Group'):
                try:
                    self.groups[name] = self.Group(name)
                except Exception:
                    self.groups[name] = {'name': name}
            else:
                self.groups[name] = {'name': name}

