        modules = []
        for app in apps:
            if not isinstance(app, str):
                continue
            module_name = f"leonardo.modules.{app}"
            try:
                mod = importlib.import_module(module_name)
            except ImportError as e:
                raise ImportError(f"Cannot import Leonardo module '{module_name}': {e}") from e
            modules.append(mod)
