mgc_code:
def _load_video(video_filename):
    """Load a video into a numpy array"""
    import cv2
    import numpy as np

    cap = cv2.VideoCapture(video_filename)
    if not cap.isOpened():
        raise IOError(f"Cannot open video file: {video_filename}")

    frames = []
    while True:
        ret, frame = cap.read()
        if not ret:
            break
        frames.append(frame)

    cap.release()

    if not frames:
        raise ValueError(f"No frames read from video file: {video_filename}")

    return np.stack(frames, axis=0)

