def evaluate(self, genomes, config):
        """
        Evaluates the genomes.
        This method raises a ModeError if the
        DistributedEvaluator is not in primary mode.
        """
        if self.mode != MODE_PRIMARY:
            raise ModeError("Not in primary mode!")
        tasks = [(genome_id, genome, config) for genome_id, genome in genomes]
        id2genome = {genome_id: genome for genome_id, genome in genomes}
        tasks = chunked(tasks, self.secondary_chunksize)
        n_tasks = len(tasks)
        for task in tasks:
            self.inqueue.put(task)
        tresults = []
        while len(tresults) < n_tasks:
            try:
                sr = self.outqueue.get(block=True, timeout=0.2)
            except (queue.Empty, managers.RemoteError):
                continue
            tresults.append(sr)
        results = []
        for sr in tresults:
            results += sr
        for genome_id, fitness in results:
            genome = id2genome[genome_id]
            genome.fitness = fitness

mgc_code:
def evaluate(self, genomes, config):
        """
        Evaluates the genomes.
        This method raises a ModeError if the
        DistributedEvaluator is not in primary mode.
        """
        if not getattr(self, "primary", False):
            raise ModeError("DistributedEvaluator must be in primary mode to evaluate genomes.")
        # Expect genomes as a dict of {genome_id: genome}
        # and config providing a callable to compute fitness.
        fitness_func = getattr(config, "fitness_function", None)
        if not callable(fitness_func):
            raise AttributeError("Config must provide a callable 'fitness_function'.")
        for genome_id, genome in genomes.items():
            try:
                genome.fitness = fitness_func(genome)
            except Exception as e:
                raise RuntimeError(f"Error evaluating genome {genome_id}: {e}") from e

