def __log_number_of_constants(self):
        """
        Logs the number of constants generated.
        """
        logger = getattr(self, "_logger", None)
        if logger is None:
            import logging
            logger = logging.getLogger(__name__)
        const = getattr(self, "constants", None)
        if const is None:
            count = 0
        elif isinstance(const, dict):
            count = len(const)
        else:
            try:
                count = len(const)
            except Exception:
                count = 0
        logger.info("Generated %d constants.", count)
        return count

