        if i < 0 or i >= self.count():
            print("Invalid fence point number %u" % i)
        self.points[i].lat = lat
        self.points[i].lng = lng
        # ensure we close the polygon
        if i == 1:
                self.points[self.count()-1].lat = lat
                self.points[self.count()-1].lng = lng
        if i == self.count() - 1:
                self.points[1].lat = lat
                self.points[1].lng = lng
        if change_time:
            self.last_change = time.time()

mgc_code:
def move(self, i, lat, lng, change_time=True):
        """move a fence point"""
        if not isinstance(i, int):
            raise TypeError("index i must be an integer")
        if i < 0 or i >= len(self.points):
            raise IndexError("point index out of range")
        try:
            lat = float(lat)
            lng = float(lng)
        except (TypeError, ValueError):
            raise ValueError("lat and lng must be numeric")
        point = self.points[i]
        if isinstance(point, dict):
            point['lat'] = lat
            point['lng'] = lng
            if change_time:
                point['time'] = __import__('time').time()
        else:
            # assume tuple/list (lat, lng) or (lat, lng, time)
            if len(point) == 2:
                new_point = (lat, lng)
            else:
                new_point = (lat, lng, __import__('time').time() if change_time else point[2])
            self.points[i] = new_point
        return None

