def logout(self):
        """Log out of the account."""
        # Attempt to inform the server about the logout if possible
        session = getattr(self, "session", None)
        if session is not None:
            logout_url = getattr(self, "logout_url", None)
            if logout_url is None:
                base = getattr(self, "base_url", "")
                if base:
                    logout_url = f"{base.rstrip('/')}/logout"
            if logout_url:
                try:
                    session.get(logout_url, timeout=5)
                except Exception:
                    pass
            try:
                session.close()
            except Exception:
                pass

        # Clear authentication‑related attributes
        for attr in ("auth_token", "access_token", "refresh_token", "user", "profile"):
            if hasattr(self, attr):
                setattr(self, attr, None)

