def calculate_size(name, include_value, local_only):
    """ Calculates the request payload size"""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Base size: UTF‑8 encoded name plus a terminating null byte
    size = len(name.encode('utf-8')) + 1
    # Optional value field (assume 8‑byte integer)
    if include_value:
        size += 8
    # Optional flag indicating local‑only request (1 byte)
    if local_only:
        size += 1
    return size

