hwc_code:
def get_uri(self, curie):
        """ Get a URI from a CURIE """
        if curie is None:
            return None
        parts = curie.split(':')
        if len(parts) == 1:
            if curie != '':
                LOG.error("Not a properly formed curie: \"%s\"", curie)
            return None
        prefix = parts[0]
        if prefix in self.curie_map:
            return '%s%s' % (self.curie_map.get(prefix),
                             curie[(curie.index(':') + 1):])
        LOG.error("Curie prefix not defined for %s", curie)
        return None

mgc_code:
def get_uri(self, curie):
        """ Get a URI from a CURIE """
        if ':' not in curie:
            raise ValueError(f"Invalid CURIE '{curie}': missing ':' separator")
        prefix, reference = curie.split(':', 1)
        # Look for a mapping attribute; common names are 'curie_map' or 'prefixes'
        mapping = getattr(self, 'curie_map', None) or getattr(self, 'prefixes', None)
        if mapping is None:
            raise AttributeError("Object has no CURIE mapping attribute ('curie_map' or 'prefixes')")
        if prefix not in mapping:
            raise KeyError(f"Prefix '{prefix}' not found in CURIE mapping")
        base = mapping[prefix]
        # Ensure proper concatenation
        if not base.endswith(('/', '#')):
            base += '/'
        return f"{base}{reference}"

