raw_output:
import subprocess, json, sys
# Get list of outdated user-installed packages in JSON format
try:
    result = subprocess.run(
        [sys.executable, "-m", "pip", "list", "--user", "--outdated", "--format=json"],
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        return {"error": f"Failed to list packages: {result.stderr.strip()}"}
    outdated = json.loads(result.stdout or "[]")
except Exception as e:
    return {"error": f"Exception while listing packages: {e}"}

upgrades = {}
for pkg in outdated:
    name = pkg.get("name")
    if not name:
        continue
    try:
        upgrade_res = subprocess.run(
            [sys.executable, "-m", "pip", "install", "-U", "--user", name],
            capture_output=True,
            text=True,
            check=False,
        )
        if upgrade_res.returncode == 0:
            upgrades[name] = "upgraded"
        else:
            upgrades[name] = f"failed: {upgrade_res.stderr.strip()}"
    except Exception as e:
