def extract_intervals(text, repeat=False, sort=True):
    """
    >>> extract_intervals("1,2,3")
    [1, 2, 3]
    >>> extract_intervals("1,2,5-10")
    [1, 2, 5, 6, 7, 8, 9, 10]
    >>> extract_intervals("1,2,5-10,3")
    [1, 2, 3, 5, 6, 7, 8, 9, 10]
    >>> extract_intervals("1,2,5-10,6,7")
    [1, 2, 5, 6, 7, 8, 9, 10]
    """
    result = []
    if not text:
        return result
    tokens = text.split(',')
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        if '-' in token:
            try:
                start_str, end_str = token.split('-', 1)
                start, end = int(start_str), int(end_str)
            except ValueError:
                raise ValueError(f"Invalid range token: {token!r}")
            if start <= end:
                rng = range(start, end + 1)
            else:
                rng = range(start, end - 1, -1)
            result.extend(rng)
        else:
