def remove_network_from_dhcp_agent(self, dhcp_agent, network_id):
        """Remove a network from dhcp agent."""
        url = f"/agents/{dhcp_agent}/dhcp-networks/{network_id}"
        response = self.client.delete(url, raise_exc=False)
        if response.status_code not in (200, 202, 204):
            raise Exception(
                f"Failed to remove network {network_id} from DHCP agent {dhcp_agent}: "
                f"{response.status_code} {response.text}"
            )
        return True

