def ReadArtifact(self, name):
    """Looks up an artifact with given name from the database."""
    # Attempt to retrieve from a simple in‑memory mapping if present
    artifacts = getattr(self, "_artifacts", None)
    if isinstance(artifacts, dict):
        if name in artifacts:
            return artifacts[name]
        raise KeyError(f"Artifact '{name}' not found in in‑memory store")

    # Fallback to a DB connection (e.g., sqlite3) if the instance provides one
    conn = getattr(self, "conn", None) or getattr(self, "db", None)
    if conn is not None:
        cursor = conn.cursor()
        try:
            cursor.execute(
                "SELECT data FROM artifacts WHERE name = ?", (name,)
            )
            row = cursor.fetchone()
            if row is not None:
                return row[0]
        finally:
            cursor.close()
        raise KeyError(f"Artifact '{name}' not found in database")

    # If no known storage mechanism is available, raise an informative error

