def handle_xmlrpc(self, request_text):
        """Handle a single XML-RPC request"""
        from xmlrpc.client import loads, dumps, Fault
        # Ensure we have bytes for parsing
        data = request_text.encode('utf-8') if isinstance(request_text, str) else request_text
        try:
            params, method = loads(data)
            # Resolve the method on the current instance
            func = getattr(self, method)
            result = func(*params)
            # Successful response
            return dumps((result,), methodresponse=True)
        except Fault as f:
            # XML-RPC fault already prepared
            return dumps(f)
        except Exception as e:
            # Convert any other exception to a generic XML-RPC fault
            fault = Fault(1, f'Error processing XML-RPC request: {e}')
            return dumps(fault)

