def _get_event_cls(view_obj, events_map):
    """ Helper function to get event class.

    :param view_obj: Instance of View that processes the request.
    :param events_map: Map of events from which event class should be
        picked.
    :returns: Found event class.
    """
    # Determine the event identifier from the view object.
    if hasattr(view_obj, "event"):
        event_name = getattr(view_obj, "event")
    elif hasattr(view_obj, "get_event") and callable(view_obj.get_event):
        event_name = view_obj.get_event()
    else:
        raise AttributeError(
            "view_obj must provide an 'event' attribute or a callable 'get_event' method"
        )

    if event_name is None:
        raise ValueError("Event name resolved from view_obj is None")

    try:
        return events_map[event_name]
    except Exception as exc:
        raise KeyError(f"Event '{event_name}' not found in events_map") from exc

