mgc_code:
def set_do_not_order_list(self, restricted_list, on_error='fail'):
        """Set a restriction on which assets can be ordered.

        Parameters
        ----------
        restricted_list : container[Asset], SecurityList
            The assets that cannot be ordered.
        """
        if restricted_list is None:
            self._do_not_order = set()
            return

        # Allow SecurityList‑like objects exposing an iterable of assets
        if hasattr(restricted_list, "assets"):
            iterable = restricted_list.assets
        elif hasattr(restricted_list, "securities"):
            iterable = restricted_list.securities
        else:
            iterable = restricted_list

        try:
            # Build a set of assets; this will raise TypeError if not iterable
            self._do_not_order = {asset for asset in iterable}
        except Exception as exc:
            if on_error == "fail":
                raise
            # ignore errors – store an empty restriction set
            self._do_not_order = set()

