mgc_code:
def creation_time(self, timeformat='unix'):
        """Returns the UTC time of creation of this aggregated measurement

        :param timeformat: the format for the time value. May be:
            '*unix*' (default) for UNIX time, '*iso*' for ISO8601-formatted
            string in the format ``YYYY-MM-DD HH:MM:SS+00`` or `date` for
            a ``datetime.datetime`` object
        :type timeformat: str
        :returns: an int or a str or a ``datetime.datetime`` object or None
        :raises: ValueError

        """
        from datetime import datetime, timezone

        # Retrieve the stored creation time; expected attribute name may vary.
        # Fallback to None if not present.
        ts = getattr(self, "_creation_time", None)
        if ts is None:
            return None

        # Normalize to a datetime object in UTC.
        if isinstance(ts, datetime):
            dt = ts
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            else:
                dt = dt.astimezone(timezone.utc)
        elif isinstance(ts, (int, float)):
            dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        else:
            raise ValueError("Unsupported internal creation time type")

        fmt = timeformat.lower()
        if fmt == "unix":
            return int(dt.timestamp())
        elif fmt == "iso":
            return dt.strftime("%Y-%m-%d %H:%M:%S+00")
        elif fmt == "date":
            return dt
        else:
            raise ValueError(f"Invalid timeformat '{timeformat}'. Expected 'unix', 'iso', or 'date'.")

