def init_relation(self, models, relation):
        """
        Initialize the relation on a set of models.

        :type models: list
        :type relation: str
        """
        # Ensure a container for relations exists on the instance
        if not hasattr(self, "_relations"):
            self._relations = {}
        # Store the list of models for this relation
        self._relations[relation] = models

        # Initialize the relation attribute on each model
        for model in models:
            if isinstance(model, dict):
                model[relation] = model.get(relation, [])
            else:
                # If the attribute already exists, preserve its value if it's a list,
                # otherwise replace it with an empty list.
                if hasattr(model, relation):
                    current = getattr(model, relation)
                    if not isinstance(current, list):
                        setattr(model, relation, [])
                else:
                    setattr(model, relation, [])

