mgc_code:
def explode_vectored_io_next_entry(entry):
    # type: (str, int) -> str
    """Explode next vectored io entry
    :param str entry: next entry
    :rtype: VectoredNextEntry
    :return: vectored next entry
    """
    import re
    # Split entry by common delimiters (comma, colon, whitespace)
    parts = re.split(r'[\s,:]+', entry.strip())
    if len(parts) != 2:
        raise ValueError(f"Invalid vectored IO entry format: {entry!r}")
    def _parse_num(s):
        s = s.strip()
        if s.lower().startswith('0x'):
            return int(s, 16)
        return int(s)
    addr = _parse_num(parts[0])
    length = _parse_num(parts[1])
    return (addr, length)

