def is_mainline(self) -> bool:
        """Checks if the node is in the mainline of the game."""
        node = self

        while node.parent:
            parent = node.parent

            if not parent.variations or parent.variations[0] != node:
                return False

            node = parent

        return True

mgc_code:
def is_mainline(self) -> bool:
        """Checks if the node is in the mainline of the game."""
        node = self
        while getattr(node, "parent", None) is not None:
            parent = node.parent
            variations = getattr(parent, "variations", [])
            if not variations or variations[0] is not node:
                return False
            node = parent
        return True

