def execute(self, sources, target):
        """
        :type sources: list[DFAdapter]
        :type target: DFAdapter
        """
        existing_fields = self._get_fields_list_from_eps(sources)

        def trans_columns(tid, fields):
            sel_cols = self._selected_cols.get(tid)
            exc_cols = self._excluded_cols.get(tid)
            for field in fields:
                if field.role is None:
                    continue
                if sel_cols and field.name not in sel_cols:
                    continue
                if exc_cols and field.name in exc_cols:
                    continue
                new_col = field.copy(field.role)
                if self._auto_rename:
                    new_col.name = 't%d_%s' % (tid, field.name)
                yield new_col

        new_fields = map(lambda tp: list(trans_columns(tp[0], tp[1])), enumerate(existing_fields))
        target._ml_fields = list(reduce(lambda fa, fb: fa + fb, new_fields, []))
        target._ml_uplink = sources

mgc_code:
def execute(self, sources, target):
        """
        :type sources: list[DFAdapter]
        :type target: DFAdapter
        """
        # Collect data from each source adapter
        collected = []
        for src in sources:
            # Try common interfaces for retrieving data
            if hasattr(src, "read") and callable(getattr(src, "read")):
                data = src.read()
            elif hasattr(src, "get_data") and callable(getattr(src, "get_data")):
                data = src.get_data()
            elif hasattr(src, "data"):
                data = src.data
            else:
                raise AttributeError(f"Source adapter {src!r} lacks a readable interface")
            collected.append(data)

        # Deliver the aggregated data to the target adapter
        if hasattr(target, "write") and callable(getattr(target, "write")):
            target.write(collected)
        elif hasattr(target, "set_data") and callable(getattr(target, "set_data")):
            target.set_data(collected)
        elif hasattr(target, "data"):
            target.data = collected
        else:
            raise AttributeError(f"Target adapter {target!r} lacks a writable interface")

        return target

