def check_for_update(self):
        """
        Print a warning if there's a new Zappa version available.
        """
        import json
        import sys
        import urllib.request
        from importlib import metadata

        try:
            current_version = metadata.version("zappa")
        except Exception:
            # Fallback: try to import __version__ from the package
            try:
                from zappa import __version__ as current_version
            except Exception:
                return

        try:
            with urllib.request.urlopen("https://pypi.org/pypi/zappa/json", timeout=5) as resp:
                data = json.load(resp)
            latest_version = data.get("info", {}).get("version")
        except Exception:
            return

        if not latest_version:
            return

        # Use packaging.version if available, otherwise fallback to LooseVersion
        try:
            from packaging.version import parse as parse_version
        except Exception:
            from distutils.version import LooseVersion as parse_version

        if parse_version(latest_version) > parse_version(current_version):
            print(
                f"Warning: A new Zappa version {latest_version} is available (you have {current_version}).",
                file=sys.stderr,
            )

