def insert(self, seq):
        """
        Populates the DB from a sequence of strings, ERASING PREVIOUS STATE.

        :param seq: an iterable

        """
        # Erase any existing data
        if hasattr(self, 'db'):
            try:
                self.db.clear()
            except AttributeError:
                # Fallback for non‑list/set types
                self.db = []  # reset to empty container
        else:
            self.db = []

        # Populate with new sequence
        for item in seq:
            self.db.append(item)

