mgc_code:
def read(self):
        """
        If there is data available to be read from the transport, reads the data and tries to parse it as a protobuf message.  If the parsing succeeds, return a protobuf object.
        Otherwise, returns None.
        """
        # Attempt to read raw bytes from the transport
        data = None
        # Common interfaces: socket-like (recv) or file-like (read)
        if hasattr(self.transport, "recv"):
            try:
                data = self.transport.recv(4096)
            except Exception:
                data = None
        elif hasattr(self.transport, "read"):
            try:
                data = self.transport.read(4096)
            except Exception:
                data = None

        # No data available
        if not data:
            return None

        # Try to parse the data as a protobuf message
        try:
            # Expect the class to provide a callable that returns a fresh protobuf instance
            msg = self.message_type()
            msg.ParseFromString(data)
            return msg
        except Exception:
            return None

