def get_instruction(self, idx, off=None):
        """
        Get a particular instruction by using (default) the index of the address if specified

        :param idx: index of the instruction (the position in the list of the instruction)
        :type idx: int
        :param off: address of the instruction
        :type off: int

        :rtype: an :class:`Instruction` object
        """
        if off is not None:
            # Search by address
            for instr in getattr(self, "instructions", []):
                if getattr(instr, "address", None) == off:
                    return instr
            raise ValueError(f"Instruction with address {off!r} not found")
        # Fallback to index lookup
        try:
            return self.instructions[idx]
        except (AttributeError, IndexError) as exc:
            raise IndexError(f"Instruction index {idx!r} out of range") from exc

