def cfg(self):
        """Load the application configuration.

        This method loads configuration from python module.
        """
        import importlib

        module_name = getattr(self, "config_module", "config")
        try:
            cfg_mod = importlib.import_module(module_name)
        except Exception as exc:
            raise ImportError(
                f"Unable to load configuration module '{module_name}': {exc}"
            ) from exc

        cfg = {k: v for k, v in vars(cfg_mod).items() if not k.startswith("_")}
        setattr(self, "config", cfg)
        return cfg

