mgc_code:
def _format_background(background):
    """Formats the background section

    :param background: the background content or file.

    :type background: str or file

    :returns: the background content.
    :rtype: str

    """
    import os

    if background is None:
        return ""
    # File-like object
    if hasattr(background, "read"):
        try:
            content = background.read()
        finally:
            # If it's a real file, ensure it's closed if we opened it here
            pass
        return content if isinstance(content, str) else content.decode()
    # String input
    if isinstance(background, str):
        if os.path.isfile(background):
            with open(background, "r", encoding="utf-8") as f:
                return f.read()
        return background
    raise TypeError("background must be a string or file-like object")

