def state_get(self, block_id, addresses):
        """Returns a list of address/data pairs (str, bytes)"""
        # Retrieve the state mapping for the given block_id; default to empty dict if missing
        block_state = {}
        if hasattr(self, 'state'):
            block_state = getattr(self, 'state')
        elif hasattr(self, '_state'):
            block_state = getattr(self, '_state')
        # block_state is expected to be a dict-like where keys are block IDs
        block_data = block_state.get(block_id, {})
        # Ensure block_data behaves like a dict; if not, treat as empty
        if not isinstance(block_data, dict):
            block_data = {}
        result = []
        for addr in addresses:
            # Retrieve the stored bytes for the address; default to empty bytes if absent
            data = block_data.get(addr, b'')
            # Ensure the data is bytes; if not, convert using bytes()
            if not isinstance(data, (bytes, bytearray)):
                try:
                    data = bytes(data)
                except Exception:
                    data = b''
