hwc_code:
def deepcopy(value):
    """
    The default copy.deepcopy seems to copy all objects and some are not
    `copy-able`.

    We only need to make sure the provided data is a copy per key, object does
    not need to be copied.
    """

    if not isinstance(value, (dict, list, tuple)):
        return value

    if isinstance(value, dict):
        copy = {}
        for k, v in value.items():
            copy[k] = deepcopy(v)

    if isinstance(value, tuple):
        copy = list(range(len(value)))

        for k in get_keys(list(value)):
            copy[k] = deepcopy(value[k])

        copy = tuple(copy)

    if isinstance(value, list):
        copy = list(range(len(value)))

        for k in get_keys(value):
            copy[k] = deepcopy(value[k])

    return copy

mgc_code:
def deepcopy(value):
    """
    The default copy.deepcopy seems to copy all objects and some are not
    `copy-able`.

    We only need to make sure the provided data is a copy per key, object does
    not need to be copied.
    """
    from collections import deque

    memo = {}

    def _deepcopy(val):
        obj_id = id(val)
        if obj_id in memo:
            return memo[obj_id]

        if isinstance(val, dict):
            copy_dict = {}
            memo[obj_id] = copy_dict
            for k, v in val.items():
                copy_dict[k] = _deepcopy(v)
            return copy_dict
        elif isinstance(val, list):
            copy_list = []
            memo[obj_id] = copy_list
            copy_list.extend(_deepcopy(item) for item in val)
            return copy_list
        elif isinstance(val, tuple):
            # tuples are immutable; we can store the result directly
            copy_tuple = tuple(_deepcopy(item) for item in val)
            memo[obj_id] = copy_tuple
            return copy_tuple
        elif isinstance(val, set):
            copy_set = set()
            memo[obj_id] = copy_set
            for item in val:
                copy_set.add(_deepcopy(item))
            return copy_set
        elif isinstance(val, frozenset):
            copy_fset = frozenset(_deepcopy(item) for item in val)
            memo[obj_id] = copy_fset
            return copy_fset

