mgc_code:
def serialize(self, data):
        """ Invoke the serializer

        These are common things for all serializers. Mostly,
        stuff to do with managing headers. The data passed
        in may not be reliable for much of anything.

        Conditionally, set the Content-Type header unless it
        has already been set.
        """
        # Ensure the instance has a headers dictionary
        if not hasattr(self, "headers") or self.headers is None:
            self.headers = {}

        # Set a default Content-Type header if one hasn't been provided
        if "Content-Type" not in self.headers:
            # Prefer an explicit attribute on the instance
            ct = getattr(self, "content_type", None)

            # Fallback heuristics based on the data type
            if ct is None:
                if isinstance(data, (dict, list)):
                    ct = "application/json"
                elif isinstance(data, (bytes, bytearray)):
                    ct = "application/octet-stream"
                elif isinstance(data, str):
                    ct = "text/plain; charset=utf-8"
                else:
                    ct = "application/octet-stream"

            self.headers["Content-Type"] = ct

        # Return the (potentially unmodified) data; subclasses may override
        return data

