mgc_code:
def cancel_job(agent, project_name, job_id):
    """
    cancel a job.
    If the job is pending, it will be removed. If the job is running, it will be terminated.
    """
    # Retrieve the current status of the job
    try:
        status = agent.get_job_status(project_name, job_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to obtain status for job {job_id!r} in project {project_name!r}") from exc

    # Normalise status string for comparison
    if isinstance(status, str):
        status = status.strip().lower()
    else:
        raise TypeError(f"Job status must be a string, got {type(status)}")

    # Perform the appropriate cancellation action
    if status == "pending":
        try:
            agent.remove_job(project_name, job_id)
        except Exception as exc:
            raise RuntimeError(f"Failed to remove pending job {job_id!r} in project {project_name!r}") from exc
        return "removed"
    elif status == "running":
        try:
            agent.terminate_job(project_name, job_id)
        except Exception as exc:
            raise RuntimeError(f"Failed to terminate running job {job_id!r} in project {project_name!r}") from exc
        return "terminated"
    else:
        raise ValueError(f"Unsupported job status {status!r} for job {job_id!r} in project {project_name!r}")

