def assets_by_site(self):
        """
        :returns: numpy array of lists with the assets by each site
        """
        import numpy as np
        import pandas as pd

        if not hasattr(self, "assets"):
            raise AttributeError("Instance has no attribute 'assets'")
        assets = getattr(self, "assets")
        if not isinstance(assets, pd.DataFrame):
            raise TypeError("'assets' must be a pandas DataFrame")

        # Expect a column identifying the site and a column identifying the asset.
        # Try common column names; fall back to the first two columns.
        cols = assets.columns.tolist()
        if "site" in cols:
            site_col = "site"
        elif len(cols) >= 1:
            site_col = cols[0]
        else:
            raise ValueError("Assets DataFrame must have at least one column for site identification")

        if "asset" in cols:
            asset_col = "asset"
        elif len(cols) >= 2:
            asset_col = cols[1]
        else:
            raise ValueError("Assets DataFrame must have at least one column for asset identification")

        grouped = assets.groupby(site_col)
        result = [list(group[asset_col].values) for _, group in grouped]
        return np.array(result, dtype=object)

