mgc_code:
def _fetch_all_error_message(self, response):
        """
        :type response: requests.Response

        :rtype: list[str]
        """
        try:
            data = response.json()
        except Exception:
            text = response.text.strip()
            return [text] if text else []

        messages = []

        # Common structures
        if isinstance(data, dict):
            if 'errors' in data and isinstance(data['errors'], (list, tuple)):
                for err in data['errors']:
                    if isinstance(err, dict):
                        msg = err.get('message') or err.get('detail')
                        if msg:
                            messages.append(str(msg))
                    else:
                        messages.append(str(err))
            elif 'error' in data:
                messages.append(str(data['error']))
            elif 'message' in data:
                messages.append(str(data['message']))
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    msg = item.get('message') or item.get('error')
                    if msg:
                        messages.append(str(msg))
                else:
                    messages.append(str(item))

        if not messages:
            text = response.text.strip()
            if text:
                messages.append(text)

        return messages

