def displayable(obj):
    """
    Predicate that returns whether the object is displayable or not
    (i.e whether the object obeys the nesting hierarchy
    """
    if isinstance(obj, Overlay) and any(isinstance(o, (HoloMap, GridSpace))
                                        for o in obj):
        return False
    if isinstance(obj, HoloMap):
        return not (obj.type in [Layout, GridSpace, NdLayout, DynamicMap])
    if isinstance(obj, (GridSpace, Layout, NdLayout)):
        for el in obj.values():
            if not displayable(el):
                return False
        return True
    return True

mgc_code:
def displayable(obj):
    """
    Predicate that returns whether the object is displayable or not
    (i.e whether the object obeys the nesting hierarchy
    """
    from collections.abc import Mapping, Iterable

    _simple_types = (str, int, float, bool, type(None), bytes)

    def _is_displayable(o, seen):
        if isinstance(o, _simple_types):
            return True
        oid = id(o)
        if oid in seen:
            return False
        seen.add(oid)
        if isinstance(o, Mapping):
            return all(_is_displayable(k, seen) and _is_displayable(v, seen) for k, v in o.items())
        if isinstance(o, (list, tuple, set, frozenset)):
            return all(_is_displayable(item, seen) for item in o)
        # treat other iterables (e.g., generators) as non‑displayable
        return False

    return _is_displayable(obj, set())

