def disableIndexing(self):
        """
            disableIndexing - Disables indexing. Consider using plain AdvancedHTMLParser class.
              Maybe useful in some scenarios where you want to parse, add a ton of elements, then index
              and do a bunch of searching.
        """
        # Turn off any automatic indexing mechanisms and clear existing index data.
        # Use attribute names that are commonly used in AdvancedHTMLParser implementations,
        # but fall back gracefully if they are not present.
        if hasattr(self, "_indexing_enabled"):
            self._indexing_enabled = False
        if hasattr(self, "_indexing"):
            self._indexing = False
        # Clear any existing index structures to free memory and avoid stale look‑ups.
        if hasattr(self, "_index"):
            try:
                self._index.clear()
            except Exception:
                # If _index is not a dict‑like object, replace it with an empty dict.
                self._index = {}
        # Mark that indexing has been explicitly disabled.
        self._indexing_disabled = True
        return None

