        """Return contents of transport object for debugging forensics."""
        transport = getattr(self, "transport", None)
        if transport is None:
            return None
        try:
            sock = transport.get_extra_info("socket")
        except Exception:
            sock = None
        if sock is None:
            return None
        try:
            import socket
            # Peek without removing data from the socket buffer
            return sock.recv(4096, socket.MSG_PEEK)
        except Exception:
            # Fallback: some transports expose a buffer directly
            for attr in ("get_buffer", "getvalue", "buffer"):
                if hasattr(transport, attr):
                    try:
                        return getattr(transport, attr)()
                    except Exception:
                        continue
            return None

