mgc_code:
def restoreXml(self, xml):
        """
        Restores data from the xml entry.

        :param      xml | <xml.etree.ElementTree.Element>

        :return     <bool> | success
        """
        try:
            for child in xml:
                tag = child.tag
                if not tag:
                    continue
                if hasattr(self, tag):
                    setattr(self, tag, child.text)
                elif hasattr(self, "_extra") and isinstance(self._extra, dict):
                    self._extra[tag] = child.text
            return True
        except Exception:
            return False

