def make_images_responsive(app, doctree):
    """
    Add Bootstrap img-responsive class to images.
    """
    from docutils import nodes

    for image in doctree.traverse(nodes.image):
        classes = list(image.get('classes', []))
        if 'img-responsive' not in classes:
            classes.append('img-responsive')
            image['classes'] = classes

