def get_tree_depth( self ):
        """ Finds depth of this tree. """
        if (self.children):
            depth = 1
            childDepths = []
            for child in self.children:
                childDepths.append( child.get_tree_depth() )
            return depth + max(childDepths)
        else:
            return 0

mgc_code:
def get_tree_depth( self ):
        """ Finds depth of this tree. """
        left = getattr(self, 'left', None)
        right = getattr(self, 'right', None)
        children = getattr(self, 'children', None)

        if children is not None:
            if not children:
                return 1
            return 1 + max(child.get_tree_depth() for child in children)

        depths = []
        if left is not None:
            depths.append(left.get_tree_depth())
        if right is not None:
            depths.append(right.get_tree_depth())
        if not depths:
            return 1
        return 1 + max(depths)

