def get_most_complete_pm(pms):
    """ Return plugin match with longer version, if not available
        will return plugin match with ``presence=True``
    """
    if not pms:
        return None

    selected_version = None
    selected_presence = None

    for pm in pms:
        if pm.version:
            if not selected_version:
                selected_version = pm
            else:
                if len(pm.version) > len(selected_version.version):
                    selected_version = pm
        elif pm.presence:
            selected_presence = pm

    return selected_version or selected_presence

mgc_code:
def get_most_complete_pm(pms):
    """ Return plugin match with longer version, if not available
        will return plugin match with ``presence=True``
    """
    best = None
    best_len = -1
    for pm in pms:
        # Try to get version attribute or key
        version = pm.get('version') if isinstance(pm, dict) else getattr(pm, 'version', None)
        if version is not None:
            vlen = len(str(version))
            if vlen > best_len:
                best_len = vlen
                best = pm
    if best is not None:
        return best
    # Fallback to presence=True
    for pm in pms:
        presence = pm.get('presence') if isinstance(pm, dict) else getattr(pm, 'presence', False)
        if presence:
            return pm
    return None

