mgc_code:
def _validate_attributes_type(self):
        """Validate the type of each attribute."""
        attr_types = getattr(self, "_attribute_types", {})
        for name, expected_type in attr_types.items():
            if not hasattr(self, name):
                continue
            value = getattr(self, name)
            if value is None:
                continue
            if isinstance(expected_type, (list, tuple, set)):
                valid = any(isinstance(value, t) for t in expected_type)
                type_names = ", ".join(t.__name__ for t in expected_type)
            else:
                valid = isinstance(value, expected_type)
                type_names = expected_type.__name__
            if not valid:
                raise TypeError(
                    f"Attribute '{name}' must be of type {type_names}, "
                    f"got {type(value).__name__}"
                )

