def __get_nondirect_init(self, init):
        """
        return the non-direct init if the direct algorithm has been selected.
        """
        crc = init
        for i in range(self.Width):
            bit = crc & 0x01
            if bit:
                crc^= self.Poly
            crc >>= 1
            if bit:
                crc |= self.MSB_Mask
        return crc & self.Mask

mgc_code:
def __get_nondirect_init(self, init):
        """
        return the non-direct init if the direct algorithm has been selected.
        """
        if getattr(self, "algorithm", None) == "direct":
            # If init is a string indicating a direct initialization, replace it
            if isinstance(init, str) and init.lower() == "direct":
                return "random"
            # If init is a dict that specifies a direct method, replace the method
            if isinstance(init, dict):
                method = init.get("method") or init.get("type")
                if isinstance(method, str) and method.lower() == "direct":
                    new_init = init.copy()
                    new_init["method"] = "random"
                    if "type" in new_init:
                        new_init["type"] = "random"
                    return new_init
        # In all other cases return the original init unchanged
        return init

