def get_symops(self, data):
        """
        In order to generate symmetry equivalent positions, the symmetry
        operations are parsed. If the symops are not present, the space
        group symbol is parsed, and symops are generated.
        """
        # Try to extract symmetry operations directly from known CIF tags
        symop_keys = [
            "_symmetry_equiv_pos_as_xyz",
            "_symmetry_equiv_pos_as_xyz_1",
            "_space_group_symop_operation_xyz",
            "_space_group_symop_operation_xyz_1",
        ]
        symops = []
        for key in symop_keys:
            if key in data:
                raw = data[key]
                # CIF entries may be a single string or a list of strings
                if isinstance(raw, (list, tuple)):
                    entries = raw
                else:
                    # split on newlines or semicolons
                    entries = [line.strip() for line in str(raw).replace(";", "\n").splitlines()]
                for entry in entries:
                    entry = entry.strip()
                    if entry:
                        # Remove surrounding quotes if present
                        if entry.startswith(("'", '"')) and entry.endswith(("'", '"')):
                            entry = entry[1:-1].strip()
                        symops.append(entry)

