mgc_code:
def get_plan(self, nodes=None):
        """
        Retrieve a plan, e.g. a list of fixtures to be loaded sorted on
        dependency.

        :param list nodes: list of nodes to be loaded.
        :return:
        """
        if nodes is None:
            nodes = getattr(self, "nodes", [])
        _state = {}
        _result = []

        def _visit(node):
            nid = id(node)
            st = _state.get(nid, 0)
            if st == 1:
                raise ValueError("Circular dependency detected")
            if st == 2:
                return
            _state[nid] = 1
            for dep in getattr(node, "dependencies", []):
                _visit(dep)
            _state[nid] = 2
            _result.append(node)

        for n in nodes:
            _visit(n)
        return _result

