def append_strings(self, string_list, header=False):
        """Append tag=pairs for each supplied string.

        :param string_list: List of "tag=value" strings.
        :param header: Append to header if True; default to body.

        Each string is split, and the resulting tag and value strings
        are appended to the message."""
        for item in string_list:
            if not isinstance(item, str):
                raise TypeError(f"Expected string, got {type(item).__name__}")
            if '=' not in item:
                raise ValueError(f"String '{item}' does not contain '=' separator")
            tag, value = item.split('=', 1)
            target = getattr(self, 'header' if header else 'body', None)
            if target is None:
                raise AttributeError(f"{'header' if header else 'body'} attribute not found on {self!r}")
            target.append((tag, value))

