def _handle_order_args(self, rison_args):
        """
            Help function to handle rison order
            arguments

        :param rison_args:
        :return:
        """
        if not rison_args:
            return []
        order = rison_args.get('order')
        if not order:
            return []

        # Normalise order into an iterable of (field, direction) pairs
        pairs = []

        if isinstance(order, dict):
            # {'field1': 'asc', 'field2': 'desc'}
            for field, direction in order.items():
                dir_norm = str(direction).lower()
                if dir_norm not in ('asc', 'desc'):
                    dir_norm = 'asc'
                pairs.append((field, dir_norm))
        else:
            # Accept list, tuple, or comma‑separated string
