def make_links(self, project):
        """
        Process intra-site links to documentation of other parts of the program.
        """
        import re

        def _replace(match):
            target = match.group(1).strip()
            label = match.group(2)
            if not label:
                label = target
            # Attempt to obtain a URL from the project; fall back to original text if unavailable
            try:
                url = project.get_doc_url(target)
            except Exception:
                return match.group(0)
            if not url:
                return match.group(0)
            return f'[{label}]({url})'

        # Pattern supports [[target]] or [[target|label]]
        pattern = re.compile(r'\[\[([^|\]]+)(?:\|([^]]+))?\]\]')
        # Assume the page's raw text is stored in self.content
        if not hasattr(self, "content"):
            return None
        self.content = pattern.sub(_replace, self.content)
        return self.content

