def ls():                       # pylint:disable=C0103
    """
    List all installed Quilt data packages
    """
    import os
    from pathlib import Path

    try:
        import quilt3
    except Exception:
        return []

    # Preferred method: use quilt3's public API if available
    try:
        packages = quilt3.list_packages()
        if isinstance(packages, dict):
            # Older versions may return a dict mapping package names to versions
            packages = list(packages.keys())
        return sorted(packages)
    except Exception:
        # Fallback: inspect the local Quilt cache directory
        cache_dir = Path.home() / ".quilt" / "packages"
        if not cache_dir.is_dir():
            return []
        packages = [
            entry.name
            for entry in cache_dir.iterdir()
            if entry.is_dir() and not entry.name.startswith(".")
        ]
        return sorted(packages)

