mgc_code:
def hash(filename, algorithm='sha256'):
    """
    Hash the given filename. Unavailable in `pip<8.0.0`
    """
    import hashlib
    h = hashlib.new(algorithm)
    with open(filename, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()

