    while not self._listener_stop.is_set():
        try:
            # Assume the class provides a method to perform a single poll
            self._listen_once(timeout_ms)
        except Exception as exc:  # pylint: disable=broad-except
            if exception_handler:
                try:
                    exception_handler(exc)
                except Exception:
                    # Swallow any exception raised by the handler to keep the loop alive
                    pass
            else:
                # Re‑raise if no handler is provided
                raise
        # Yield to other greenlets
        gevent.sleep(0)

# Start the greenlet and store a reference for later control
