def send_messages(self, sms_messages):
        """
        Sends one or more SmsMessage objects and returns the number of sms
        messages sent.
        """
        count = 0
        # Ensure sms_messages is iterable (but not a string/bytes)
        if isinstance(sms_messages, (str, bytes)) or not hasattr(sms_messages, "__iter__"):
            messages = [sms_messages]
        else:
            messages = sms_messages
        for msg in messages:
            try:
                result = msg.send()
                # Consider a successful send if send() returns True or None
                if result is None or result is True:
                    count += 1
            except Exception:
                # Skip messages that raise an exception during sending
                continue
        return count

