def run(self):
        """ Overrides parent method to implement thread's functionality. """
        while True:
            # Check for a stop condition if provided
            if hasattr(self, "stop_event") and self.stop_event.is_set():
                break
            if getattr(self, "stopped", False):
                break

            # Attempt to fetch a callable task from a queue attribute
            try:
                task = self.task_queue.get(timeout=0.1)
            except Exception:
                continue

            try:
                # Execute the task if it's callable
                if callable(task):
                    task()
            except Exception as exc:
                # Optional custom error handling hook
                if hasattr(self, "handle_exception"):
                    try:
                        self.handle_exception(exc)
                    except Exception:
                        pass
            finally:
                # Mark the task as done if the queue supports it
                if hasattr(self.task_queue, "task_done"):
                    try:
                        self.task_queue.task_done()
                    except Exception:
