def start (self):
        """
        Starts (Subscribes) the client.

        """
        if getattr(self, "_started", False):
            return
        # Attempt to call a subscribe method if the client provides one
        subscribe = getattr(self, "subscribe", None)
        if callable(subscribe):
            try:
                result = subscribe()
                # If the subscribe method is a coroutine, schedule it
                if hasattr(result, "__await__"):
                    import asyncio

                    if asyncio.iscoroutine(result):
                        asyncio.get_event_loop().run_until_complete(result)
                    else:
                        # For awaitable objects that are not coroutines
                        asyncio.get_event_loop().run_until_complete(result)
            except Exception as exc:
                raise RuntimeError(f"Failed to start client: {exc}") from exc
        self._started = True

