def find_arg(self, name):
        """Find arg by normalized arg name or parameter name."""
        for arg in getattr(self, "args", []):
            # Direct match on normalized name or parameter name
            if getattr(arg, "normalized_name", None) == name:
                return arg
            if getattr(arg, "parameter_name", None) == name:
                return arg
            # Fallback: compare stripped raw name (e.g., '--foo' -> 'foo')
            raw_name = getattr(arg, "name", None)
            if raw_name and raw_name.lstrip("-") == name:
                return arg
        return None

