def _get_dvs_link_discovery_protocol(dvs_name, dvs_link_disc_protocol):
    """
    Returns the dict representation of the DVS link discovery protocol

    dvs_name
        The name of the DVS

    dvs_link_disc_protocl
        The DVS link discovery protocol
    """
    allowed = {"cdp", "lldp", "both", "none"}
    if not isinstance(dvs_name, str):
        raise TypeError("dvs_name must be a string")
    if not isinstance(dvs_link_disc_protocol, str):
        raise TypeError("dvs_link_disc_protocol must be a string")
    protocol = dvs_link_disc_protocol.strip().lower()
    if protocol not in allowed:
        raise ValueError(
            f"Unsupported link discovery protocol '{dvs_link_disc_protocol}'. "
            f"Supported values are: {', '.join(sorted(allowed))}"
        )
    return {"dvsName": dvs_name, "linkDiscoveryProtocol": protocol}

