    raise AttributeError("Missing 'sigma' or 'exp' in self._surf")
if not hasattr(self, 'Tc'):
    raise AttributeError("Missing critical temperature attribute 'Tc'")
delta = 1.0 - T / self.Tc
if delta <= 0.0:
    return 0.0
return float(sigma0 * delta ** exp)

