        """
        Return True if the value of component in attribute "part" is valid,
        and otherwise False.

        :returns: True if value of component is valid, False otherwise
        :rtype: boolean
        """
        try:
            part = getattr(self, "part")
        except Exception:
            return False
        if part is None:
            return False
        if isinstance(part, str):
            part = part.strip()
            if not part:
                return False
            import re
