def after(f, chain=False):
    """Runs f with the result of the decorated function."""
    def decorator(g):
        @wraps(g)
        def h(*args, **kargs):
            if chain:
                return f(g(*args, **kargs))
            else:
                r = g(*args, **kargs)
                f(*args, **kargs)
                return r
        return h
    return decorator

mgc_code:
def after(f, chain=False):
    """Runs f with the result of the decorated function."""
    import functools
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            new = f(result)
            return new if chain else result
        return wrapper
    return decorator

