mgc_code:
def _unique_constrains(cls):
        """Get all (single column and multi column) unique constraints"""
        table = getattr(cls, "__table__", None)
        if table is None:
            return []
        constraints = []
        # Column-level unique constraints
        for col in table.columns:
            if getattr(col, "unique", False):
                constraints.append((col.name,))
        # Table-level UniqueConstraint objects
        try:
            from sqlalchemy import UniqueConstraint
        except Exception:
            UniqueConstraint = None
        if UniqueConstraint:
            for cons in table.constraints:
                if isinstance(cons, UniqueConstraint):
                    cols = tuple(col.name for col in cons.columns)
                    if cols not in constraints:
                        constraints.append(cols)
        return constraints

