def _create_snapshot(logger, snapshot_name, vm, save_vm_memory_to_snapshot):
        """
        :type save_vm_memory_to_snapshot: bool
        """
        try:
            logger.info(
                "Creating snapshot '%s' for VM '%s' (memory=%s)",
                snapshot_name,
                getattr(vm, "name", str(vm)),
                save_vm_memory_to_snapshot,
            )
            # Attempt to create the snapshot; support common signatures
            if hasattr(vm, "create_snapshot"):
                # Prefer keyword arguments if supported
                try:
                    snapshot = vm.create_snapshot(name=snapshot_name, memory=save_vm_memory_to_snapshot)
                except TypeError:
                    # Fallback to positional arguments
                    snapshot = vm.create_snapshot(snapshot_name, save_vm_memory_to_snapshot)
            else:
                raise AttributeError("VM object has no method 'create_snapshot'")
