mgc_code:
def _write_standard(self, message, extra):
        """
        Writes a standard log statement

        @param message: The message to write
        @param extra: The object to pull defaults from
        """
        from datetime import datetime

        # Determine level
        if isinstance(extra, dict):
            level = extra.get("level", "INFO")
            timestamp = extra.get("timestamp")
        else:
            level = getattr(extra, "level", "INFO")
            timestamp = getattr(extra, "timestamp", None)

        # Fallback timestamp
        if not timestamp:
            timestamp = datetime.utcnow().isoformat()

        # Build the log line
        log_line = f"{timestamp} [{level}] {message}"

        # Write using a custom writer if available, otherwise fallback to print
        writer = getattr(self, "_write", None)
        if callable(writer):
            writer(log_line)
        else:
            print(log_line)

