mgc_code:
def GetBlockHash(self, height):
        """
        Get the block hash by its block height
        Args:
            height(int): height of the block to retrieve hash from.

        Returns:
            bytes: a non-raw block hash (e.g. b'6dd83ed8a3fc02e322f91f30431bf3662a8c8e8ebe976c3565f0d21c70620991', but not b'\x6d\xd8...etc'
        """
        if not isinstance(height, int):
            raise TypeError("height must be an integer")
        if height < 0:
            raise ValueError("height must be non‑negative")
        try:
            hash_hex = self.rpc.getblockhash(height)
        except Exception as exc:
            raise RuntimeError(f"Unable to retrieve block hash for height {height}") from exc
        if not isinstance(hash_hex, str):
            hash_hex = str(hash_hex)
        return hash_hex.encode('utf-8')

