        model_inserts.labels(model_name).inc()
        return super(Mixin, self)._do_insert(*args, **kwargs)

    def _do_update(self, *args, **kwargs):
        model_updates.labels(model_name).inc()
        return super(Mixin, self)._do_update(*args, **kwargs)

