def _init_alphabet_from_tokens(self, tokens):
        """Initialize alphabet from an iterable of token or subtoken strings."""
        # Ensure we have an iterable; if None, treat as empty
        if tokens is None:
            self.alphabet = set()
            return self.alphabet

        # Build a set of all characters appearing in any token/subtoken
        try:
            iterator = iter(tokens)
        except TypeError:
            raise TypeError("tokens must be an iterable of strings") from None

        alphabet = set()
        for token in iterator:
            if token is None:
                continue
            if not isinstance(token, str):
                raise TypeError(f"token {token!r} is not a string")
            alphabet.update(token)

        self.alphabet = alphabet
        return self.alphabet

