mgc_code:
def onSelect_specimen(self, event):
        """
        update figures and text when a new specimen is selected
        """
        # Get the widget that triggered the event
        widget = getattr(event, "widget", None)
        if widget is None:
            return

        # Determine the selected index (listbox or similar)
        try:
            # For Tkinter Listbox or similar widgets
            selection = widget.curselection()
            if not selection:
                return
            index = selection[0]
        except Exception:
            # For widgets that provide a 'value' attribute (e.g., ttk.Combobox)
            try:
                index = widget.current()
                if index == -1:
                    return
            except Exception:
                return

        # Retrieve the specimen data associated with the selected index
        try:
            specimen = self.specimens[index]
        except (AttributeError, IndexError, TypeError):
            # Fallback: if the widget provides the actual value directly
            try:
                specimen = widget.get()
            except Exception:
                return

        # Update internal state
        self.current_specimen = specimen

        # Update any dependent UI components
        if hasattr(self, "update_figures"):
            try:
                self.update_figures()
            except Exception:
                pass

        if hasattr(self, "update_text"):
            try:
                self.update_text()
            except Exception:
                pass

        # Optionally emit a custom event or callback
        if hasattr(self, "on_specimen_changed"):
            try:
                self.on_specimen_changed(specimen)
            except Exception:
                pass

