def topWindow():
    """
    Returns the very top window for all Qt purposes.

    :return     <QWidget> || None
    """
    try:
        from PyQt5.QtWidgets import QApplication
    except ImportError:
        try:
            from PySide2.QtWidgets import QApplication
        except ImportError:
            return None
    app = QApplication.instance()
    if not app:
        return None
    active = app.activeWindow()
    if active:
        return active
    visible_toplevels = [w for w in app.topLevelWidgets() if w.isVisible()]
    return visible

