def page_should_not_contain_element(self, locator, loglevel='INFO'):
        """Verifies that current page not contains `locator` element.

        If this keyword fails, it automatically logs the page source
        using the log level specified with the optional `loglevel` argument.
        Giving `NONE` as level disables logging.
        """
        if self.is_element_present(locator):
            message = f"Page should not contain element '{locator}' but it does."
            if loglevel.upper() != "NONE":
                try:
                    page_source = self.driver.page_source
                except Exception:
                    page_source = "Unable to retrieve page source."
                self.logger.log(f"{message}\nPage source:\n{page_source}", loglevel.upper())
            raise AssertionError(message)

