def compute_texptime(imageObjectList):
    """
    Add up the exposure time for all the members in
    the pattern, since 'drizzle' doesn't have the necessary
    information to correctly set this itself.
    """
    total = 0.0
    for obj in imageObjectList:
        exp = None
        if isinstance(obj, dict):
            exp = obj.get('exptime') or obj.get('exposure_time')
        else:
            exp = getattr(obj, 'exptime', None) or getattr(obj, 'exposure_time', None)
        if exp is None:
            continue
        try:
            total += float(exp)
        except Exception:
            continue
    return total

