def tolist(self):
        """
        The fastest way to convert the vector into a python list.
        """
        try:
            # Prefer an internal array's tolist method if available (e.g., numpy.ndarray)
            arr = getattr(self, "_data", None) or getattr(self, "data", None)
            if arr is not None and hasattr(arr, "tolist"):
                return arr.tolist()
            # Fallback to any object's tolist (e.g., pandas Series)
            if hasattr(self, "tolist"):
                return self.tolist()
        except Exception:
            pass
        # As a generic fallback, convert the iterable to a list
        return list(self)

