def from_localhost(self) -> bool:
        """True if :attr:`.peername` is a connection from a ``localhost``
        address.

        """
        try:
            host = self.peername[0] if self.peername else None
        except Exception:
            return False
        if not host:
            return False
        try:
            import ipaddress
            return ipaddress.ip_address(host).is_loopback
        except ValueError:
            return host == 'localhost'

