def _authenticate_https(org):
    """Try authenticating via HTTPS, if succesful yields User, otherwise raises Error."""
    import urllib.request
    import urllib.error
    from collections import namedtuple

    User = namedtuple("User", ["org"])

    try:
        with urllib.request.urlopen(f"https://{org}", timeout=5) as resp:
            if getattr(resp, "status", resp.getcode()) != 200:
                raise RuntimeError(f"HTTPS authentication failed for {org}")
    except Exception as exc:
        raise RuntimeError(f"HTTPS authentication failed for {org}") from exc

    return User(org)

