mgc_code:
def _grab_crl(user_agent, url, timeout):
    """
    Fetches a CRL and parses it

    :param user_agent:
        A unicode string of the user agent to use when fetching the URL

    :param url:
        A unicode string of the URL to fetch the CRL from

    :param timeout:
        The number of seconds after which an HTTP request should timeout

    :return:
        An asn1crypto.crl.CertificateList object
    """
    import urllib.request
    import urllib.error
    from asn1crypto import crl

    if not isinstance(user_agent, str):
        raise TypeError("user_agent must be a string")
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    request = urllib.request.Request(url, headers={"User-Agent": user_agent})
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            data = response.read()
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"Failed to fetch CRL: HTTP {e.code} {e.reason}") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"Failed to fetch CRL: {e.reason}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error while fetching CRL: {e}") from e

    try:
        return crl.CertificateList.load(data)
    except Exception as e:
        raise RuntimeError(f"Failed to parse CRL data: {e}") from e

