def get_color_between(color1, color2, i):
    """ i is a number between 0 and 1, if 0 then color1, if 1 color2, ... """
    i = max(0.0, min(1.0, float(i)))
    c1 = tuple(color1)
    c2 = tuple(color2)
    if len(c1) != 3 or len(c2) != 3:
        raise ValueError("Colors must have three components (R, G, B)")
    return tuple(int(round(c1[j] + (c2[j] - c1[j]) * i)) for j in range(3))

