def sync_connect_master(self, timeout=None, failed=False):
        """
        Block until we are connected to a master
        """
        import time

        start = time.time()
        while True:
            # Determine connection status
            if hasattr(self, "is_master_connected") and callable(self.is_master_connected):
                connected = self.is_master_connected()
            else:
                connected = bool(getattr(self, "master_connected", False))

            if connected:
                return True

            if failed:
                raise ConnectionError("Failed to connect to master")

            if timeout is not None and (time.time() - start) >= timeout:
                raise TimeoutError("Timeout while waiting for master connection")

            time.sleep(0.1)

