mgc_code:
def parseDoc(cur):
    """parse an XML in-memory document and build a tree. """
    if cur is None:
        return None
    # ElementTree.Element handling
    if hasattr(cur, 'tag'):
        node = {
            'tag': cur.tag,
            'attrib': dict(getattr(cur, 'attrib', {})),
            'text': (cur.text or '').strip(),
            'children': [parseDoc(child) for child in list(cur)]
        }
        return node
    # minidom Node handling
    if hasattr(cur, 'nodeName'):
        node = {
            'tag': cur.nodeName,
            'attrib': {attr.name: attr.value for attr in cur.attributes.values()} if cur.attributes else {},
            'text': '',
            'children': []
        }
        for child in cur.childNodes:
            if child.nodeType == child.TEXT_NODE:
                node['text'] += child.data.strip()
            elif child.nodeType == child.ELEMENT_NODE:
                node['children'].append(parseDoc(child))
        node['text'] = node['text'].strip()
        return node
    # Fallback: return raw representation
    return str(cur)

