def fetch_response(self, req_payload, **kwargs):
        """payload has been sent, do anything else you need to do (eg, wait for response?)

        :param req_payload: Payload, the payload sent to the server
        :returns: Payload, the response payload
        """
        import time

        # Optional artificial delay before fetching the response
        delay = kwargs.get("delay")
        if delay:
            try:
                time.sleep(float(delay))
            except Exception:
                pass

        # If a specific response payload is provided via kwargs, return it
        if "response" in kwargs:
            return kwargs["response"]

        # If a callable is provided to generate the response, use it
        response_func = kwargs.get("response_func")
        if callable(response_func):
            return response_func(req_payload)

        # Default behavior: echo back the request payload
        return req_payload

