    """Identify regions in the end file that overlap the exclusion file.

    We look for ends with a large percentage in a repeat or where the end contains
    an entire repeat.
    """
    # Parse BED-like files into dict of chrom -> list of (start, end)
    def _parse_intervals(file_path):
        intervals = {}
        open_func = open if isinstance(file_path, str) else lambda x: x
        with open_func(file_path) as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split()
                if len(parts) < 3:
                    continue
                chrom, start_str, end_str = parts[:3]
                try:
                    start = int(start_str)
                    end = int(end_str)
                except ValueError:
                    continue
                intervals.setdefault(chrom, []).append((start, end))
        # sort intervals per chromosome for efficient scanning
        for chrom in intervals:
            intervals[chrom].sort()
        return intervals

    # Load intervals
    in_intervals = _parse_intervals(in_file)
    excl_inter

