def match(self, path_pattern):
        """
        Return True if this path matches the given pattern.
        """
        import fnmatch
        target = getattr(self, "path", None)
        if target is None:
            try:
                target = str(self)
            except Exception:
                return False
        return fnmatch.fnmatch(target, path_pattern)

