def group(self):
        """
        :rtype: list
        """
        result = []
        iterator = iter(self)
        try:
            current = next(iterator)
        except StopIteration:
            return result
        group = [current]
        for item in iterator:
            if item == current:
                group.append(item)
            else:
                result.append(group)
                current = item
                group = [current]
        result.append(group)
        return result

