def add_repo(self, repo_name, items):
        """
        Build up repos

        `name` - Name of this repo.
        `items` - List of paths to rpm.
        """
        if not hasattr(self, 'repos'):
            self.repos = {}
        if not isinstance(items, (list, tuple, set)):
            raise TypeError("`items` must be an iterable of RPM paths")
        # Ensure all items are strings (paths)
        for i in items:
            if not isinstance(i, str):
                raise TypeError("Each item in `items` must be a string representing a path")
        self.repos[repo_name] = list(items)
        return self.repos[repo_name]

