mgc_code:
def _set_or_sum_metric(self, metrics, metric_path, value):
        """If we already have a datapoint for this metric, lets add
        the value. This is used when the logstash mode is enabled."""
        # Determine the list of keys representing the metric path
        if isinstance(metric_path, str):
            keys = metric_path.split('.')
        else:
            keys = list(metric_path)

        # Navigate/create nested dictionaries up to the final key
        current = metrics
        for key in keys[:-1]:
            if not isinstance(current.get(key), dict):
                current[key] = {}
            current = current[key]

        final_key = keys[-1]
        # If the metric already exists and is numeric, sum the new value
        if isinstance(current.get(final_key), (int, float)):
            current[final_key] += value
        else:
            current[final_key] = value

