def to_dataframe(self) -> "pandas.DataFrame":
        """Convert to pandas DataFrame.

        This is not a lossless conversion - (under/over)flow info is lost.
        """
        import pandas as pd

        # Prefer an explicit 'data' attribute if present
        if hasattr(self, "data"):
            source = getattr(self, "data")
        else:
            source = self

        # Already a DataFrame – return a shallow copy to avoid side‑effects
        if isinstance(source, pd.DataFrame):
            return source.copy()

        # Mapping of column names to sequences
        if isinstance(source, dict):
            return pd.DataFrame(source)

        # Sequence of rows (list/tuple of dicts, lists, or scalars)
        if isinstance(source, (list, tuple)):
            return pd.DataFrame(source)

        # Generic iterable (e.g., generator)
        try:
            return pd.DataFrame(list(source))
        except Exception as exc:
            raise Type

