mgc_code:
def grab_bulbs(host, token=None):
    """Grab XML, then add all bulbs to a dict. Removes room functionality"""
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    # Build URL (assume host already includes scheme)
    url = host if host.startswith(('http://', 'https://')) else f'http://{host}'
    req = urllib.request.Request(url)
    if token:
        req.add_header('Authorization', f'Bearer {token}')
    try:
        with urllib.request.urlopen(req) as resp:
            data = resp.read()
    except (urllib.error.URLError, urllib.error.HTTPError):
        return {}

    try:
        root = ET.fromstring(data)
    except ET.ParseError:
        return {}

    bulbs = {}
    # Look for any element named 'bulb' (case‑insensitive) anywhere in the tree
    for bulb in root.iter():
        if bulb.tag.lower() == 'bulb':
            bulb_id = bulb.get('id') or bulb.get('ID') or bulb.get('Id')
            bulb_name = bulb.get('name') or bulb.get('Name')
            if bulb_id is not None:
                bulbs[bulb_id] = bulb_name if bulb_name is not None else ''
    return bulbs

