def snooze(self, from_email, duration):
        """Snooze this incident for `duration` seconds."""
        import datetime

        if not isinstance(duration, (int, float)):
            raise TypeError("duration must be a number of seconds")
        if duration <= 0:
            raise ValueError("duration must be positive")

        self.snoozed_by = from_email
        self.snoozed_until = datetime.datetime.utcnow() + datetime.timedelta(seconds=duration)

