def focusout(event):
        """Change style on focus out events."""
        widget = getattr(event, "widget", None)
        if widget is None:
            return
        # Try to reset common widget options
        for option, value in (("background", "white"), ("foreground", "black")):
            try:
                widget.configure(**{option: value})
            except Exception:
                pass
        # If it's a ttk widget, attempt to reset its style to the default
        try:
            widget.configure(style="TEntry")
        except Exception:
            try:
                widget.configure(style="TButton")
            except Exception:
                pass

