mgc_code:
def to_numpy_(self, table_name: str="data") -> numpy.array:
        """Convert the main dataframe to a numpy array

        :param table_name: name of the python variable, defaults to "data"
        :param table_name: str, optional
        :return: a numpy array
        :rtype: np.array

        :example: ``ds.to_numpy_("myvar")``
        """
        import numpy as np
        import pandas as pd

        # Retrieve the table; support both attribute and dict storage
        df = getattr(self, table_name, None)
        if df is None:
            tables = getattr(self, "tables", None)
            if isinstance(tables, dict):
                df = tables.get(table_name)
        if df is None:
            raise KeyError(f"Table '{table_name}' not found.")

        # Convert to numpy array based on type
        if isinstance(df, pd.DataFrame):
            return df.to_numpy()
        if isinstance(df, (list, tuple, np.ndarray)):
            return np.array(df)
        # Fallback: try to cast directly
        return np.array(df)

