mgc_code:
def _parse_methods(cls, list_string):
        """Return HTTP method list. Use json for security reasons."""
        import json

        if not list_string:
            return []

        try:
            methods = json.loads(list_string)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON for methods: {exc}") from None

        if not isinstance(methods, list):
            raise ValueError("Methods must be a JSON list")

        result = []
        for m in methods:
            if not isinstance(m, str):
                raise ValueError("Each method must be a string")
            result.append(m.upper())

        return result

