def all(self) -> List[Any]:
        """
        Load all entry points (if not already loaded) in this namespace and return the resulting
        objects as a list.

        """
        # Ensure we have a cache for loaded objects
        if not hasattr(self, "_loaded_cache") or self._loaded_cache is None:
            self._loaded_cache = {}
        results: List[Any] = []
        for name, entry in getattr(self, "_entries", {}).items():
            if name not in self._loaded_cache:
                try:
                    obj = entry.load()
                except Exception as exc:
                    raise RuntimeError(f"Failed to load entry point '{name}': {exc}") from exc
                self._loaded_cache[name] = obj
            results.append(self._loaded_cache[name])
        return results

