def build_joins(self):
        """
        Generates the sql for the JOIN portion of the query

        :return: the JOIN portion of the query
        :rtype: str
        """
        parts = []
        joins = getattr(self, "_joins", [])
        for join in joins:
            if isinstance(join, dict):
                jtype = join.get("type", "JOIN")
                table = join.get("table")
                condition = join.get("on")
            else:
                # Expect (type, table, condition) tuple
                try:
                    jtype, table, condition = join
                except Exception:
                    continue
            jtype = jtype.upper()
            if condition:
                parts.append(f"{jtype} {table} ON {condition}")
            else:
                parts.append(f"{jtype} {table}")
        return " ".join(parts) if parts else ""

