def print_status(self, repo):
        """Print status
        """
        try:
            # Prefer using the git command interface if available
            if hasattr(repo, "git") and hasattr(repo.git, "status"):
                print(repo.git.status())
                return
        except Exception:
            pass

        try:
            branch = getattr(repo, "active_branch", None)
            branch_name = branch.name if branch is not None else "N/A"
            dirty = getattr(repo, "is_dirty", lambda: False)()
            untracked = getattr(repo, "untracked_files", [])
            print(f"On branch {branch_name}")
            print(f"Dirty: {dirty}")
            if untracked:
                print("Untracked files:")
                for f in untracked:
                    print(f"  {f}")
        except Exception as e:
            print(f"Unable to retrieve status: {e}")

