def GetUsername(self, event, default_username='-'):
    """Retrieves the username related to the event.

    Args:
      event (EventObject): event.
      default_username (Optional[str]): default username.

    Returns:
      str: username.
    """
    # Try common attribute names
    for attr in ("username", "user", "owner"):
        if hasattr(event, attr):
            val = getattr(event, attr)
            if val:
                return str(val)

    # Try dict‑like access on the event itself
    try:
        for key in ("username", "user", "owner"):
            if key in event:
                val = event[key]
                if val:
                    return str(val)
    except Exception:
        pass

    # Try a nested data dictionary if present
    if hasattr(event, "data") and isinstance(event.data, dict):
        for key in ("username", "user", "owner"):
            if key in event.data:
                val = event.data[key]
                if val:
                    return str(val)

    return default_username

