def _calculate_remaining_battery_percentage(self, voltage):
        """Calculate percentage."""
        min_v = getattr(self, "MIN_VOLTAGE", 3.0)
        max_v = getattr(self, "MAX_VOLTAGE", 4.2)
        if voltage is None:
            raise ValueError("Voltage must be provided")
        try:
