def resolve_composed_functions(data, recursive=True):
    """
    Calls `ComposedFunction`s and returns its return value. By default, this
    function will recursively iterate dicts, lists, tuples, and sets and
    replace all `ComposedFunction`s with their return value.
    """

    if isinstance(data, ComposedFunction):
        data = data()

    if recursive:
        if isinstance(data, dict):
            for key, value in data.items():
                data[key] = resolve_composed_functions(
                    value,
                    recursive=recursive,
                )
        elif isinstance(data, (list, tuple, set)):
            for index, value in enumerate(data):
                data[index] = resolve_composed_functions(
                    value,
                    recursive=recursive,
                )

    return data

mgc_code:
def resolve_composed_functions(data, recursive=True):
    """
    Calls `ComposedFunction`s and returns its return value. By default, this
    function will recursively iterate dicts, lists, tuples, and sets and
    replace all `ComposedFunction`s with their return value.
    """
    # Resolve a ComposedFunction by calling it, otherwise return the object unchanged.
    if isinstance(data, ComposedFunction):
        return data()
    if not recursive:
        return data

    # Handle mappings
    if isinstance(data, dict):
        return {k: resolve_composed_functions(v, True) for k, v in data.items()}

    # Handle sequences
    if isinstance(data, list):
        return [resolve_composed_functions(item, True) for item in data]
    if isinstance(data, tuple):
        return tuple(resolve_composed_functions(item, True) for item in data)

    # Handle sets
    if isinstance(data, set):
        return {resolve_composed_functions(item, True) for item in data}
    if isinstance(data, frozenset):
        return frozenset(resolve_composed_functions(item, True) for item in data)

    # Fallback: return as‑is
    return data

