def finalize(self, **kwargs):
        """
        Finalize executes any subclass-specific axes finalization steps.
        The user calls poof and poof calls finalize.

        Parameters
        ----------
        kwargs: generic keyword arguments.
        """
        # Store provided keyword arguments, updating existing attributes when possible
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)
            else:
                # Preserve unknown kwargs for potential later use
                if not hasattr(self, "_finalize_kwargs"):
                    self._finalize_kwargs = {}
                self._finalize_kwargs[key] = value

        # Execute any subclass‑specific finalization hook if present
        hook = getattr(self, "_finalize_axes", None)
        if callable(hook):
            hook(**kwargs)

