def _write(self, item, labels, features):
        """ Writes the given item to the owned file."""
        import json
        record = {"item": item, "labels": labels, "features": features}
        line = json.dumps(record, ensure_ascii=False)
        # Determine the file object to write to
        file_obj = getattr(self, "_file", None)
        if file_obj is None:
            raise RuntimeError("Writer has no associated file.")
        # If a path string was provided instead of an open file, open it temporarily
        if isinstance(file_obj, str):
            with open(file_obj, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        else:
            file_obj.write(line + "\n")
            try:
                file_obj.flush()
            except Exception:
                pass

