mgc_code:
def _determine_colorspace(self, colorspace=None, **kwargs):
        """Determine the colorspace from the supplied inputs.

        Parameters
        ----------
        colorspace : str, optional
            Either 'rgb' or 'gray'.
        """
        # Normalize explicit argument
        if colorspace is not None:
            cs = str(colorspace).lower()
            if cs not in ("rgb", "gray"):
                raise ValueError(
                    f"Invalid colorspace '{colorspace}'. Expected 'rgb' or 'gray'."
                )
            return cs

        # Try to infer from provided keyword arguments
        img = kwargs.get("image") or kwargs.get("img") or kwargs.get("array")
        if img is not None:
            try:
                shape = img.shape
            except Exception as exc:
                raise ValueError("Unable to determine colorspace from provided image.") from exc

            # Grayscale if 2‑D or last dimension is 1
            if len(shape) == 2 or (len(shape) == 3 and shape[-1] == 1):
                return "gray"
            # RGB if last dimension is 3
            if len(shape) == 3 and shape[-1] == 3:
                return "rgb"

        # Fallback: default to 'rgb'
        return "rgb"

