mgc_code:
def get_selected_filenames(self):
        """Return selected filenames"""
        selected = []
        # Direct list of selected items (strings or objects with filename/name attribute)
        if hasattr(self, "selected_items"):
            for item in self.selected_items:
                if isinstance(item, str):
                    selected.append(item)
                elif hasattr(item, "filename"):
                    selected.append(item.filename)
                elif hasattr(item, "name"):
                    selected.append(item.name)
        # Fallback: selection indices referencing a filenames list
        elif hasattr(self, "selection") and hasattr(self, "filenames"):
            for idx in self.selection:
                try:
                    selected.append(self.filenames[idx])
                except Exception:
                    continue
        return selected

