def _GetKeyFromRegistry(self):
    """Determines the key from the Windows Registry."""
    if not self._registry:
      return

    try:
      self._registry_key = self._registry.GetKeyByPath(self._key_path)
    except RuntimeError:
      pass

    if not self._registry_key:
      return

    for sub_registry_key in self._registry_key.GetSubkeys():
      self.AddSubkey(sub_registry_key)

    if self._key_path == 'HKEY_LOCAL_MACHINE\\System':
      sub_registry_key = VirtualWinRegistryKey(
          'CurrentControlSet', registry=self._registry)
      self.AddSubkey(sub_registry_key)

    self._registry = None

mgc_code:
def _GetKeyFromRegistry(self):
    """Determines the key from the Windows Registry."""
    import sys
    try:
        import winreg
    except ImportError:
        # Not a Windows platform
        return None

    # Determine which root and subkey to inspect.
    # Subclass may provide these attributes; fall back to sensible defaults.
    root = getattr(self, "_registry_root", winreg.HKEY_LOCAL_MACHINE)
    subkey = getattr(self, "_registry_subkey", r"SOFTWARE\MyApp")
    value_name = getattr(self, "_registry_value_name", "Key")

    # Try 64‑bit view first, then 32‑bit view, then current user.
    for view in (winreg.KEY_WOW64_64KEY, winreg.KEY_WOW64_32KEY):
        try:
            with winreg.OpenKey(root, subkey, 0, winreg.KEY_READ | view) as key:
                value, _ = winreg.QueryValueEx(key, value_name)
                return value
        except FileNotFoundError:
            continue
        except OSError:
            continue

    # Fallback to HKCU if not found under HKLM.
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, subkey, 0, winreg.KEY_READ) as key:
            value, _ = winreg.QueryValueEx(key, value_name)
            return value
    except FileNotFoundError:
        pass
    except OSError:
        pass

    return None

