def add_path(self, path, method=None):
        """
        Adds the path/method combination to the Swagger, if not already present

        :param string path: Path name
        :param string method: HTTP method
        :raises ValueError: If the value of `path` in Swagger is not a dictionary
        """
        paths = getattr(self, 'swagger', {}).setdefault('paths', {})
        if path in paths and not isinstance(paths[path], dict):
            raise ValueError(f'Path `{path}` in Swagger is not a dictionary')
        if path not in paths:
            paths[path] = {}
        if method:
            method = method.lower()
            if method not in paths[path]:
                paths[path][method] = {}

