mgc_code:
def hasoriginal(self,allowempty=False):
        """Does the correction record the old annotations prior to correction?"""
        # Determine if the instance records original annotations.
        # Look for a conventional attribute that might hold them.
        orig = getattr(self, "original", None)
        if orig is None:
            # No attribute named 'original' – cannot have original annotations.
            return False
        if allowempty:
            # Presence of the attribute is sufficient.
            return True
        # For common container types, check for non‑emptiness.
        if isinstance(orig, (list, dict, set, tuple, str, bytes)):
            return len(orig) > 0
        # Fallback to truthiness for other types.
        return bool(orig)

