mgc_code:
def create_user(server_context, email, container_path=None, send_email=False):
    """
    Create new account
    :param server_context: A LabKey server context. See utils.create_server_context.
    :param email:
    :param container_path:
    :param send_email: true to send email notification to user
    :return:
    """
    payload = {
        "email": email,
        "sendEmail": str(send_email).lower()
    }
    if container_path is not None:
        payload["containerPath"] = container_path

    # Assume server_context has a method `post` that returns a response-like object
    response = server_context.post(
        "/security/createUser.api",
        json=payload,
        headers={"Content-Type": "application/json"}
    )
    if not getattr(response, "ok", False):
        # Try to extract error details if available
        try:
            error_info = response.json()
        except Exception:
            error_info = response.text
        raise RuntimeError(f"Failed to create user: {error_info}")

    try:
        return response.json()
    except Exception:
        return response.text

