def new_from_list(cls, items, **kwargs):
        """Populates the ListView with a string list.

        Args:
            items (list): list of strings to fill the widget with.
        """
        instance = cls(**kwargs)
        for item in items:
            try:
                instance.add(item)
            except Exception:
                try:
                    instance.insert('end', item)
                except Exception:
                    if hasattr(instance, 'items'):
                        try:
                            instance.items.append(item)
                        except Exception:
                            pass
        return instance

