def _get_state(wallet_name: str) -> _STATE:
        """
        Return current state of revocation registry builder process.

        :param wallet_name: name of wallet for corresponding Issuer
        :return: current process state as _STATE enum
        """
        state = _registry_state.get(wallet_name)
        if state is None:
            for fallback in ("UNKNOWN", "NOT_STARTED", "UNINITIALIZED"):
                if hasattr(_STATE, fallback):
                    return getattr(_STATE, fallback)
            raise ValueError(f"State for wallet '{wallet_name}' not found")
        return state

