mgc_code:
def flip_iterable_dict(d: dict) -> dict:
    """Transform dictionary to unpack values to map to respective key."""
    result = {}
    for key, val in d.items():
        # Determine if val should be treated as iterable of items
        if isinstance(val, (list, tuple, set, frozenset)):
            iterable = val
        elif isinstance(val, dict):
            iterable = val.keys()
        elif isinstance(val, (str, bytes)):
            iterable = (val,)
        else:
            try:
                iter(val)
                # Exclude non‑container iterables like numbers (which raise TypeError)
                iterable = val
            except TypeError:
                iterable = (val,)
        for item in iterable:
            result[item] = key
    return result

