mgc_code:
def load_hdf(cls, filename, path=''):
        """Loads OrbitPopulation from HDF file.

        :param filename:
            HDF file

        :param path:
            Path within HDF file store where :class:`OrbitPopulation` is saved.
        """
        import h5py

        with h5py.File(filename, 'r') as f:
            grp = f[path] if path else f

            # Load attributes
            attrs = {key: grp.attrs[key] for key in grp.attrs}

            # Load datasets
            data = {}
            for name in grp.keys():
                obj = grp[name]
                if isinstance(obj, h5py.Dataset):
                    data[name] = obj[...]
                elif isinstance(obj, h5py.Group):
                    # Recursively load groups as nested dicts
                    def _load_group(g):
                        result = {}
                        for k, v in g.items():
                            if isinstance(v, h5py.Dataset):
                                result[k] = v[...]
                            elif isinstance(v, h5py.Group):
                                result[k] = _load_group(v)

