mgc_code:
def reset(self):
        """
        Resets the state of this pipette, removing associated placeables,
        setting current volume to zero, and resetting tip tracking
        """
        # Clear any stored placeables
        if hasattr(self, "placeables"):
            try:
                self.placeables.clear()
            except Exception:
                # Fallback to resetting to an empty container
                self.placeables = [] if isinstance(self.placeables, list) else {}
        # Reset the current volume to zero
        if hasattr(self, "current_volume"):
            self.current_volume = 0
        # Reset tip tracking information
        if hasattr(self, "tip_tracker"):
            tip = self.tip_tracker
            # Prefer a dedicated reset method if available
            if hasattr(tip, "reset") and callable(tip.reset):
                tip.reset()
            else:
                try:
                    tip.clear()
                except Exception:
                    # If tip_tracker is a simple attribute, just nullify it
                    self.tip_tracker = None
        return None

