def Update(self, menu=None, tooltip=None,filename=None, data=None, data_base64=None,):
        """
        Updates the menu, tooltip or icon
        :param menu: menu defintion
        :param tooltip: string representing tooltip
        :param filename:  icon filename
        :param data:  icon raw image
        :param data_base64: icon base 64 image
        :return:
        """
        if menu is not None:
            self.menu = menu
        if tooltip is not None:
            self.tooltip = tooltip

        # Resolve icon data
        icon_data = None
        if filename is not None:
            try:
                with open(filename, "rb") as f:
                    icon_data = f.read()
            except Exception as e:
                raise ValueError(f"Unable to read icon file '{filename}': {e}")
        elif data is not None:
            if isinstance(data, (bytes, bytearray)):
                icon_data = bytes(data)
            else:
                raise TypeError("data must be bytes-like")
        elif data_base64 is not None:
            import base64
            try:
                icon_data = base64.b64decode(data_base64)
            except Exception as e:
                raise ValueError(f"Invalid base64 icon data: {e}")

        if icon_data is not None:
            self.icon_data = icon_data
        # No explicit return; method updates internal state.

