mgc_code:
def encode(self, delimiter=';'):
        """Encode a command string from message."""
        if not hasattr(self, "command"):
            raise AttributeError("Object has no attribute 'command'")
        cmd = self.command
        if cmd is None:
            return ""
        if isinstance(cmd, (list, tuple)):
            escaped_parts = []
            for part in cmd:
                part_str = "" if part is None else str(part)
                # Escape backslashes first
                part_str = part_str.replace("\\", "\\\\")
                # Escape the delimiter
                part_str = part_str.replace(delimiter, "\\" + delimiter)
                escaped_parts.append(part_str)
            return delimiter.join(escaped_parts)
        # For non-iterable command, just ensure delimiter is escaped
        cmd_str = str(cmd).replace("\\", "\\\\").replace(delimiter, "\\" + delimiter)
        return cmd_str

