def save_gui_settings(self, *a):
        """
        Saves just the current configuration of the controls if the
        autosettings_path is set.
        """
        import json, os
        path = getattr(self, "autosettings_path", None)
        if not path:
            return
        # Ensure the directory exists
        dir_name = os.path.dirname(path)
        if dir_name and not os.path.isdir(dir_name):
            try:
                os.makedirs(dir_name, exist_ok=True)
            except OSError:
                return
        # Retrieve current GUI settings; fallback to empty dict if method missing
        try:
            settings = self.get_gui_settings()
        except Exception:
            settings = {}
        # Serialize to JSON
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(settings, f, indent=2, sort_keys=True)
        except Exception:
            pass

