def _forward_mode(self, *args):
        """Forward mode differentiation for a sum"""
        total_val = 0
        total_der = 0
        has_dual = False
        for a in args:
            if hasattr(a, "val") and hasattr(a, "der"):
                total_val += a.val
                total_der += a.der
                has_dual = True
            else:
                total_val += a
        if has_dual:
            return type(self)(total_val, total_der)
        return total_val

