def derivatives(self, **kwargs):
        """ Evaluates the derivatives at the input parameter. """
        point = kwargs.get('point', getattr(self, 'params', {}))
        step = kwargs.get('step', 1e-6)
        func = getattr(self, 'func', None)
        if not callable(func):
            raise AttributeError("Object must have a callable 'func' attribute")
        grads = {}
        for key, val in point.items():
            p_plus = point.copy()
            p_minus = point.copy()
            p_plus[key] = val + step
            p_minus[key] = val - step
            f_plus = func(**p_plus)
            f_minus = func

