def handle_namespace_pattern(self, line: str, position: int, tokens: ParseResults) -> ParseResults:
        """Handle statements like ``DEFINE NAMESPACE X AS PATTERN "Y"``.

        :raises: RedefinedNamespaceError
        """
        # Extract namespace identifier and pattern string from the parsed tokens.
        # The ParseResults object typically provides attribute access for named
        # elements; fall back to positional indexing if attributes are missing.
        try:
            namespace = tokens.namespace
        except Exception:
            namespace = tokens[0] if len(tokens) > 0 else None

        try:
            pattern = tokens.pattern
        except Exception:
            # The pattern is usually the last token (e.g., the quoted string)
            pattern = tokens[-1] if len(tokens) > 1 else None

        if namespace is None or pattern is None:
            # If required components are missing, propagate a generic parsing error.
            raise ValueError(f"Invalid namespace pattern definition at position {position}: {line}")

        # Ensure the namespace has not been defined previously.
        if hasattr(self, "namespaces"):
            defined = self.namespaces
        else:
            # Lazily create a container for namespaces if it does not exist.
            defined = {}
            setattr(self, "namespaces", defined)

        if namespace in defined:
            raise RedefinedNamespaceError(f"Namespace '{namespace}' is already defined")

