def get_tensor_info(self):
    """See base class for details."""
    try:
        tensor = self.tensor
    except AttributeError as e:
        raise AttributeError("Object has no attribute 'tensor'") from e

    info = {}
    # Shape
    if hasattr(tensor, "shape"):
        try:
            info["shape"] = tuple(tensor.shape)
        except TypeError:
            # fallback for objects that expose shape as list/tuple
            info["shape"] = tuple(getattr(tensor, "shape"))
    # Data type
    if hasattr(tensor, "dtype"):
        info["dtype"] = str(tensor.dtype)
    # Device (for torch tensors or similar)
    if hasattr(tensor, "device"):
        info["device"] = str(tensor.device)

    return info

