def _totuple( x ):
    """Utility stuff to convert string, int, long, float, None or anything to a usable tuple."""
    if x is None:
        return ()
    if isinstance(x, tuple):
        return x
    if isinstance(x, (list, set, frozenset)):
        return tuple(x)
    if isinstance(x, (str, bytes)):
        return (x,)
    try:
        iter(x)
    except TypeError:
        return (x,)
    else:
        return tuple(x)

