def send(self, api, force_send):
        """
        Send this item using api.
        :param api: D4S2Api sends messages to D4S2
        :param force_send: bool should we send even if the item already exists
        """
        # Determine if we should skip sending based on existing record
        if not force_send:
            # Try to infer a unique identifier for the item
            item_id = getattr(self, "id", None)
            if item_id is not None:
                try:
                    # If the API can retrieve the item, assume it already exists
                    existing = api.get(item_id)
                    if existing is not None:
                        return False
                except Exception:
                    # If the API does not support `get` or raises, fall back to sending
                    pass
        # Perform the actual send operation; let any exception propagate
        return api.send(self)

