mgc_code:
def release_node(self, node):
        """
        release a single redis node
        """
        try:
            # Remove node from internal tracking structures if present
            if hasattr(self, "_nodes"):
                nodes = getattr(self, "_nodes")
                # List‑like container
                if isinstance(nodes, (list, set, tuple)):
                    try:
                        nodes.remove(node)
                    except (ValueError, AttributeError):
                        pass
                # Dict‑like container
                elif isinstance(nodes, dict):
                    keys_to_del = [k for k, v in nodes.items() if v is node]
                    for k in keys_to_del:
                        del nodes[k]

            # Attempt to gracefully close the node's connection
            close_fn = getattr(node, "close", None) or getattr(node, "disconnect", None)
            if callable(close_fn):
                close_fn()
        except Exception as exc:
            # Log the failure if a logger is available, then re‑raise
            logger = getattr(self, "logger", None)

