mgc_code:
def getHostsFromSGE():
    """Return a host list in a SGE environment"""
    import os, socket
    hosts = []
    hostfile = os.getenv('PE_HOSTFILE')
    if hostfile and os.path.isfile(hostfile):
        try:
            with open(hostfile) as f:
                for line in f:
                    parts = line.split()
                    if not parts:
                        continue
                    name = parts[0]
                    try:
                        slots = int(parts[1]) if len(parts) > 1 else 1
                    except Exception:
                        slots = 1
                    hosts.extend([name] * slots)
        except Exception:
            pass
    if not hosts:
        hosts = [socket.gethostname()]
    return hosts

