def do_glob_math(self, cont):
        """Performs #{}-interpolation.  The result is always treated as a fixed
        syntactic unit and will not be re-evaluated.
        """
        import re
        pattern = re.compile(r'#\{([^}]*)\}')
        def _replace(match):
            expr = match.group(1)
            try:
                # Evaluate using the instance's attribute dictionary as locals
                result = eval(expr, {}, self.__dict__)
                return str(result)
            except Exception:
                # If evaluation fails, leave the original text unchanged
                return match.group(0)
        return pattern.sub(_replace, cont)

