def connectCached(self, endpoint, protocolFactory,
                      extraWork=lambda x: x,
                      extraHash=None):
        """
        See module docstring

        @param endpoint:
        @param protocolFactory:
        @param extraWork:
        @param extraHash:

        @return: the D
        """
        if not hasattr(self, "_connectCache"):
            self._connectCache = {}
        # Determine cache key
        if extraHash is not None:
            try:
                key = (endpoint, extraHash(endpoint))
            except Exception:
                key = (endpoint, extraHash)
        else:
            key = endpoint
        # Return cached Deferred if present
        if key in self._connectCache:
            return self._connectCache[key]
        # Create new connection Deferred
        d = endpoint.connect(protocolFactory)
        # Apply any extra work to the result
        d.addCallback(extraWork)
        # Cache the Deferred for future calls
        self._connectCache[key] = d
        return d

def get_seaborn_clustermap(dfr, params, title=None, annot=True):
    """Returns a Seaborn clustermap."""
    import seaborn as sns
    import matplotlib.pyplot as plt

    if params is None:
        params = {}
    else:
        params = dict(params)  # copy to avoid mutating caller's dict

    # Ensure the annotation flag is set as requested
    params['annot'] = annot

    # Create the clustermap
    g = sns.clustermap(dfr, **params)

    # Apply title if provided
    if title is not None:
        g.ax_heatmap.set_title(title)

    return g

