def save(self, commit=True):
        """
        Saves this ``form``'s cleaned_data into model instance ``self.instance``
        and related EAV attributes.

        Returns ``instance``.
        """
        from django.db import transaction

        # Assign regular model fields
        for field_name, value in self.cleaned_data.items():
            if hasattr(self.instance, field_name):
                setattr(self.instance, field_name, value)
            else:
                # Fallback to EAV handling if the instance provides a setter
                if hasattr(self.instance, "set_eav"):
                    self.instance.set_eav(field_name, value)

        if commit:
            with transaction.atomic():
                self.instance.save()

        return self.instance

