def load_attributes(self):
        """Read the variables from the VARS_MODULE_PATH"""
        import os
        import importlib.util

        path = getattr(self, "VARS_MODULE_PATH", None)
        if not path:
            raise AttributeError("VARS_MODULE_PATH is not defined on the instance")
        if not os.path.isfile(path):
            raise FileNotFoundError(f"Variables module file not found: {path}")

        spec = importlib.util.spec_from_file_location("_vars_module", path)
        if spec is None or spec.loader is None:
            raise ImportError(f"Cannot create module spec for {path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        for name, value in vars(module).items():
            if name.startswith("_"):
                continue
            setattr(self, name, value)

