def _fix_unicode_list(self, columns):
        """
        Convenience wrapper for self.log which is passed a list of format arguments.
        """
        # Ensure all items are proper text strings before logging
        processed = []
        for item in columns:
            if isinstance(item, str):
                processed.append(item)
            elif isinstance(item, (bytes, bytearray)):
                try:
                    processed.append(item.decode('utf-8', 'replace'))
                except Exception:
                    processed.append(str(item))
            else:
                processed.append(str(item))
