mgc_code:
def is_nameserver(self, path):
        """Is the node pointed to by @ref path a name server (specialisation
        of directory nodes)?

        """
        try:
            # Try common accessor patterns
            if hasattr(self, "get_node"):
                node = self.get_node(path)
            else:
                node = self[path]  # type: ignore[index]
        except Exception:
            return False

        # Direct flag/property
        if hasattr(node, "is_nameserver"):
            return bool(getattr(node, "is_nameserver"))

        # Fallback: check type/name heuristics
        if getattr(node, "is_dir", False):
            cls_name = node.__class__.__name__.lower()
            if "nameserver" in cls_name:
                return True

        return False

