mgc_code:
def get_bcbio_timings(path):
    """Fetch timing information from a bcbio log file."""
    import re
    timings = {}
    pattern = re.compile(
        r'(?i)^\s*(?P<step>\w[\w\s-]*)[:\s]\s*'
        r'(?P<time>\d+(?:\.\d+)?)(?:\s*(?:seconds|s|sec))?'
    )
    with open(path, 'r', encoding='utf-8') as fh:
        for line in fh:
            m = pattern.search(line)
            if m:
                step = m.group('step').strip().replace(' ', '_')
                secs = float(m.group('time'))
                timings[step] = timings.get(step, 0.0) + secs
    return timings

