mgc_code:
def cache(opts, serial):
    """
    Returns the returner modules
    """
    import importlib

    returners = opts.get("returner", [])
    if isinstance(returners, str):
        returners = [r.strip() for r in returners.split(",") if r.strip()]
    elif not isinstance(returners, (list, tuple)):
        returners = []

    modules = {}
    for name in returners:
        if not name:
            continue
        try:
            mod = importlib.import_module(f"salt.returners.{name}")
            modules[name] = mod
        except ImportError as exc:
            raise ImportError(f"Unable to import returner '{name}': {exc}") from exc

    return modules

