def wrap_traceback(traceback):
    """
    For internal use only (until further notice)
    """
    import traceback as _tb
    # If an exception instance is provided, format its traceback
    if isinstance(traceback, BaseException):
        return "".join(_tb.format_exception(type(traceback), traceback, traceback.__traceback__))
    # If a traceback object is provided, format it
    if hasattr(traceback, "tb_frame"):
        return "".join(_tb.format_tb(traceback))
    # If a string (or bytes) is provided, return it as a string
    if isinstance(traceback, (str, bytes)):
        return traceback.decode() if isinstance(traceback, bytes) else traceback
    # Fallback: return the string representation
    return str(traceback)

