def secret_access_key(ecs_secret_access_key):
    """Display / set / update the ECS secret access key."""
    import os

    env_var = "ECS_SECRET_ACCESS_KEY"
    if ecs_secret_access_key is not None:
        os.environ[env_var] = str(ecs_secret_access_key)
        return os.environ[env_var]
    current = os.getenv(env_var)
    if current is None:
        print(f"{env_var} is not set.")
    else:
        print(f"{env_var}={current}")
    return current

