def get_extra(request):
    """Return information about a module / collection that cannot be cached."""
    # Determine module name from request endpoint or blueprint
    endpoint = getattr(request, "endpoint", None)
    if endpoint:
        # endpoint may be like 'module.view_func'
        module = endpoint.split(".", 1)[0]
    else:
        module = getattr(request, "blueprint", None)

    # Try to infer collection name from view arguments or query parameters
    collection = None
    view_args = getattr(request, "view_args", {})
    if isinstance(view_args, dict):
        collection = view_args.get("collection") or view_args.get("id")
    if not collection:
        args = getattr(request, "args", {})
        if isinstance(args, dict):
            collection = args.get("collection") or args.get("id")

    # Return a structure indicating the resource cannot be cached
    return {
        "module": module,
        "collection": collection,
        "cannot_cache": True,
    }

