mgc_code:
def get_serial():
    """
    Detect if a micro:bit is connected and return a serial object to talk to
    it.
    """
    import serial
    from serial.tools import list_ports

    # Known USB identifiers for BBC micro:bit
    MICROBIT_VID = 0x0D28
    MICROBIT_PID = 0x0204

    for port in list_ports.comports():
        # Some platforms expose vid/pid, others only description
        if getattr(port, "vid", None) == MICROBIT_VID and getattr(port, "pid", None) == MICROBIT_PID:
            return serial.Serial(port.device, baudrate=115200, timeout=1)
        if "micro:bit" in (port.description or "").lower():
            return serial.Serial(port.device, baudrate=115200, timeout=1)

    raise RuntimeError("No micro:bit device found on any serial port.")

