mgc_code:
def close_cache(self):
        """
        Close cache of WS Shinken
        """
        try:
            cache = getattr(self, "cache", None)
            if cache is None:
                return
            # If the cache object provides a close method, call it.
            close_method = getattr(cache, "close", None)
            if callable(close_method):
                close_method()
            # If the cache is a mutable mapping, clear its contents.
            if isinstance(cache, dict):
                cache.clear()
        finally:
            # Remove reference to the cache to aid garbage collection.
            if hasattr(self, "cache"):
                del self.cache

