def _configure_logging(self):
        """
        Setting up logging from logging config in settings
        """
        import logging
        import logging.config

        settings = getattr(self, "settings", None)
        if not settings:
            logging.basicConfig()
            return

        logging_cfg = getattr(settings, "LOGGING", None)
        if not logging_cfg:
            logging_cfg = getattr(settings, "logging", None)

        if logging_cfg:
            try:
                logging.config.dictConfig(logging_cfg)
            except Exception:
                logging.basicConfig()
        else:
            logging.basicConfig()

