mgc_code:
def find_module_defining_flag(self, flagname, default=None):
    """Return the name of the module defining this flag, or default.

    Args:
      flagname: str, name of the flag to lookup.
      default: Value to return if flagname is not defined. Defaults
          to None.

    Returns:
      The name of the module which registered the flag with this name.
      If no such module exists (i.e. no flag with this name exists),
      we return default.
    """
    try:
        flag = self._flags[flagname]  # type: ignore[index]
    except Exception:
        return default
    # Flag may be stored as an object with a 'module' attribute,
    # or as a dict containing a 'module' key.
    if isinstance(flag, dict):
        return flag.get('module', default)
    return getattr(flag, 'module', default)

