def lookup_endpoint(cli):
    """Looks up the application endpoint from dotcloud"""
    # Try direct attribute
    try:
        return cli.endpoint
    except AttributeError:
        pass

    # Try a config mapping
    cfg = getattr(cli, "config", None)
    if isinstance(cfg, dict):
        ep = cfg.get("endpoint")
        if ep:
            return ep

    # Try a callable accessor
    get_ep = getattr(cli, "get_endpoint", None)
    if callable(get_ep):
        try:
            return get_ep()
        except Exception:
            pass

    # No endpoint found
    return None

