def stop(self):
        """
        Shuts the server down and waits for server thread to join
        """
        import threading
        # Attempt to gracefully shut down the server if possible
        try:
            srv = getattr(self, "server", None)
            if srv is not None:
                shutdown = getattr(srv, "shutdown", None)
                if callable(shutdown):
                    shutdown()
        finally:
            # Ensure the server thread terminates
            thr = getattr(self, "thread", None)
            if isinstance(thr, threading.Thread):
                thr.join()
            elif thr is not None:
                try:
                    thr.join()
                except Exception:
                    pass

