mgc_code:
def range(self, start_row=0, max_rows=None):
    """ Get an iterator to iterate through a set of table rows.

    Args:
      start_row: the row of the table at which to start the iteration (default 0)
      max_rows: an upper limit on the number of rows to iterate through (default None)

    Returns:
      A row iterator.
    """
    import itertools

    if not isinstance(start_row, int) or start_row < 0:
        raise ValueError("start_row must be a non‑negative integer")
    if max_rows is not None:
        if not isinstance(max_rows, int) or max_rows < 0:
            raise ValueError("max_rows must be a non‑negative integer or None")
        stop = start_row + max_rows
    else:
        stop = None

    # Assume the object is iterable and supports slicing via itertools.islice
    return itertools.islice(self, start_row, stop)

