def compute_taxes(self, precision=None):
        """
        Returns the total amount of taxes for this line with a specific 
        number of decimals
        @param precision: int Number of decimal places
        @return: Decimal
        """
        from decimal import Decimal, ROUND_HALF_UP

        total = Decimal('0')
        for tax in getattr(self, 'taxes', []):
            try:
                amount = tax.amount
            except AttributeError:
                amount = tax
            if not isinstance(amount, Decimal):
                amount = Decimal(str(amount))
            total += amount

        if precision is not None:
            if not isinstance(precision, int) or precision < 0:
                raise ValueError("precision must be a non‑negative integer")
            quant = Decimal('1').scaleb(-precision)  # 10**-precision
            total = total.quantize(quant, rounding=ROUND_HALF_UP)

        return total

