def check(ctx, meta_model_file, model_file, ignore_case):
    """
    Check validity of meta-model and optionally model.
    """
    import os
    import json

    def _load_json(path):
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)

    def _lower_keys(obj):
        if isinstance(obj, dict):
            return {k.lower(): _lower_keys(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_lower_keys(item) for item in obj]
        return obj

    # Verify meta‑model file exists
    if not isinstance(meta_model_file, (str, bytes, os.PathLike)):
        raise TypeError("meta_model_file must be a path-like object")
    if not os.path.isfile(meta_model_file):
        raise FileNotFoundError(f"Meta‑model file not found: {meta_model_file}")

    meta_model = _load_json(meta_model_file)

