def gen_random_key(size=32):
    """
    Generate a cryptographically-secure random key. This is done by using
    Python 2.4's os.urandom, or PyCrypto.
    """
    import os
    try:
        # Prefer built‑in os.urandom for cryptographic randomness
        return os.urandom(size)
    except Exception:
        # Fallback to PyCrypto / PyCryptodome if os.urandom is unavailable
        try:
            from Crypto.Random import get_random_bytes
            return get_random_bytes(size)
