mgc_code:
def get_encoding_from_headers(headers):
    """Returns encodings from given HTTP Header Dict.

    :param headers: dictionary to extract encoding from.
    :rtype: str
    """
    # Normalize header keys to lower case for case‑insensitive lookup
    content_type = None
    for key, value in headers.items():
        if key.lower() == "content-type":
            content_type = value
            break

    if not content_type:
        return None

    # Header value may be a list/tuple of values; use the first one
    if isinstance(content_type, (list, tuple)):
        if not content_type:
            return None
        content_type = content_type[0]

    # Ensure we are working with a string
    if isinstance(content_type, bytes):
        try:
            content_type = content_type.decode("utf-8", errors="replace")
        except Exception:
            return None

    # Split on ';' and look for charset parameter
    parts = content_type.split(";")
    for part in parts[1:]:  # skip the media type itself
        if "charset" in part.lower():
            # Expected format: charset=VALUE
            _, _, charset = part.partition("=")
            charset = charset.strip().strip('"\'')
            return charset or None

    return None

