def transform_record(self, pid, record, links_factory=None, **kwargs):
        """Transform record into an intermediate representation."""
        # Prepare a shallow copy of the record to avoid mutating the original
        result = dict(record) if isinstance(record, dict) else {"value": record}
        # Ensure the primary identifier is present
        result.setdefault("pid", pid)
        # Build links if a factory is supplied
        if links_factory is not None:
            try:
                links = links_factory(record)
            except Exception as exc:
                raise RuntimeError(f"links_factory raised an exception: {exc}") from exc
            result["links"] = links
        # Merge any additional keyword arguments, overriding existing keys
        result.update(kwargs)
        return result

