mgc_code:
def sd(self):
        """Calculate standard deviation of timeseries"""
        import math
        # Try to obtain a sequence of numeric values from the instance
        try:
            values = list(self)
        except TypeError:
            # Fallback to common attribute names
            if hasattr(self, "values"):
                values = list(self.values)
            elif hasattr(self, "data"):
                values = list(self.data)
            else:
                raise AttributeError("Unable to retrieve timeseries data for standard deviation calculation")
        n = len(values)
        if n == 0:
            return 0.0
        if n == 1:
            return 0.0
        mean = sum(values) / n
        # Sample standard deviation (denominator n-1)
        variance = sum((x - mean) ** 2 for x in values) / (n - 1)
        return math.sqrt(variance)

