def write_packages(self, reqs_file):
        """
        Dump the packages in the catalog in a requirements file
        """
        try:
            items = self.catalog.items()
        except AttributeError:
            items = [(p.name, getattr(p, "version", None)) for p in getattr(self, "packages", [])]
        lines = []
        for name, version in items:
            if not name:
                continue
            lines.append(f"{name}=={version}" if version else name)
        lines.sort()
        with open(reqs_file, "w", encoding="utf-8") as f:
            if lines:
                f.write("\n".join(lines) + "\n")

