def print_all_signals(self):
        """
        Prints out every signal available for this widget and childs.
        """
        from PyQt5.QtCore import QMetaMethod, QObject

        def _collect_signals(obj):
            meta = obj.metaObject()
            for i in range(meta.methodCount()):
                method = meta.method(i)
                if method.methodType() == QMetaMethod.Signal:
                    # method.name() returns QByteArray; decode to str
                    name = bytes(method.name()).decode()
                    print(f"{obj.__class__.__name__}: {name}")

            for child in obj.findChildren(QObject):
                _collect_signals(child)

        _collect_signals(self)

