def __query_cmd(self, command, device=None):
        """Calls a command"""
        target = device if device is not None else getattr(self, "device", None)
        if target is None:
            import subprocess
            try:
                output = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT)
