def _onCoreModuleLoad(self, event):
        """
        Clear the cached model rows and rebuild them only if they have been loaded already.
        """
        # Clear any cached rows
        if hasattr(self, "_modelRowsCache"):
            try:
                self._modelRowsCache.clear()
            except Exception:
                self._modelRowsCache = {}
        elif hasattr(self, "modelRows"):
            try:
                self.modelRows.clear()
            except Exception:
                self.modelRows = []

        # Rebuild rows only if they were previously loaded
        if getattr(self, "_modelRowsLoaded", False):
            rebuild = getattr(self, "_buildModelRows", None) or getattr(self, "buildModelRows", None)
            if callable(rebuild):
                rebuild()
        return None

