mgc_code:
def array2image(array, nx=0, ny=0):
    """
    returns the information contained in a 1d array into an n*n 2d array (only works when lenght of array is n**2)

    :param array: image values
    :type array: array of size n**2
    :returns:  2d array
    :raises: AttributeError, KeyError
    """
    try:
        length = len(array)
    except Exception as e:
        raise AttributeError("Provided object has no length") from e

    if nx and ny:
        rows, cols = nx, ny
        if rows * cols != length:
            raise KeyError("Provided dimensions do not match array length")
    else:
        import math
        n = int(math.isqrt(length))
        if n * n != length:
            raise KeyError("Length of array is not a perfect square")
        rows = cols = n

    return [list(array[i * cols:(i + 1) * cols]) for i in range(rows)]

