def recvall(sock, size):
    """
    Receive data of given size from a socket connection
    """
    data = bytearray()
    while len(data) < size:
        chunk = sock.recv(size - len(data))
        if not chunk:
            raise EOFError(f"Socket closed with {size - len(data)} bytes left to read")
        data.extend(chunk)
    return bytes(data)

