def display_assignment_changes(plan_details, to_log=True):
    """Display current and proposed changes in
    topic-partition to replica layout over brokers.
    """
    import logging

    logger = logging.getLogger(__name__)

    def _output(msg):
        if to_log:
            logger.info(msg)
        else:
            print(msg)

    # Normalise input into a mapping: (topic, partition) -> (current, proposed)
    assignments = {}
    if isinstance(plan_details, dict):
        if "current" in plan_details and "proposed" in plan_details:
            cur = plan_details["current"]
            prop = plan_details["proposed"]
            # Expect cur and prop to be dicts keyed by (topic, partition)
            for key in set(cur) | set(prop):
                assignments[key] = (cur.get(key, []), prop.get(key, []))
        else:
            # Assume each value is a dict with 'current' and 'proposed' keys
            for key, val in plan_details.items():
                cur = val.get("current", [])
                prop = val.get("proposed", [])
                assignments[key] = (cur, prop)

    # Sort by topic then partition for deterministic output
    def _sort_key(item):
        topic, part

