mgc_code:
def remove_node(node_id=str, force=bool):
    """
    Remove a node from a swarm and the target needs to be a swarm manager

    node_id
        The node id from the return of swarm.node_ls

    force
        Forcefully remove the node/minion from the service

    CLI Example:

    .. code-block:: bash

        salt '*' swarm.remove_node node_id=z4gjbe9rwmqahc2a91snvolm5 force=false
    """
    import subprocess

    cmd = ["docker", "node", "rm"]
    if force:
        cmd.append("--force")
    cmd.append(node_id)

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except Exception as exc:  # pragma: no cover
        return {"result": False, "comment": f"Exception while executing docker: {exc}"}

    if result.returncode == 0:
        return {"result": True, "comment": result.stdout.strip()}
    else:
        return {
            "result": False,
            "comment": result.stderr.strip() or result.stdout.strip(),
        }

