                    sys.exit(1)

mgc_code:
def stop(self):
        """Stop the daemon."""
        # Signal any stop event if present
        stop_event = getattr(self, "_stop_event", None)
        if stop_event is not None:
            try:
                stop_event.set()
            except Exception:
                pass

        # Join a running thread if present
        thread = getattr(self, "_thread", None)
        if thread is not None:
            try:
                if thread.is_alive():
                    thread.join()
            except Exception:
                pass

        # Terminate a subprocess if present
        proc = getattr(self, "process", None)
        if proc is not None:
            try:
                proc.terminate()
                proc.wait()
            except Exception:
                pass

        # Clear running flag if used
        if hasattr(self, "_running"):
            try:
                self._running = False
            except Exception:
                pass

