mgc_code:
def email_domain_disposable(value):
    """
    Confirms that the email address is not using a disposable service.
    @param {str} value
    @returns {None}
    @raises AssertionError

    """
    if not isinstance(value, str):
        raise AssertionError("Email must be a string")
    parts = value.rsplit("@", 1)
    if len(parts) != 2 or not parts[0] or not parts[1]:
        raise AssertionError("Invalid email format")
    domain = parts[1].lower()
    disposable_domains = {
        "mailinator.com",
        "trashmail.com",
        "10minutemail.com",
        "guerrillamail.com",
        "temp-mail.org",
        "yopmail.com",
        "dispostable.com",
        "maildrop.cc",
        "tempmail.com",
        "fakeinbox.com",
        "getnada.com",
        "mailnesia.com",
        "spamgourmet.com",
        "throwawaymail.com",
    }
    if domain in disposable_domains:
        raise AssertionError(f"Disposable email domain not allowed: {domain}")

