mgc_code:
def lmedian (inlist,numbins=1000):
    """
Returns the computed median value of a list of numbers, given the
number of bins to use for the histogram (more bins brings the computed value
closer to the median score, default number of bins = 1000).  See G.W.
Heiman's Basic Stats (1st Edition), or CRC Probability & Statistics.

Usage:   lmedian (inlist, numbins=1000)
"""
    if not inlist:
        raise ValueError("lmedian() arg is an empty sequence")
    if numbins <= 0:
        raise ValueError("numbins must be a positive integer")
    total = len(inlist)
    half = total / 2.0
    lo = min(inlist)
    hi = max(inlist)
    if lo == hi:
        return float(lo)
    bin_width = (hi - lo) / float(numbins)
    # Initialize bins
    bins = [0] * numbins
    for x in inlist:
        # Clamp index to valid range
        idx = int((x - lo) / bin_width)
        if idx >= numbins:
            idx = numbins - 1
        bins[idx] += 1
    cum = 0
    for i, cnt in enumerate(bins):
        cum += cnt
        if cum >= half:
            # Median lies in this bin
            cum_before = cum - cnt
            # Avoid division by zero
            if cnt == 0:
                median = lo + i * bin_width
            else:
                fraction = (half - cum_before) / cnt
                median = lo + (i + fraction) * bin_width
            return float(median)
    # Fallback (should not reach here)
    return float(hi)

