mgc_code:
def _mutate_probability_vec(probability_vec, mutation_chance, mutation_adjust_rate):
    """Randomly adjust probabilities.

    WARNING: Modifies probability_vec argument.
    """
    import random

    n = len(probability_vec)
    for i in range(n):
        if random.random() < mutation_chance:
            delta = (random.random() * 2.0 - 1.0) * mutation_adjust_rate
            new_val = probability_vec[i] + delta
            probability_vec[i] = new_val if new_val > 0 else 0.0

    total = sum(probability_vec)
    if total > 0.0:
        inv_total = 1.0 / total
        for i in range(n):
            probability_vec[i] *= inv_total
    else:
        # fallback to uniform distribution if all entries became zero
        uniform = 1.0 / n if n else 0.0
        for i in range(n):
            probability_vec[i] = uniform

