def getElementsByTagName(start_node: ParentNode, tag: str) -> NodeList:
    """Get child nodes which tag name is ``tag``."""
    result = []
    stack = [start_node]
    while stack:
        node = stack.pop()
        children = getattr(node, "children", getattr(node, "childNodes", []))
        for child in children:
            if getattr(child, "tagName", None) == tag:
                result.append(child)
            stack.append(child)
    return result

