mgc_code:
def _extract_info(archive, info):
    """
    Extracts the contents of an archive info object

    ;param archive:
        An archive from _open_archive()

    :param info:
        An info object from _list_archive_members()

    :return:
        None, or a byte string of the file contents
    """
    try:
        # ZipFile-like archives: .read() works with ZipInfo or filename
        if hasattr(archive, "read"):
            return archive.read(info)
    except Exception:
        pass

    try:
        # TarFile-like archives: .extractfile() returns a file‑like object
        if hasattr(archive, "extractfile"):
            fileobj = archive.extractfile(info)
            if fileobj is None:
                return None
            try:
                return fileobj.read()
            finally:
                fileobj.close()
    except Exception:
        pass

    return None

