def normalize_node(node, headers=None):
    """Normalizes given node as str or dict with headers"""
    headers = {} if headers is None else headers
    if isinstance(node, str):
        url = normalize_url(node)
        return {'endpoint': url, 'headers': headers}

    url = normalize_url(node['endpoint'])
    node_headers = node.get('headers', {})
    return {'endpoint': url, 'headers': {**headers, **node_headers}}

mgc_code:
def normalize_node(node, headers=None):
    """Normalizes given node as str or dict with headers"""
    if node is None:
        return None
    if isinstance(node, dict):
        result = dict(node)
        if headers:
            existing = result.get('headers')
            if isinstance(existing, dict):
                merged = {**existing, **headers}
            else:
                merged = dict(headers)
            result['headers'] = merged
        elif 'headers' not in result:
            result['headers'] = {}
        return result
    if not isinstance(node, str):
        node = str(node)
    return {'value': node, 'headers': dict(headers) if headers else {}}

