def _get_config(filename):
    """
    Parse the provided YAML file and return a dict.

    :parse filename: A string containing the path to YAML file.
    :return: dict
    """
    import yaml
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Configuration file not found: {filename}") from e
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML file: {filename}") from e

    if not isinstance(data, dict):
        return {}
    return data

