mgc_code:
def createKmerProfile(self, k, profileCsvFN):
        """
        TODO: this method is oldddddd, needs to be ported into BasicBWT AND reworked to do this better
        @param k - the length of the k-mers to profile
        @param profileCsvFN - the filename of the csv to create
        """
        # Determine the source string for k‑mer extraction
        if hasattr(self, "sequence"):
            src = self.sequence
        elif hasattr(self, "text"):
            src = self.text
        else:
            raise AttributeError("Object has no attribute 'sequence' or 'text' for k‑mer profiling.")
        if not isinstance(src, str):
            raise TypeError("Source for k‑mer profiling must be a string.")
        if k <= 0:
            raise ValueError("k must be a positive integer.")
        # Count k‑mers
        from collections import Counter
        kmers = (src[i:i + k] for i in range(len(src) - k + 1))
        counts = Counter(kmers)
        # Write CSV
        import csv
        with open(profileCsvFN, "w", newline="") as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["kmer", "count"])
            for kmer in sorted(counts):
                writer.writerow([kmer, counts[kmer]])
        return counts

