def get_extra_files():
    """returns a list of files that should be watched by the Flask server
    when in debug mode to trigger a reload of the server
    """
    import os

    base_dir = os.path.abspath(os.path.dirname(__file__))
    extensions = {".py", ".html", ".jinja2", ".css", ".js"}
    extra_files = []

    for root, dirs, files in os.walk(base_dir):
        # Skip hidden directories and common cache folders
        dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__pycache__"]
        for filename in files:
            _, ext = os.path.splitext(filename)
            if ext.lower() in extensions:
                extra_files.append(os.path.join(root, filename))

    return extra_files

