def terminate(self, devices):
        """Terminate one or more running or stopped instances.
        """
        # Ensure devices is iterable
        if devices is None:
            return []
        if not isinstance(devices, (list, tuple, set)):
            devices = [devices]

        results = []
        for dev in devices:
            try:
                # Prefer a direct terminate method on the device object
                if hasattr(dev, "terminate") and callable(dev.terminate):
                    result = dev.terminate()
                # Fallback to a client API that accepts an identifier
                elif hasattr(self, "client") and hasattr(self.client, "terminate_instance"):
                    identifier = getattr(dev, "id", None) or getattr(dev, "instance_id", None)
                    if identifier is None:
                        raise AttributeError("Device lacks an identifier for termination")
                    result = self.client.terminate_instance(identifier)
                else:
                    raise NotImplementedError(
                        "No termination method available for device or client"
                    )
                results.append(bool(result))
            except Exception as exc:
                # Record failure as False; optionally re‑raise or log as needed
                results.append(False)
        return results

