def simple_generate(cls, create, **kwargs):
        """Generate a new instance.

        The instance will be either 'built' or 'created'.

        Args:
            create (bool): whether to 'build' or 'create' the instance.

        Returns:
            object: the generated instance
        """
        if create:
            if not hasattr(cls, "create"):
                raise AttributeError(f"{cls.__name__} has no 'create' method")
            return cls.create(**kwargs)
        else:
            if not hasattr(cls, "build"):
                raise AttributeError(f"{cls.__name__} has no 'build' method")
            return cls.build(**kwargs)

