mgc_code:
def load_pip_addons(_globals):
    """Load all known fabsetup addons which are installed as pypi pip-packages.

    Args:
        _globals(dict): the globals() namespace of the fabric script.

    Return: None
    """
    try:
        # Python 3.10+
        from importlib.metadata import entry_points
        eps = entry_points().select(group="fabsetup.addons")
    except Exception:
        # Fallback for older Python versions
        import pkg_resources
        eps = pkg_resources.iter_entry_points("fabsetup.addons")
    for ep in eps:
        try:
            module = ep.load()
        except Exception:
            continue
        names = getattr(module, "__all__", None)
        if names is None:
            names = [n for n in dir(module) if not n.startswith("_")]
        for name in names:
            _globals[name] = getattr(module, name)

