def to_strings(self):
        """
        Convert the expansion node to a list of expansion strings.

        :return: a list of expansion strings that represent the leaf nodes of the expansion tree.
        :rtype: list[union[str, unicode]]
        """
        result = []

        if not self.expansions:
            result.append(self.name)
        else:
            for expansion in self.expansions:
                result.extend('{}.{}'.format(self.name, es) for es in expansion.to_strings())

        return result

mgc_code:
def to_strings(self):
        """
        Convert the expansion node to a list of expansion strings.

        :return: a list of expansion strings that represent the leaf nodes of the expansion tree.
        :rtype: list[union[str, unicode]]
        """
        result = []
        children = getattr(self, "children", None)
        if children:
            for child in children:
                if hasattr(child, "to_strings"):
                    result.extend(child.to_strings())
                elif isinstance(child, (str,)):
                    result.append(child)
        else:
            val = getattr(self, "value", None)
            if isinstance(val, (str,)):
                result.append(val)
            elif isinstance(self, (str,)):
                result.append(self)
        return result

