mgc_code:
def group(self):
        """Yield a group from the iterable"""
        it = iter(self)
        try:
            current = next(it)
        except StopIteration:
            return
        group = [current]
        for item in it:
            if item == current:
                group.append(item)
            else:
                yield group
                current = item
                group = [item]
        yield group

