def _other_to_dict(self, other):
    """When serializing models, this allows attached models (children, parents, etc.) to also be
    serialized.
    """
    if isinstance(other, ModelBase):
      return other.to_dict()
    elif isinstance(other, list):
      # TODO: what if it's not a list?
      return [self._other_to_dict(i) for i in other]
    else:
      return other

mgc_code:
def _other_to_dict(self, other):
    """When serializing models, this allows attached models (children, parents, etc.) to also be
    serialized.
    """
    if other is None:
        return None
    # If the object has its own serialization method, use it.
    if hasattr(other, "to_dict") and callable(other.to_dict):
        return other.to_dict()
    # Recursively handle mappings.
    if isinstance(other, dict):
        return {k: self._other_to_dict(v) for k, v in other.items()}
    # Recursively handle iterable containers (list, tuple, set).
    if isinstance(other, (list, tuple, set)):
        return [self._other_to_dict(item) for item in other]
    # Fallback: return the value unchanged.
    return other

