def get_item_with_id(self, uid):
        """
        Returns item for defined UID.

        >>> book.get_item_with_id('image_001')

        :Args:
          - uid: UID for the item

        :Returns:
          Returns item object. Returns None if nothing was found.
        """
        # Try dictionary-like storage first
        if hasattr(self, 'items'):
            items = getattr(self, 'items')
            if isinstance(items, dict):
                return items.get(uid, None)
            # If items is a list/tuple, search for matching uid attribute or key
            for item in items:
                # Support dict items with 'uid' key
                if isinstance(item, dict) and item.get('uid') == uid:
                    return item
                # Support objects with uid attribute
                if hasattr(item, 'uid') and getattr(item, 'uid') == uid:
                    return item
        # Fallback to a generic attribute that might store items
        for attr_name in ('_items', 'data', 'entries'):
            if hasattr(self, attr_name):
                collection = getattr(self, attr_name)
                if isinstance(collection, dict):
                    if uid in collection:
                        return collection[uid]
                else:
                    for item in collection:
                        if isinstance(item, dict) and item.get('uid') == uid:
                            return item
                        if hasattr(item, 'uid') and getattr(item, 'uid') == uid:
                            return item
        return None

