def _find_nml(self):
        """
        Find the start and end of the embedded namelist.

        Returns
        -------
        (int, int)
            start and end index for the namelist
        """
        # Determine source lines
        if hasattr(self, "lines"):
            lines = self.lines
        elif hasattr(self, "_lines"):
            lines = self._lines
        elif hasattr(self, "text"):
            lines = self.text.splitlines()
        else:
            raise AttributeError("Object has no attribute 'lines', '_lines', or 'text' to search for namelist.")
        start = end = None
        for i, line in enumerate(lines):
            stripped = line.lstrip()
            if start is None and stripped.startswith("&"):
                start = i
                continue
            if start is not None and line.strip() == "/":
                end = i
                break
        if start is None or end is None:
            raise ValueError("Unable to locate namelist start/end in provided content.")
        return start, end

