def decrypt(self, key):
        """This method checks the signature on the state and decrypts it.

        :param key: the key to decrypt and sign with
        """
        try:
            # Verify the signature first
            if not hasattr(key, "verify"):
                raise TypeError("Key object must provide a 'verify' method")
            key.verify(self.signature, self.encrypted_state)

            # Decrypt the payload
            if not hasattr(key, "decrypt"):
                raise TypeError("Key object must provide a 'decrypt' method")
            return key.decrypt(self.encrypted_state)
        except Exception as exc:
            raise ValueError("Signature verification or decryption failed") from exc

