mgc_code:
def set_current(self, channel, value, unit='A'):
        """Setting current of current source
        """
        # Validate unit
        allowed_units = {'A', 'mA', 'uA'}
        if unit not in allowed_units:
            raise ValueError(f"Unsupported unit '{unit}'. Allowed units: {allowed_units}")

        # Convert and validate value
        try:
            val = float(value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Current value must be numeric, got {value!r}") from exc

        # Build command string (generic SCPI-like syntax)
        cmd = f"SOUR:CURR {channel},{val}{unit}"

        # Send command to instrument; expect a 'write' method on the instance
        if not hasattr(self, "write"):
            raise AttributeError("Instance has no 'write' method to send commands to the instrument")
        self.write(cmd)

        # Keep a local record of the set value for possible later queries
        if not hasattr(self, "_current_state"):
            self._current_state = {}
        self._current_state[channel] = (val, unit)

