def _has_file_rolled(self):
        """Check if the file has been rolled"""
        import os, time
        # Size‑based rollover
        max_bytes = getattr(self, "maxBytes", 0)
        if max_bytes:
            try:
                if os.path.getsize(self.baseFilename) >= max_bytes:
                    return True
            except OSError:
                return False
        # Time‑based rollover
        rollover_at = getattr(self, "rolloverAt", None)
        if rollover_at is not None:
            if int(time.time()) >= rollover_at:
                return True
        return False

