def add_wirevector(self, wirevector):
        """ Add a wirevector object to the block."""
        # Initialize storage attributes if they don't exist
        if not hasattr(self, "_wirevectors"):
            self._wirevectors = []
        if not hasattr(self, "_wirevectors_by_name"):
            self._wirevectors_by_name = {}

        # Basic validation
        if not hasattr(wirevector, "name"):
            raise AttributeError("wirevector must have a 'name' attribute")
        name = wirevector.name

        # Prevent duplicate insertion
        if name in self._wirevectors_by_name:
            raise ValueError(f"WireVector with name '{name}' already added to the block")

        # Store the wirevector
        self._wirevectors.append(wirevector)
        self._wirevectors_by_name[name] = wirevector

