import os
from pathlib import Path

def _parse_keywords_file(path):
    result = {}
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.split("#", 1)[0].strip()
                if not line:
                    continue
                parts = line.split()
                atom = parts[0]
                keywords = set(parts[1:]) if len(parts) > 1 else set()
                if atom in result:
                    result[atom].update(keywords)
                else:
                    result[atom] = keywords
    except FileNotFoundError:
        pass
    return result

base_path = Path("/etc/portage/package.keywords")
accept_path = Path("/etc/portage/package.accept_keywords")

base = _parse_keywords_file(base_path)
accept = _parse_keywords_file(accept_path)

# Merge: accept keywords augment base keywords
for atom, kws in accept.items():
    if atom in base:
        base[atom].update(kws)
    else:
        base[atom] = kws

