def _unify_keywords():
    """
    Merge /etc/portage/package.keywords and
    /etc/portage/package.accept_keywords.
    """
    old_path = BASE_PATH.format('keywords')
    if os.path.exists(old_path):
        if os.path.isdir(old_path):
            for triplet in salt.utils.path.os_walk(old_path):
                for file_name in triplet[2]:
                    file_path = '{0}/{1}'.format(triplet[0], file_name)
                    with salt.utils.files.fopen(file_path) as fh_:
                        for line in fh_:
                            line = salt.utils.stringutils.to_unicode(line).strip()
                            if line and not line.startswith('#'):
                                append_to_package_conf(
                                    'accept_keywords', string=line)
            shutil.rmtree(old_path)
        else:
            with salt.utils.files.fopen(old_path) as fh_:
                for line in fh_:
                    line = salt.utils.stringutils.to_unicode(line).strip()
                    if line and not line.startswith('#'):
                        append_to_package_conf('accept_keywords', string=line)
            os.remove(old_path)

mgc_code:
def _unify_keywords():
    """
    Merge /etc/portage/package.keywords and
    /etc/portage/package.accept_keywords.
    """
    import os
    from pathlib import Path

    def _parse_keywords_file(path):
        result = {}
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.split("#", 1)[0].strip()
                    if not line:
                        continue
                    parts = line.split()
                    atom = parts[0]
                    keywords = set(parts[1:]) if len(parts) > 1 else set()
                    if atom in result:
                        result[atom].update(keywords)
                    else:
                        result[atom] = keywords
        except FileNotFoundError:
            pass
        return result

    base_path = Path("/etc/portage/package.keywords")
    accept_path = Path("/etc/portage/package.accept_keywords")

    base = _parse_keywords_file(base_path)
    accept = _parse_keywords_file(accept_path)

    # Merge: accept keywords augment base keywords
    for atom, kws in accept.items():
        if atom in base:
            base[atom].update(kws)
        else:
            base[atom] = kws

