mgc_code:
def closeTab(self, item):
        """
        Requests a close for the inputed tab item.

        :param      item | <XViewPanelItem>
        """
        # Try to locate the tab index in a QTabWidget if present
        tab_widget = getattr(self, "tabWidget", None)
        if tab_widget is not None:
            # The item might be a widget itself or expose a widget attribute
            widget = getattr(item, "widget", None) or item
            try:
                index = tab_widget.indexOf(widget)
            except Exception:
                index = -1
            if index != -1:
                # If the item provides a custom close request method, use it first
                if hasattr(item, "requestClose"):
                    try:
                        item.requestClose()
                    except Exception:
                        pass
                # Remove the tab and clean up the widget
                tab_widget.removeTab(index)
                if hasattr(widget, "deleteLater"):
                    try:
                        widget.deleteLater()
                    except Exception:
                        pass
                return True

        # Fallback: if the object has a close method, call it
        if hasattr(item, "close"):
            try:
                item.close()
                return True
            except Exception:
                pass

        # If the item is stored in a custom list of tabs, attempt to remove it
        tabs = getattr(self, "_tabs", None)

