def angle2d(self):
        """determine the angle of this point on a circle, measured in radians (presume values represent a Vector)"""
        import math
        try:
            x = self.x
            y = self.y
        except AttributeError:
            try:
                x, y = self[0], self[1]
            except Exception:
                raise TypeError("Object must have 'x' and 'y' attributes or be indexable with two elements")
        if x == 0 and y == 0:
            return 0.0
        return math.atan2(y, x)

