def _comp_task(inbox, args, kwargs):
    """
    (internal) Composes a sequence of functions in the global variable TASK. The
    resulting composition is given the input "inbox" and arguments "args", 
    "kwargs".

    """
    try:
        task_seq = TASK
    except NameError:
        task_seq = ()
    result = inbox
    for fn in task_seq:
        if fn is None:
            continue
        result = fn(result, *args, **kwargs)
    return result

