mgc_code:
def _on_client_connect(self, data):
        """Handle client connect."""
        client_id = data.get('client_id')
        if client_id is None:
            raise ValueError("Missing 'client_id' in connection data")
        # Register the client
        if not hasattr(self, 'clients'):
            self.clients = {}
        self.clients[client_id] = data
        # Acknowledge the connection if a send method exists
        if hasattr(self, 'send') and callable(self.send):
            try:
                self.send(client_id, {'type': 'connect_ack', 'status': 'ok'})
            except Exception:
                pass
        # Log the event if a logger is available
        if hasattr(self, 'logger') and hasattr(self.logger, 'info'):
            self.logger.info("Client %s connected", client_id)
        return True

