mgc_code:
def apt_install(packages, options=None, fatal=False):
    """Install one or more packages."""
    import subprocess
    import shlex

    if not packages:
        raise ValueError("No packages specified for installation")
    # Normalize packages to a list of strings
    if isinstance(packages, (str, bytes)):
        pkg_list = shlex.split(packages)
    else:
        try:
            pkg_list = list(packages)
        except TypeError:
            raise TypeError("packages must be a string or an iterable of strings")
    # Normalize options
    opt_list = []
    if options:
        if isinstance(options, (str, bytes)):
            opt_list = shlex.split(options)
        else:
            try:
                opt_list = list(options)
            except TypeError:
                raise TypeError("options must be a string or an iterable of strings")
    # Build the command
    cmd = ["apt-get", "install", "-y"] + opt_list + pkg_list
    # Execute
    result = subprocess.run(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=fatal
    )
    return result

