mgc_code:
def detach_zone(organization_id_or_slug):
    """Detach the zone of a given <organization>."""
    import os
    import requests

    base_url = os.getenv("API_BASE_URL", "https://api.example.com")
    token = os.getenv("API_TOKEN")
    if not token:
        raise RuntimeError("API_TOKEN environment variable not set")

    url = f"{base_url.rstrip('/')}/organizations/{organization_id_or_slug}/zone/detach"
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}

    response = requests.post(url, headers=headers, timeout=30)
    try:
        data = response.json()
    except ValueError:
        response.raise_for_status()
        return {}

    if not response.ok:
        error_msg = data.get("error") or response.text
        raise requests.HTTPError(f"Failed to detach zone: {error_msg}", response=response)

    return data

