mgc_code:
def monitor(args, watch):
    """
    reloads the script given by argv when src files changes
    """
    import os
    import sys
    import time

    script = args[0] if args else None
    if not script:
        return

    # Resolve absolute paths for watched files
    watch_paths = [os.path.abspath(p) for p in watch]

    # Initial modification times
    mtimes = {}
    for path in watch_paths:
        try:
            mtimes[path] = os.path.getmtime(path)
        except OSError:
            mtimes[path] = None

    try:
        while True:
            time.sleep(0.5)
            changed = False
            for path in watch_paths:
                try:
                    current = os.path.getmtime(path)
                except OSError:
                    current = None
                if mtimes.get(path) != current:
                    changed = True
                    break
            if changed:
                # Restart the script with the same interpreter and arguments
                os.execv(sys.executable, [sys.executable] + args)
    except KeyboardInterrupt:
        pass

