def safe_put_bulk(self, url, bulk_json):
        """ Bulk PUT controlling unicode issues """
        import json, requests
        # Prepare the payload ensuring proper Unicode handling
        if isinstance(bulk_json, (list, dict)):
            payload = json.dumps(bulk_json, ensure_ascii=False)
        else:
            payload = str(bulk_json)
        try:
            data = payload.encode('utf-8')
        except UnicodeEncodeError:
            data = payload.encode('utf-8', errors='replace')
        # Use an existing session if present, otherwise fall back to requests
        session = getattr(self, "session", None)
        if session and isinstance(session, requests.sessions.Session):
            response = session.put(url, data=data, headers={"Content-Type": "application/json"})
        else:
            response = requests.put(url, data=data, headers={"Content-Type": "application/json"})
        response.raise_for_status()
        return response

