mgc_code:
def _check_samples_nodups(fnames):
    """Ensure a set of input VCFs do not have duplicate samples.
    """
    import gzip

    seen = set()
    dup = set()
    for fname in fnames:
        open_func = gzip.open if fname.endswith('.gz') else open
        with open_func(fname, 'rt') as f:
            for line in f:
                if line.startswith('#CHROM'):
                    cols = line.rstrip('\n').split('\t')
                    samples = cols[9:]
                    for s in samples:
                        if s in seen:
                            dup.add(s)
                        else:
                            seen.add(s)
                    break
    if dup:
        raise ValueError(f"Duplicate sample(s) found: {', '.join(sorted(dup))}")

